INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C1','kor',6,2,'u6',1,'경험을 글로 표현하면 좋은 점 — 그때 내 마음이 어땠는지 또렷하게 알게 되고, 말로는 잘 안 되던 것을 다른 사람에게 생생하게 전하며, 지나가 버릴 일이 오래 남는다 (글씨를 예쁘게 쓰거나 글을 길게 늘리는 것은 좋은 점이 아니다)',ARRAY['[6국05-05]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C2','kor',6,2,'u6',1,'날마다 겪는 작은 일도 글감 — 여행이나 대단한 일이 없어도 우유갑을 여느라 씨름한 일처럼 마음이 움직인 일이면 무엇이든 글감이 되며, 글감을 고르는 물음은 「그때 내 마음이 움직였는가」 하나다',ARRAY['[6국05-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C3','kor',6,2,'u6',1,'좋은 표현은 개수가 아니라 알맞음 — 빗댄 표현을 많이 넣거나 어려운 말을 쓸수록 좋은 시가 되는 것이 아니라 그 마음에 알맞은 표현이 좋은 표현이며, 빗댄 표현이 하나뿐이거나 하나도 없는 짧고 쉬운 시도 마음이 잘 전해지면 좋은 시다',ARRAY['[6국05-02][6국05-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C4','kor',6,2,'u6',1,'이야기의 세 요소 — 인물(이야기에 나오는 사람이나 대상)·배경(일이 일어난 때와 곳)·사건(이야기 속에서 일어난 일)이 모여 이야기가 되며, 셋은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직인다',ARRAY['[6국05-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C5','kor',6,2,'u6',2,'시가 담은 경험과 장면 떠올리기 — 말하는 이가 실제로 한 일을 찾아 시가 어떤 경험을 담았는지 알고, 장면을 머릿속에 그리며 읽으며, 빗댄 말(벌써 백 번은 미끄러졌다)은 실제로 일어난 일이 아니라 말하는 이의 마음(놓칠까 걱정함)을 나타낸 것으로 읽는다',ARRAY['[6국05-02]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C6','kor',6,2,'u6',2,'겪은 일을 시로 옮기는 일 — 겪은 일을 전부 쓰지 않고 인상 깊었던 부분만 고르고, 장면이 바뀔 때 연과 행을 나누고, 마음을 다른 사물이나 비슷한 상황에 빗대고, 본 것·들은 것·만진 것을 그대로 살린다',ARRAY['[6국05-02]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C7','kor',6,2,'u6',2,'비유적 표현과 빗댄 까닭 — 비슷한 점이 있는 두 대상을 이어 나타내는 것을 비유적 표현이라 하며, 빗댈 때에는 반드시 비슷한 점이 있어(아침 집 = 끓는 주전자: 바쁘고 뜨거운 기운 · 낮 집 = 빈 운동장: 텅 빔 · 저녁 집 = 난롯가: 따뜻하게 둘러앉음) 그 점을 말로 옮길 수 있어야 한다',ARRAY['[6국05-02]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C8','kor',6,2,'u6',2,'직유법과 은유법 — 직유법은 「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법(주전자처럼 끓는다)이고, 은유법은 「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법(낮 우리 집은 빈 운동장이다)이다',ARRAY['[6국05-02]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C9','kor',6,2,'u6',2,'감각적 표현 — 보고·듣고·맡고·만지고·맛본 것을 그대로 살려 쓴 표현으로(들은 것 — 김이 푹푹 · 본 것 — 시계 초침), 다른 것에 빗대는 비유적 표현과 달리 느낀 감각을 그대로 옮겨 장면을 생생하게 한다',ARRAY['[6국05-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C10','kor',6,2,'u6',2,'시의 특성은 규칙이 아니라 방법 — 연과 행으로 나누어 노래하는 듯한 리듬이 느껴지고, 생각이나 느낌을 짧은 글로 눌러 담으며, 비유적 표현과 감각적 표현으로 대상을 생생하게 나타내지만, 이 셋은 지켜야 할 규칙이 아니라 쓸 수 있는 방법이다',ARRAY['[6국05-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C11','kor',6,2,'u6',4,'시 쓰기 준비와 묻고 답하기 — 시로 쓸 경험 고르기 → 묻고 답하며 자세히 떠올리기 → 생각그물로 모으기 → 남길 것과 버릴 것 고르기의 차례로 준비하며, 「가장 기억에 남는 순간은? · 그때 본 것과 들은 것은? · 무엇에 빗댈 수 있을까? · 마음이 어떻게 움직였나?」처럼 그 경험 속으로 다시 들어가게 하는 물음이 기억을 또렷하게 한다',ARRAY['[6국05-05]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C12','kor',6,2,'u6',4,'생각그물로 갈래 나누어 모으기 — 가운데에 경험을 두고 둘레에 본 것(지나가는 줄)·들은 것(탁, 탁 소리)·만진 것(미끄러운 손잡이)·생각이나 느낌(드디어 되었다)·빗댈 것(떠 있는 몸 → 새)을 갈래별로 적어 두면 시로 옮기기 쉬워진다',ARRAY['[6국05-05]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C13','kor',6,2,'u6',4,'시는 넣는 일보다 버리는 일 — 생각그물을 다 넣으면 빠뜨린 것은 없어도 어느 순간이 중요한지 알 수 없는 목록이 되고, 인상 깊은 순간만 골라 남기면 그 마음이 또렷해진다 (짧아서 좋은 것이 아니라 고르고 버려서 또렷해진 것이다)',ARRAY['[6국05-05]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C14','kor',6,2,'u6',4,'마음이 드러나는 제목 — 제목은 겪은 일 그대로(줄넘기를 한 날)·가장 인상 깊은 것으로·빗댄 표현으로(백한 번째 새) 붙일 수 있고, 맨 처음에 붙여도 다 쓴 뒤에 붙여도 되지만 시를 읽고 나서 고개가 끄덕여지게 시에 담긴 마음이 드러나면 좋다',ARRAY['[6국05-05]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C15','kor',6,2,'u6',4,'시 고쳐 쓰기 — 다 쓴 시는 전하려던 마음이 드러나는가 · 장면이 바뀌는 곳에서 연이 나뉘었는가 · 없어도 되는 줄이 남아 있지 않은가 · 소리 내어 읽었을 때 걸리는 곳이 없는가를 보며 고치고, 고쳐 쓰기는 벌이 아니라 시를 자라게 하는 단계다 (빗댄 표현의 개수나 글씨 모양은 볼 것이 아니다)',ARRAY['[6국05-05]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C16','kor',6,2,'u6',6,'낭송 계획 — 마음에 맞는 목소리와 속도 — 듣는 사람에게 꼭 전하고 싶은 마음을 먼저 정하고, 그 마음에 맞게 부분마다 목소리와 속도를 정하며(숨을 참듯 낮고 느리게 · 또렷하고 빠르게 · 한 음절씩 힘을 실어 천천히), 여러 번 연습해 걸리는 곳을 고친다 — 목소리는 그 부분의 마음을 따라간다',ARRAY['[6국03-06]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C17','kor',6,2,'u6',6,'효과음 · 배경 음악 · 영상은 돕는 만큼 — 효과음은 시의 장면과 맞닿은 소리를 아주 짧게, 배경 음악은 시의 분위기와 어울리는 것을 낭송하는 목소리보다 작게, 영상이나 그림은 장면을 떠올리는 데 도움이 될 만큼만 쓰며, 셋 다 낭송을 돕는 것이지 대신하거나 덮는 것이 아니다',ARRAY['[6국03-06]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C18','kor',6,2,'u6',6,'낭송을 듣는 사람과 구체적인 조언 — 낭송회는 낭송하는 사람과 듣는 사람이 함께 만들어, 듣는 사람은 낭송하는 사람을 바라보며 시와 관련 있는 내 경험을 떠올리며 듣고, 끝난 뒤 「잘했어」가 아니라 어느 부분을 어떻게 하면 좋을지까지 말해 준다',ARRAY['[6국03-06]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C19','kor',6,2,'u6',6,'낭송을 잘한다는 것 — 들리지 않을 만큼 읽어도, 마음과 상관없이 무조건 크게 읽어도, 음악과 영상으로 화려하게 꾸며도 안 되고, 뒤에 앉은 사람까지 들릴 만큼 부분마다 마음에 맞는 크기로 읽어 멋있게 들리는 것이 아니라 그 시의 마음이 건너가게 하는 것이다',ARRAY['[6국03-06]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C20','kor',6,2,'u6',7,'패러디와 표절 — 널리 알려진 이야기를 원래 이야기를 밝히고 일부러 비틀어 바뀐 곳에서 새로운 뜻이 생기게 하는 것이 패러디이고, 남의 것을 그대로 옮기고 자기 것인 척해 새로운 뜻이 생기지 않는 것이 표절이다',ARRAY['[6국05-05]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C21','kor',6,2,'u6',7,'성격이 바뀌면 하는 일이 바뀐다 — 「금도끼 은도끼」의 나무꾼은 제 것이 아닌 것을 제 것이라 하지 않고 주는 것을 고맙게 받지만, 「마르지 않는 샘」의 나무꾼은 받기 전에 마을에 무슨 일이 생길지 먼저 생각해 상을 거절하듯, 인물의 성격이 바뀌면 그 인물이 하는 일도 바뀐다',ARRAY['[6국05-05]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C22','kor',6,2,'u6',7,'배경이 바뀌면 할 수 있는 일이 바뀐다 — 그저 「옛날」이던 때를 「몇 해째 비가 오지 않아 우물이 말라 가던 해」로 바꾸자 나무꾼이 물을 걱정하는 것이 자연스러워졌듯, 때와 곳을 바꾸면 인물이 할 수 있는 일과 일어날 사건이 함께 달라진다',ARRAY['[6국05-05]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C23','kor',6,2,'u6',7,'앞의 일이 뒤의 일을 부른다 — 이야기는 바뀌어도 원인과 결과로 이어져야 해서(가뭄이 든 해였으므로 → 물을 먼저 걱정했고 → 그래서 상을 거절했고 → 그래서 샘이 생겼다) 이어 쓸 때에도 앞에서 생긴 일이 뒤의 일을 불러오게 쓴다',ARRAY['[6국05-05]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C24','kor',6,2,'u6',7,'잘 바꾼 이야기는 많이 바꾼 이야기가 아니다 — 갑자기 우주선이 내려오는 것처럼 놀랍기만 하고 앞의 일과 이어지지 않는 바꾸기는 잘 바꾼 것이 아니며, 바꾸어 쓰기는 기발한 생각을 얼마나 많이 넣었는가가 아니라 바뀐 것에 따라 뒤가 자연스럽게 이어지는가로 가늠한다',ARRAY['[6국05-05]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C25','kor',6,2,'u6',7,'바꾸어 쓸 때 생각할 점과 경험 — 인물을 어떤 성격으로 · 때와 곳을 어떻게 바꿀지 · 앞의 일이 뒤의 일을 부르는지 · 내가 잘 아는 경험을 살릴 수 있는지를 생각하며, 경험을 바탕으로 쓴 이야기는 실제로 있었던 일만 적는 일기와 달리 겪은 일에서 출발하되 인물·배경·사건을 지어낸다 (겪어 본 것에서 출발하면 더 자세히 쓸 수 있다)',ARRAY['[6국05-05]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C26','kor',6,2,'u6',9,'바꾸어 쓰면 새로운 뜻이 생긴다 — 「정직하면 상을 받는다」던 이야기가 상을 거절하고 마을에 샘이 생기는 이야기로 바뀌면 「정직함은 나 혼자의 일이 아니다」라는 새로운 뜻이 생기며, 그것이 이야기를 바꾸어 쓰는 까닭이다',ARRAY['[6국05-05]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C27','kor',6,2,'u6',9,'인물의 성격과 사건의 차례 정리하기 — 인물의 성격은 그 인물이 한 말과 행동에서 드러나고(놀라지 않은 척 둘러대는 토끼 · 혼자 뭍까지 올라간 자라 · 들은 말을 그대로 믿는 용왕), 사건은 보통 발단(일이 시작됨)·전개(일이 커짐)·절정(가장 긴장되는 순간)을 거쳐 마지막에 일이 마무리되는 차례로 흘러가므로, 바꾸기 전에 이 둘을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보인다',ARRAY['[6국05-05]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C28','kor',6,2,'u6',9,'바꾸기 계획 — 하나를 바꾸면 함께 손볼 곳 — 인물·배경·사건 가운데 하나만 골라 바꾸어도 충분하며(나머지가 따라 움직이므로), 바꿀 것 · 그 때문에 달라지는 것 · 그대로 둘 것을 적고, 성격을 바꾸었으면 행동도 함께 바꾸어야 한다 (자라가 따져 보는 성격이 되면 토끼에게 하는 말 · 토끼의 행동 · 이야기의 끝이 함께 바뀐다)',ARRAY['[6국05-05]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C29','kor',6,2,'u6',9,'바꾼 이야기의 첫 문장과 제목 — 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 읽는 사람이 금방 알아채고, 제목은 새로 바꾼 인물의 성격·배경·사건이 드러나게 붙이며(「자라가 입을 열었다」), 맨 처음에 붙여도 다 쓴 뒤에 붙여도 된다',ARRAY['[6국05-05]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C30','kor',6,2,'u6',9,'칭찬 쪽지 — 어느 부분이 왜 — 글은 읽어 주는 사람이 있을 때 완성되며, 친구의 이야기를 읽고 「잘 썼어 · 재미있어」에서 멈추지 않고 어느 부분이 좋았는지 짚고 왜 좋았는지 까닭을 붙여 쓴다 (글씨처럼 이야기와 상관없는 겉모습만 칭찬하지 않는다)',ARRAY['[6국03-06]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C31','kor',6,2,'u6',12,'책의 형태와 독자 — 종이책(교실에 두고 아무 때나 넘겨 봄)·소리로 담는 책(낭송의 목소리와 속도를 그대로 남김)·화면으로 보는 책(멀리 있는 사람에게도 보냄)은 더 나은 것 없이 알맞은 자리가 서로 다를 뿐이고, 누가 읽을지와 무엇을 전하고 싶은지를 먼저 정하면 형태가 따라 정해진다',ARRAY['[6국03-06]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C32','kor',6,2,'u6',12,'실을 글을 쓰기 전에 정할 것 — 중심 사건 · 등장인물의 이름과 성격 · 일이 일어난 때와 곳 · 사건이 이어지는 차례를 정해 두면 글이 빨리 써지며, 겪은 일에서 출발하되 일기를 옮겨 적는 것이 아니라 인물과 배경을 지어내도 된다 (표지 색이나 글자 수는 먼저 정할 것이 아니다)',ARRAY['[6국03-06]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C33','kor',6,2,'u6',12,'꾸미기가 이야기를 덮지 않게 함께 만들기 — 이야기를 먼저 완성하고 꾸미기는 읽기 좋게 돕는 만큼만 하며, 함께 만들 때에는 누구와 · 무엇을 맡을지 · 언제까지를 정하고 다 만든 뒤 글에서 잘한 점부터 이야기한다 — 목적은 멋진 결과물이 아니라 쓰고 나누는 즐거움을 겪어 보는 것',ARRAY['[6국03-06]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C34','kor',6,2,'u6',12,'소리가 같고 뜻이 다른 낱말 — 읽을 때 소리는 같지만 쓰는 글자와 뜻이 다른 낱말(바치다 = 웃어른께 정중히 올리다 · 받치다 = 밑에서 괴어 기울지 않게 하다 / 메다 = 어깨에 걸쳐 지다 · 매다 = 끈이나 줄을 묶다 / 부치다 = 편지나 물건을 보내다 · 붙이다 = 맞닿아 떨어지지 않게 하다)은 앞뒤 문장을 보고 쓰이는 자리에 맞게 골라 쓴다 (기초 다지기)',ARRAY['기초 다지기 — 소리가 같고 뜻이 다른 낱말(단원 성취기준 표기 없음)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C35','kor',6,2,'u6',1,'「눈꺼풀」(오지연) — 점심 먹고 축구를 한 뒤 5교시 도덕 시간에 졸음이 쏟아진 경험 · 「꾸벅 꾸우벅」(졸려서 눈이 감기는 모습) · 「세상에서 가장 무거운 풀」(깨려 해도 잘 떠지지 않는 눈꺼풀)',ARRAY['[6국05-05]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C36','kor',6,2,'u6',2,'「그때부터였나 봐」(임수현) — 축구공을 차며 골대로 뛰어가는 수빈이를 본 뒤 자꾸 수빈이가 생각나는 경험 · 축구공이 굴러온다(수빈이 모습이 떠오름) · 축구공이 수북이 쌓였어(점점 커져 가는 마음) · 이미지 카드 · 경험을 쓴 글과 견주기',ARRAY['[6국05-02]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C37','kor',6,2,'u6',2,'「오늘 날씨는」(양슬기) — 오늘 전학 온 말하는 이 · 소나기(수다스러운 친구)·첫눈(수줍음이 많은 친구)·번개(장난기 많은 친구)·천둥(목소리가 큰 친구) · 빗댄 까닭(비슷한 점)',ARRAY['[6국05-02]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C38','kor',6,2,'u6',7,'「알라딘과 요술 램프」(글 ㉮) — 가짜 삼촌을 믿은 까닭 · 램프를 먼저 주지 않아 동굴에 갇힘 · 반지 요정 · 옷자락으로 먼지를 닦아 램프의 요정을 부름 · 먹을 것과 보물을 소원으로 빎',ARRAY['[6국05-05]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C39','kor',6,2,'u6',7,'「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) — 보물을 거절함 · 지니가 권한 소원 거절 · 전쟁을 없애고 무기를 사라지게 하는 소원 · 두 글의 인물 성격(지혜롭지만 욕심이 많음/이타적이고 욕심이 없음 · 맡은 일을 충실히 해냄/성질이 급하고 지기 싫어함)·배경·사건 비교',ARRAY['[6국05-05]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C40','kor',6,2,'u6',9,'「옹고집전」 — 심술궂은 옹고집의 성격과 그 까닭 · 인물 관계(어머니·부인·가짜 옹고집·도사·사또) · 발단·전개·절정·결말(걸인을 내쫓음 → 가짜 옹고집 → 재판과 쫓겨남 → 뉘우치고 착하게 삶)',ARRAY['[6국05-05]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C41','kor',6,2,'u6',9,'작품 속 낱말 — 탄식하다(한탄하여 한숨을 쉬다) · 아뢰다(다른 사람에게 말씀드려서 알리다) · 괴이쩍다(별나고 괴상한 느낌이 있다) · 극진하다(어떤 대상에게 정성을 다하는 태도가 있다) · 동냥·곤욕·첩첩산중·개과천선 · 왕자 비·착취하다·성인군자',ARRAY['[6국05-05]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C42','kor',6,2,'u6',12,'「양말 한 짝」(김세희, 마무리) — 양말 한 짝이 사라진 경험 · 세탁기에서 「꼬물꼬물」 나옴 · 기회를 틈타 사라짐 · 한 짝만 사라져도 두 짝 다 사라진 것',ARRAY['[6국05-02][6국05-05]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X01','kor',6,'u6',ARRAY['K6-2-u6-C1']::text[],'경험을 글로 쓰는 좋은 점을 글씨를 예쁘게 쓰기 · 글을 길게 늘리기 같은 겉모습에서 찾는다','나에게, 읽는 사람에게 무엇이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X02','kor',6,'u6',ARRAY['K6-2-u6-C2','K6-2-u6-C25']::text[],'여행이나 대단한 일을 겪어야 글감이 된다고 여겨, 날마다 겪는 작은 일을 글감으로 보지 않는다','그때 마음이 움직였는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X03','kor',6,'u6',ARRAY['K6-2-u6-C3','K6-2-u6-C7','K6-2-u6-C10']::text[],'빗댄 표현을 많이 넣을수록 좋은 시라고 여긴다','개수가 아니라 그 마음에 알맞은가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X04','kor',6,'u6',ARRAY['K6-2-u6-C3','K6-2-u6-C10']::text[],'어렵고 멋있어 보이는 말을 쓸수록 좋은 시라고 여긴다','짧고 쉬운 말도 좋은 시가 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X05','kor',6,'u6',ARRAY['K6-2-u6-C4','K6-2-u6-C27']::text[],'인물 · 배경 · 사건의 뜻을 서로 헷갈린다','누가 · 언제 어디서 · 무슨 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X06','kor',6,'u6',ARRAY['K6-2-u6-C4','K6-2-u6-C21','K6-2-u6-C22']::text[],'이야기의 세 요소가 따로 움직인다고 여겨, 하나를 바꾸어도 나머지는 그대로라고 생각한다','하나를 바꾸면 나머지도 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X07','kor',6,'u6',ARRAY['K6-2-u6-C5']::text[],'시가 담은 경험을 말하는 이가 실제로 한 일에서 찾지 않고 시에 없는 사건으로 짐작한다','말하는 이가 실제로 한 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X08','kor',6,'u6',ARRAY['K6-2-u6-C5','K6-2-u6-C7']::text[],'빗댄 말을 실제로 일어난 일로 읽어, 그 말이 나타낸 마음을 놓친다','실제 일인가, 마음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X09','kor',6,'u6',ARRAY['K6-2-u6-C6','K6-2-u6-C13']::text[],'겪은 일을 시로 옮길 때 하나도 빠뜨리지 않고 차례대로 다 적어야 한다고 여긴다','인상 깊은 부분만 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X10','kor',6,'u6',ARRAY['K6-2-u6-C7']::text[],'빗댄 두 대상 사이의 비슷한 점을 찾지 못하거나, 비슷한 점이 없는 것끼리 아무렇게나 빗댄다','어떤 점에서 닮았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X11','kor',6,'u6',ARRAY['K6-2-u6-C8']::text[],'직유법과 은유법을 서로 헷갈린다','「처럼 · 같이 · 듯이」가 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X12','kor',6,'u6',ARRAY['K6-2-u6-C9','K6-2-u6-C12']::text[],'감각적 표현과 비유적 표현을 헷갈리거나, 본 것 · 들은 것 · 만진 것을 갈래대로 가르지 못한다','느낀 그대로? 다른 것에 빗댐?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X13','kor',6,'u6',ARRAY['K6-2-u6-C10','K6-2-u6-C3']::text[],'연과 행 · 비유 같은 시의 특성을 꼭 지켜야 할 규칙으로 여겨, 빗댄 표현이 없으면 시가 아니라고 생각한다','규칙이 아니라 쓸 수 있는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X14','kor',6,'u6',ARRAY['K6-2-u6-C6','K6-2-u6-C15']::text[],'장면이 바뀌어도 연을 나누지 않거나, 장면과 상관없이 아무 데서나 연과 행을 나눈다','장면이 바뀌는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X15','kor',6,'u6',ARRAY['K6-2-u6-C11']::text[],'경험을 자세히 떠올리는 물음 대신 몇 시 몇 분 · 몇 줄로 쓸지 같은 겉 물음을 고른다','그 경험 속으로 다시 들어가게 하는 물음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X16','kor',6,'u6',ARRAY['K6-2-u6-C12','K6-2-u6-C13']::text[],'생각그물에 모은 것을 다 넣어야 빠짐없는 좋은 시가 된다고 여긴다','넣는 일보다 버리는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X17','kor',6,'u6',ARRAY['K6-2-u6-C13']::text[],'고른 시가 더 나은 까닭을 「짧아서 · 빗댄 표현이 많아서」로 여겨, 고르고 버려서 마음이 또렷해진 것을 보지 못한다','읽고 나서 무엇이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X18','kor',6,'u6',ARRAY['K6-2-u6-C14','K6-2-u6-C29']::text[],'제목을 담긴 마음이나 바뀐 것과 상관없이 붙이거나, 제목은 반드시 맨 처음에 정해야 한다고 여긴다','읽고 나서 고개가 끄덕여지는 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X19','kor',6,'u6',ARRAY['K6-2-u6-C15']::text[],'시를 고쳐 쓸 때 빗댄 표현의 개수나 글씨 모양 같은 겉모습을 보거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','전하려던 마음 · 연 · 없어도 되는 줄 · 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X20','kor',6,'u6',ARRAY['K6-2-u6-C16']::text[],'전할 마음을 정하지 않고 낭송하거나, 시의 모든 부분을 같은 목소리와 속도로 읽는다','목소리는 그 부분의 마음을 따라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X21','kor',6,'u6',ARRAY['K6-2-u6-C19','K6-2-u6-C16']::text[],'낭송을 잘한다는 것을 마음과 상관없이 무조건 크게 읽는 것으로 여긴다','크게가 아니라 마음에 맞는 크기로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X22','kor',6,'u6',ARRAY['K6-2-u6-C17','K6-2-u6-C19']::text[],'효과음 · 배경 음악 · 영상을 많이, 크게, 화려하게 쓸수록 낭송이 좋아진다고 여긴다','돕는 만큼만, 목소리보다 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X23','kor',6,'u6',ARRAY['K6-2-u6-C19']::text[],'마음만 담으면 들리지 않을 만큼 작게 읽어도 괜찮다고 여긴다','뒤에 앉은 사람까지 들리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X24','kor',6,'u6',ARRAY['K6-2-u6-C18']::text[],'친구의 낭송을 들을 때 옆 친구와 이야기하거나 틀린 글자만 찾는 것을 잘 듣는 것으로 여긴다','바라보며, 내 경험을 떠올리며') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X25','kor',6,'u6',ARRAY['K6-2-u6-C18','K6-2-u6-C30']::text[],'조언이나 칭찬을 「잘했어 · 재미있어」처럼 어느 부분이 왜 그런지 없이 막연하게 하거나, 글씨 같은 겉모습만 칭찬한다','어느 부분을 · 왜 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X26','kor',6,'u6',ARRAY['K6-2-u6-C20']::text[],'패러디와 표절을 같은 것으로 여기거나, 원래 이야기를 밝히지 않고 그대로 옮겨도 패러디라고 생각한다','밝히고 일부러 바꾸어 새 뜻이 생기나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X27','kor',6,'u6',ARRAY['K6-2-u6-C21','K6-2-u6-C28']::text[],'인물의 성격을 바꾸어 놓고 그 인물의 말과 행동은 그대로 둔다','성격이 바뀌면 하는 일도 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X28','kor',6,'u6',ARRAY['K6-2-u6-C22']::text[],'배경을 바꾼 것이 인물이 할 수 있는 일이나 사건과 어떻게 이어지는지 보지 못한다','그 때와 곳이라서 할 수 있는 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X29','kor',6,'u6',ARRAY['K6-2-u6-C23','K6-2-u6-C24']::text[],'앞의 일과 이어지지 않는 갑작스러운 사건(하늘에서 우주선이 내려옴 · 갑자기 병이 나음)을 이어 쓴다','앞의 일이 뒤의 일을 부르나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X30','kor',6,'u6',ARRAY['K6-2-u6-C24']::text[],'많이 · 놀랍게 · 기발하게 바꿀수록 잘 바꾼 이야기라고 여긴다','놀라움이 아니라 이어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X31','kor',6,'u6',ARRAY['K6-2-u6-C25','K6-2-u6-C32']::text[],'경험을 바탕으로 쓴 이야기를 일기처럼 겪은 일 그대로만 써야 한다고 여기거나, 반대로 일기에 지어낸 일을 적어도 된다고 여긴다','일기는 사실, 이야기는 지어냄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X32','kor',6,'u6',ARRAY['K6-2-u6-C26']::text[],'이야기를 바꾸어 쓰는 까닭을 글을 길게 늘리기나 재미만으로 여겨, 바뀐 곳에서 새로운 뜻이 생기는 것을 모른다','바꾸면 무엇이 생기나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X33','kor',6,'u6',ARRAY['K6-2-u6-C27']::text[],'인물의 성격을 그 인물이 한 말과 행동과 잇지 못한다','그 인물이 실제로 한 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X34','kor',6,'u6',ARRAY['K6-2-u6-C27']::text[],'발단 · 전개 · 절정의 차례와 각 단계에서 일어나는 일을 헷갈린다','시작 · 커짐 · 가장 긴장되는 순간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X35','kor',6,'u6',ARRAY['K6-2-u6-C28']::text[],'하나를 바꾸어도 다른 곳은 손볼 필요가 없다고 여기거나, 이야기와 상관없는 글자 수 · 공간 같은 것을 손볼 곳으로 고른다','바꾼 것에 닿아 있던 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X36','kor',6,'u6',ARRAY['K6-2-u6-C28','K6-2-u6-C24']::text[],'인물 · 배경 · 사건을 모두 한꺼번에 바꾸어야 제대로 바꾼 것이라고 여긴다','하나만 바꾸어도 충분해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X37','kor',6,'u6',ARRAY['K6-2-u6-C29']::text[],'바꾼 이야기의 첫 문장을 바뀐 것과 상관없이 원래 이야기 그대로 시작해, 읽는 사람이 무엇이 바뀌었는지 알아채기 어렵게 한다','바뀐 것이 드러나는 곳에서 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X38','kor',6,'u6',ARRAY['K6-2-u6-C31']::text[],'책의 형태에 등수를 매기거나, 가장 새롭고 멋있어 보이는 형태 · 가장 빨리 끝나는 형태를 고른다','더 나은 형태는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X39','kor',6,'u6',ARRAY['K6-2-u6-C31']::text[],'누가 읽을지와 무엇을 전하고 싶은지를 정하지 않고 책의 형태부터 고른다','독자가 정해지면 형태가 따라와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X40','kor',6,'u6',ARRAY['K6-2-u6-C32']::text[],'글을 쓰기 전에 정할 것을 표지 색깔 · 글자 수 같은 겉모습에서 찾는다','중심 사건 · 인물 · 때와 곳 · 차례') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X41','kor',6,'u6',ARRAY['K6-2-u6-C33']::text[],'표지와 그림이 화려한 것을 잘한 것으로 여겨 꾸미기에 시간을 다 쓰고 글은 급히 쓴다','이야기가 먼저, 꾸미기는 돕는 만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X42','kor',6,'u6',ARRAY['K6-2-u6-C33']::text[],'함께 만들 때 누가 무엇을 언제까지 맡을지 정하지 않거나, 다 만든 뒤 잘한 점이 아니라 고칠 점부터 말한다','누구와 · 무엇을 · 언제까지 · 잘한 점부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X43','kor',6,'u6',ARRAY['K6-2-u6-C34']::text[],'소리가 같은 낱말(바치다 · 받치다, 메다 · 매다, 부치다 · 붙이다)을 앞뒤 문장의 뜻과 상관없이 섞어 쓴다','앞뒤 문장을 보고 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X44','kor',6,'u6',ARRAY['K6-2-u6-C5','K6-2-u6-C36']::text[],'시를 한 가지 뜻으로만 읽어야 한다고 여겨, 시 안의 말로 뒷받침되는 다른 풀이(「그때부터였나 봐」를 좋아하는 마음으로도, 축구하고 싶은 마음으로도 읽기)를 틀렸다고 여긴다','시 안의 말이 뒷받침하면 다른 풀이도 열려 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X45','kor',6,'u6',ARRAY['K6-2-u6-C21','K6-2-u6-C39']::text[],'이야기에서 인물의 성별이 바뀐 것을 성격이 달라진 까닭으로 여겨, 인물이 한 말과 선택에서 성격을 찾지 않는다','성격은 그 인물이 한 말과 선택에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X46','kor',6,'u6',ARRAY['K6-2-u6-C25','K6-2-u6-C23']::text[],'이야기를 바꾸어 쓸 때 생각할 것을 인물·배경·사건이나 원인과 결과가 아니라 주장과 근거 같은 다른 갈래 글의 요소에서 찾는다','이야기는 인물·배경·사건, 그리고 원인과 결과') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X47','kor',6,'u6',ARRAY['K6-2-u6-C16','K6-2-u6-C19']::text[],'시를 낭송할 때 글자를 하나씩 끊어 읽어, 시의 분위기에 맞는 리듬을 살리지 않는다','연과 행의 리듬을 살려 이어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X48','kor',6,'u6',ARRAY['K6-2-u6-C25','K6-2-u6-C28']::text[],'이야기에 담을 경험은 직접 겪은 일만 된다고 여겨, 읽거나 들은 간접 경험은 쓸 수 없다고 생각한다','읽고 들은 것도 경험이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X49','kor',6,'u6',ARRAY['K6-2-u6-C41']::text[],'작품에 나온 낱말(탄식하다·아뢰다·괴이쩍다·극진하다·동냥·곤욕·첩첩산중·개과천선·착취하다·성인군자)의 뜻을 서로 엇갈리게 안다','뜻풀이를 문장에 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X50','kor',6,'u6',ARRAY['K6-2-u6-C40','K6-2-u6-C27']::text[],'작품 속 인물이 누구이고 누가 무엇을 했는지(누가 누구를 불렀는지·누가 가짜를 만들었는지·누구와 싸웠는지)를 서로 엇갈리게 안다','누가 · 누구에게 · 무엇을 했나 다시 찾아봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#1','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C35',1,'mc','auto','「눈꺼풀」에서 말하는 이는 도덕 시간 전에 무엇을 했나요?',ARRAY['K6-2-u6-X07','K6-2-u6-X08']::text[],false,'{"seq":1,"concept":"K6-2-u6-C35","difficulty":1,"kind":"mc","stem":"「눈꺼풀」에서 말하는 이는 도덕 시간 전에 무엇을 했나요?","options":[{"t":"축구를 했다","correct":true},{"t":"낮잠을 잤다","mis":"K6-2-u6-X07"},{"t":"도덕 공부를 미리 했다","mis":"K6-2-u6-X07"},{"t":"풀밭에서 풀을 뽑았다","mis":"K6-2-u6-X08"}],"explanation":["시의 첫머리에 점심을 먹고 신나게 한 일이 나와요.","말하는 이는 축구를 한판 뛰었어요.","그 뒤 5교시 도덕 시간에 졸음이 쏟아졌어요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#2','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C35',1,'mc','auto','「눈꺼풀」의 “꾸벅 꾸우벅”은 어떤 모습을 나타내는 말인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":2,"concept":"K6-2-u6-C35","difficulty":1,"kind":"mc","stem":"「눈꺼풀」의 “꾸벅 꾸우벅”은 어떤 모습을 나타내는 말인가요?","options":[{"t":"졸려서 눈이 감기고 고개가 숙여지는 모습","correct":true},{"t":"웃어른께 인사를 드리는 모습","mis":"K6-2-u6-X08"},{"t":"밥을 맛있게 먹는 모습","mis":"K6-2-u6-X07"},{"t":"축구공이 튀어 오르는 모습","mis":"K6-2-u6-X07"}],"explanation":["“꾸벅 꾸우벅”은 도덕 시간 장면에 나와요.","축구를 하고 난 뒤라 졸음이 쏟아지는 때예요.","졸려서 눈이 감기는 모습을 흉내 낸 말이에요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#3','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C35',1,'sa','auto','「눈꺼풀」에서 “세상에서 가장 무거운 풀”은 무엇을 가리키나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C35","difficulty":1,"kind":"sa","stem":"「눈꺼풀」에서 “세상에서 가장 무거운 풀”은 무엇을 가리키나요? 세 글자로 쓰세요.","answer":["눈꺼풀"],"explanation":["제목을 함께 떠올려 보아요.","졸릴 때 소리 없이 내려오는 것은 눈꺼풀이에요.","깨려고 해도 잘 떠지지 않아 「가장 무거운 풀」이라고 했어요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"},"mis":"K6-2-u6-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#4','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C1',1,'ox','auto','경험을 시나 이야기로 표현하면 그 경험을 오랫동안 생생하게 기억할 수 있어요.',ARRAY['K6-2-u6-X01']::text[],false,'{"seq":4,"concept":"K6-2-u6-C1","difficulty":1,"kind":"ox","stem":"경험을 시나 이야기로 표현하면 그 경험을 오랫동안 생생하게 기억할 수 있어요.","answer":"O","reason_options":[{"t":"겪은 일과 그때의 마음을 글로 남겨 두기 때문에","correct":true},{"t":"글씨를 바르게 쓰는 연습이 되기 때문에","mis":"K6-2-u6-X01"}],"mis":"K6-2-u6-X01","explanation":["『국어』 257쪽 3번에서 친구가 말한 좋은 점이에요.","경험과 마음을 글로 남기면 오래 기억할 수 있어요.","글씨 연습은 경험을 표현하는 좋은 점이 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 재미있게 표현할 수 있어."},{"who":"친구 2","text":"오랫동안 생생하게 기억할 수 있어."},{"who":"친구 3","text":"경험하면서 느낀 내 마음을 다른 사람들에게 잘 전달할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#5','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C35',2,'mc','auto','「눈꺼풀」은 어떤 경험을 시로 표현했나요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C35","difficulty":2,"kind":"mc","stem":"「눈꺼풀」은 어떤 경험을 시로 표현했나요?","options":[{"t":"점심 먹고 축구를 한 뒤 수업 시간에 졸음이 쏟아졌던 경험","correct":true},{"t":"도덕 시간에 풀밭에 나가 무거운 풀을 옮긴 경험","mis":"K6-2-u6-X08"},{"t":"축구 시합에서 이겨 상을 받은 경험","mis":"K6-2-u6-X07"},{"t":"힘센 친구와 팔씨름을 한 경험","mis":"K6-2-u6-X08"}],"explanation":["말하는 이는 축구를 한판 뛰고 도덕 시간을 맞았어요.","눈꺼풀이 자꾸 내려오는 모습을 풀에 빗대었어요.","수업 시간에 졸렸던 경험을 재미있게 표현한 시예요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#6','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C1',2,'mc','auto','『국어』 257쪽 3번에서 친구들이 말한, 경험을 시나 이야기로 표현하면 좋은 점은 무엇인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X02','K6-2-u6-X04']::text[],false,'{"seq":6,"concept":"K6-2-u6-C1","difficulty":2,"kind":"mc","stem":"『국어』 257쪽 3번에서 친구들이 말한, 경험을 시나 이야기로 표현하면 좋은 점은 무엇인가요?","options":[{"t":"경험하면서 느낀 내 마음을 다른 사람들에게 잘 전달할 수 있다","correct":true},{"t":"글을 길게 늘이는 연습을 할 수 있다","mis":"K6-2-u6-X01"},{"t":"대단한 일을 겪은 사람만 쓸 수 있어 자랑이 된다","mis":"K6-2-u6-X02"},{"t":"어려운 말을 많이 쓸 수 있다","mis":"K6-2-u6-X04"}],"explanation":["경험을 재미있게 표현할 수 있어요.","오랫동안 생생하게 기억할 수 있어요.","느낀 마음을 다른 사람에게 잘 전할 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#7','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C2',2,'mc','auto','시나 이야기로 표현할 경험에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X09']::text[],false,'{"seq":7,"concept":"K6-2-u6-C2","difficulty":2,"kind":"mc","stem":"시나 이야기로 표현할 경험에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"수업 시간에 졸렸던 일처럼 날마다 겪는 일도 좋은 글감이 된다","correct":true},{"t":"여행처럼 특별한 일만 글감이 된다","mis":"K6-2-u6-X02"},{"t":"남에게 자랑할 만한 일만 글감이 된다","mis":"K6-2-u6-X02"},{"t":"겪은 일은 하나도 빠짐없이 다 써야 한다","mis":"K6-2-u6-X09"}],"explanation":["「눈꺼풀」은 수업 시간에 졸렸던 일을 썼어요.","특별한 일이 아니어도 좋은 글감이 돼요.","일상의 경험에 대한 생각이나 느낌을 솔직하게 쓰면 돼요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#8','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',2,'mc','auto','이 단원에서 이야기를 바꾸어 쓸 때 살펴볼 이야기의 세 가지 요소는 무엇인가요?',ARRAY['K6-2-u6-X46','K6-2-u6-X05']::text[],false,'{"seq":8,"concept":"K6-2-u6-C4","difficulty":2,"kind":"mc","stem":"이 단원에서 이야기를 바꾸어 쓸 때 살펴볼 이야기의 세 가지 요소는 무엇인가요?","options":[{"t":"인물, 배경, 사건","correct":true},{"t":"주장, 이유, 근거","mis":"K6-2-u6-X46"},{"t":"처음, 가운데, 끝","mis":"K6-2-u6-X05"},{"t":"제목, 글쓴이, 쪽수","mis":"K6-2-u6-X05"}],"explanation":["『국어』 280쪽에서 이야기의 세 가지 요소를 살펴봐요.","이야기의 세 가지 요소는 인물, 배경, 사건이에요.","주장, 이유, 근거는 주장하는 글을 살필 때 쓰는 말이에요."],"asset":{"type":"passage","lines":["1. 시 창작하기","• 시의 특성을 생각하며 시 감상하기","• 시의 특성을 생각하며 시 창작하기","• 시 낭송하기","2. 이야기로 표현하기","• 경험을 떠올리며 이야기를 바꾸어 쓰는 방법 알기","• 이야기 바꾸어 쓰기"],"numbered":false,"title":"이 단원에서는 배워요 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#9','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C35',2,'ox','auto','「눈꺼풀」의 말하는 이는 도덕 시간에 정말로 풀밭에 누워 있었어요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":9,"concept":"K6-2-u6-C35","difficulty":2,"kind":"ox","stem":"「눈꺼풀」의 말하는 이는 도덕 시간에 정말로 풀밭에 누워 있었어요.","answer":"X","reason_options":[{"t":"“무거운 풀”은 졸려서 내려오는 눈꺼풀을 빗댄 말이기 때문에","correct":true},{"t":"시에 풀과 풀밭이라는 말이 나오기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["말하는 이는 교실에서 도덕 수업을 듣고 있어요.","“풀”은 눈꺼풀을 빗대어 말한 것이에요.","빗댄 말을 실제로 일어난 일로 읽지 않아요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_basic#10','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C1',3,'essay','teacher','경험을 시나 이야기로 표현하면 어떤 점이 좋은지 『국어』 257쪽 친구들의 말을 참고해 두 가지 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C1","difficulty":3,"kind":"essay","stem":"경험을 시나 이야기로 표현하면 어떤 점이 좋은지 『국어』 257쪽 친구들의 말을 참고해 두 가지 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 경험을 시나 이야기로 표현하면 그 일을 오랫동안 생생하게 기억할 수 있다. 또 경험하면서 느낀 내 마음을 다른 사람들에게 잘 전달할 수 있다. 「눈꺼풀」을 읽으니 졸렸던 시인의 마음이 내게도 전해졌기 때문이다.","scoring_points":["좋은 점을 두 가지 썼는가","겉모습(글씨·길이)이 아닌 기억·마음 전달에서 찾았는가","까닭을 덧붙였는가"]},"explanation":["경험을 재미있게 표현할 수 있어요.","오래 생생하게 기억할 수 있어요.","느낀 마음을 다른 사람에게 전할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 재미있게 표현할 수 있어."},{"who":"친구 2","text":"오랫동안 생생하게 기억할 수 있어."},{"who":"친구 3","text":"경험하면서 느낀 내 마음을 다른 사람들에게 잘 전달할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#1','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C35',2,'mc','auto','「눈꺼풀」의 끝에서 눈꺼풀을 「세상에서 가장 힘센」 풀이라고 한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07','K6-2-u6-X03']::text[],false,'{"seq":1,"concept":"K6-2-u6-C35","difficulty":2,"kind":"mc","stem":"「눈꺼풀」의 끝에서 눈꺼풀을 「세상에서 가장 힘센」 풀이라고 한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"깨어 있으려고 애써도 졸음 때문에 눈꺼풀이 자꾸 내려오기 때문","correct":true},{"t":"풀이 실제로 무척 단단하기 때문","mis":"K6-2-u6-X08"},{"t":"도덕 시간에 힘을 기르는 운동을 했기 때문","mis":"K6-2-u6-X07"},{"t":"힘센 말을 많이 넣어야 좋은 시가 되기 때문","mis":"K6-2-u6-X03"}],"explanation":["말하는 이는 눈을 뜨고 있으려고 애썼어요.","그래도 눈꺼풀이 자꾸 내려왔어요.","그래서 아무도 이길 수 없는 힘센 풀이라고 빗대었어요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#2','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',2,'mc','auto','「눈꺼풀」이 수업 시간에 졸렸던 경험을 재미있게 나타낸 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X04','K6-2-u6-X03','K6-2-u6-X09']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":2,"kind":"mc","stem":"「눈꺼풀」이 수업 시간에 졸렸던 경험을 재미있게 나타낸 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"감기는 눈꺼풀을 「무거운 풀」에 빗대어 느낌을 알맞게 나타냈기 때문","correct":true},{"t":"어렵고 멋있어 보이는 낱말을 많이 썼기 때문","mis":"K6-2-u6-X04"},{"t":"빗댄 표현을 줄마다 되도록 많이 넣었기 때문","mis":"K6-2-u6-X03"},{"t":"겪은 일을 처음부터 끝까지 빠짐없이 썼기 때문","mis":"K6-2-u6-X09"}],"explanation":["「눈꺼풀」은 눈꺼풀과 풀을 엮어 재치 있게 빗대었어요.","졸음을 이기기 어려운 느낌이 잘 살아났어요.","표현은 개수가 아니라 알맞음이 중요해요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#3','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C2',3,'mc','auto','글로 표현할 경험을 고르기 어려워하는 친구에게 해 줄 도움으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X01','K6-2-u6-X09']::text[],false,'{"seq":3,"concept":"K6-2-u6-C2","difficulty":3,"kind":"mc","stem":"글로 표현할 경험을 고르기 어려워하는 친구에게 해 줄 도움으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"인상 깊었던 경험을 모두 적어 보고, 생각이나 느낌이 생생한 것을 고르게 한다","correct":true},{"t":"특별한 여행을 다녀온 뒤에야 쓸 수 있다고 말해 준다","mis":"K6-2-u6-X02"},{"t":"가장 길게 쓸 수 있는 경험을 골라 쓰게 한다","mis":"K6-2-u6-X01"},{"t":"겪은 일을 아침부터 저녁까지 빠짐없이 적게 한다","mis":"K6-2-u6-X09"}],"explanation":["인상 깊었던 경험을 먼저 모두 적어 보아요.","그 가운데 생각이나 느낌이 생생하게 떠오르는 것을 골라요.","특별한 일이 아니어도 일상의 경험이면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#4','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',3,'error','auto','경험을 시나 이야기로 표현하면 좋은 점을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X02','K6-2-u6-X03']::text[],false,'{"seq":4,"concept":"K6-2-u6-C1","difficulty":3,"kind":"error","stem":"경험을 시나 이야기로 표현하면 좋은 점을 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「경험을 글로 쓰면 글씨를 반듯하게 쓰게 되는 게 가장 좋은 점이야.」","correct":true,"mis_target":"K6-2-u6-X01"},{"t":"친구 1 — 「경험을 재미있게 표현할 수 있어.」","mis":"K6-2-u6-X02"},{"t":"친구 2 — 「오랫동안 생생하게 기억할 수 있어.」","mis":"K6-2-u6-X03"}],"explanation":["친구 1과 친구 2는 『국어』 257쪽처럼 바르게 말했어요.","경험을 표현하면 기억하고 마음을 전할 수 있어요.","글씨 모양은 경험을 글로 표현하는 좋은 점이 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 재미있게 표현할 수 있어."},{"who":"친구 2","text":"오랫동안 생생하게 기억할 수 있어."},{"who":"친구 3","text":"경험하면서 느낀 내 마음을 다른 사람들에게 잘 전달할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#5','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C35',3,'match','auto','「눈꺼풀」의 표현과 그 표현이 나타낸 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C35","difficulty":3,"kind":"match","stem":"「눈꺼풀」의 표현과 그 표현이 나타낸 것을 알맞게 이으세요.","pairs":[{"l":"“꾸벅 꾸우벅”","r":"졸려서 눈이 감기는 모습"},{"l":"“세상에서 가장 무거운 풀”","r":"깨려 해도 잘 떠지지 않는 눈꺼풀"},{"l":"“5교시 도덕 시간”","r":"졸음이 쏟아진 때"}],"mis":"K6-2-u6-X08","explanation":["“꾸벅 꾸우벅”은 조는 모습을 흉내 낸 말이에요.","무거운 풀은 눈꺼풀을 빗댄 말이에요.","도덕 시간은 졸음이 쏟아진 때예요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#6','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',3,'mc','auto','시나 이야기를 쓸 때 경험을 떠올리면 어떤 점이 좋을까요?',ARRAY['K6-2-u6-X01','K6-2-u6-X04','K6-2-u6-X09']::text[],false,'{"seq":6,"concept":"K6-2-u6-C1","difficulty":3,"kind":"mc","stem":"시나 이야기를 쓸 때 경험을 떠올리면 어떤 점이 좋을까요?","options":[{"t":"시나 이야기를 생생하고 재미있게 쓸 수 있다","correct":true},{"t":"글을 빨리 길게 늘일 수 있다","mis":"K6-2-u6-X01"},{"t":"어려운 낱말을 많이 쓸 수 있다","mis":"K6-2-u6-X04"},{"t":"겪은 일을 하나도 빠짐없이 적을 수 있다","mis":"K6-2-u6-X09"}],"explanation":["『국어』 255쪽 생각 열기의 물음이에요.","경험을 떠올리면 장면과 마음이 생생하게 살아나요.","그래서 시나 이야기를 생생하고 재미있게 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#7','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C2',3,'ox','auto','시는 거창하거나 화려한 일을 겪어야 쓸 수 있어요.',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":7,"concept":"K6-2-u6-C2","difficulty":3,"kind":"ox","stem":"시는 거창하거나 화려한 일을 겪어야 쓸 수 있어요.","answer":"X","reason_options":[{"t":"수업 시간에 졸렸던 일처럼 시는 생활 속 경험에서 나오기 때문에","correct":true},{"t":"특별한 일을 겪어야 읽는 사람이 재미있어하기 때문에","mis":"K6-2-u6-X02"}],"mis":"K6-2-u6-X02","explanation":["「눈꺼풀」은 누구나 겪는 졸음을 썼어요.","시는 생활 속 경험에서 나와요.","작은 일도 마음을 담으면 좋은 시가 돼요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#8','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C35',4,'essay','teacher','「눈꺼풀」은 어떤 경험을 시로 표현했는지 쓰고, 그 경험을 재미있게 나타낸 표현을 하나 골라 까닭을 쓰세요. 그리고 자신에게 있었던 비슷한 경험을 한 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C35","difficulty":4,"kind":"essay","stem":"「눈꺼풀」은 어떤 경험을 시로 표현했는지 쓰고, 그 경험을 재미있게 나타낸 표현을 하나 골라 까닭을 쓰세요. 그리고 자신에게 있었던 비슷한 경험을 한 가지 쓰세요.","answer_guide":{"answer":"예: 「눈꺼풀」은 점심 먹고 축구를 한 뒤 5교시 도덕 시간에 졸음이 쏟아진 경험을 표현했다. 눈꺼풀을 “세상에서 가장 무거운 풀”이라고 한 표현이 재미있다. 깨려고 해도 잘 떠지지 않는 눈꺼풀의 느낌이 잘 드러나기 때문이다. 나도 체육 시간 뒤 국어 시간에 눈이 자꾸 감겼던 적이 있다.","scoring_points":["시에 담긴 경험을 바르게 썼는가","표현 하나와 재미있는 까닭을 썼는가","자신의 비슷한 경험을 썼는가"]},"explanation":["시에 담긴 경험은 시 안의 말에서 찾아요.","빗댄 표현은 그때의 느낌을 살려 줘요.","비슷한 경험을 떠올리면 시를 더 깊이 느껴요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#9','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',4,'essay','teacher','이 단원에서 배울 내용을 살펴보고, 더 알고 싶은 것을 두 가지 쓰세요. 그리고 그것을 알고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배울 내용을 살펴보고, 더 알고 싶은 것을 두 가지 쓰세요. 그리고 그것을 알고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 비유적 표현을 써서 내 경험을 시로 쓰는 방법을 알고 싶다. 또 경험을 떠올리며 이야기를 바꾸어 쓰는 방법도 알고 싶다. 내가 겪은 일을 재미있게 표현해 친구들에게 들려주고 싶기 때문이다.","scoring_points":["단원의 배울 내용과 이어진 것을 썼는가","알고 싶은 것을 두 가지 썼는가","까닭을 썼는가"]},"explanation":["이 단원은 시 창작하기와 이야기로 표현하기로 이루어져요.","비유적 표현·경험 떠올리기·바꾸어 쓰기가 알고 싶은 것의 예예요.","시 낭송이나 작품 감상도 알고 싶은 것이 될 수 있어요."],"asset":{"type":"passage","lines":["1. 시 창작하기","• 시의 특성을 생각하며 시 감상하기","• 시의 특성을 생각하며 시 창작하기","• 시 낭송하기","2. 이야기로 표현하기","• 경험을 떠올리며 이야기를 바꾸어 쓰는 방법 알기","• 이야기 바꾸어 쓰기"],"numbered":false,"title":"이 단원에서는 배워요 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L01_challenge#10','kor',6,2,'u6','L01','tb_g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',4,'mc','auto','「눈꺼풀」처럼 경험을 시로 쓸 때의 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X09']::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":4,"kind":"mc","stem":"「눈꺼풀」처럼 경험을 시로 쓸 때의 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그때의 느낌이 잘 살아나는 표현을 골라 알맞게 쓴다","correct":true},{"t":"빗댄 표현을 줄마다 하나씩 넣어야 한다","mis":"K6-2-u6-X03"},{"t":"어렵고 멋있어 보이는 말을 골라 쓴다","mis":"K6-2-u6-X04"},{"t":"겪은 일을 시간 차례대로 모두 써 넣는다","mis":"K6-2-u6-X09"}],"explanation":["「눈꺼풀」은 졸음을 「무거운 풀」 하나로 재치 있게 나타냈어요.","느낌이 잘 살아나는 표현을 골랐기 때문에 재미있어요.","좋은 표현은 개수가 아니라 알맞음이 중요해요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#1','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C36',1,'mc','auto','「그때부터였나 봐」에서 말하는 이에게 축구공이 굴러오기 시작한 것은 언제부터인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C36","difficulty":1,"kind":"mc","stem":"「그때부터였나 봐」에서 말하는 이에게 축구공이 굴러오기 시작한 것은 언제부터인가요?","options":[{"t":"축구공을 차며 골대로 뛰어가는 수빈이를 본 뒤부터","correct":true},{"t":"급식실에서 친구와 밥을 먹은 뒤부터","mis":"K6-2-u6-X07"},{"t":"음악실에서 피아노를 친 뒤부터","mis":"K6-2-u6-X07"},{"t":"수학 시험을 보고 난 뒤부터","mis":"K6-2-u6-X07"}],"explanation":["제목 「그때부터였나 봐」의 「그때」를 찾아보아요.","첫 연에 수빈이를 본 뒤부터라고 나와요.","그 뒤로 축구공만 굴러온다고 했어요."],"asset":{"type":"passage","lines":["축구공을 차며 골대로 뛰어가는","수빈이를 본 뒤부터","연우야, 급식실 가자, 누가 불러도","축구공만 데굴데굴 굴러와"],"title":"「그때부터였나 봐」(임수현) 첫 연 — 『국어』 258쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#2','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C36',1,'sa','auto','「그때부터였나 봐」에서 누군가 말하는 이를 급식실에 가자고 부를 때 부른 이름은 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C36","difficulty":1,"kind":"sa","stem":"「그때부터였나 봐」에서 누군가 말하는 이를 급식실에 가자고 부를 때 부른 이름은 무엇인가요?","answer":["연우"],"explanation":["첫 연의 셋째 줄을 읽어 보아요.","「연우야, 급식실 가자」라고 불렀어요.","말하는 이는 연우이고, 수빈이는 축구공을 찬 친구예요."],"asset":{"type":"passage","lines":["축구공을 차며 골대로 뛰어가는","수빈이를 본 뒤부터","연우야, 급식실 가자, 누가 불러도","축구공만 데굴데굴 굴러와"],"title":"「그때부터였나 봐」(임수현) 첫 연 — 『국어』 258쪽"},"mis":"K6-2-u6-X50"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#3','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C37',1,'mc','auto','「오늘 날씨는」의 말하는 이는 어떤 상황에 놓여 있나요?',ARRAY['K6-2-u6-X07','K6-2-u6-X08']::text[],false,'{"seq":3,"concept":"K6-2-u6-C37","difficulty":1,"kind":"mc","stem":"「오늘 날씨는」의 말하는 이는 어떤 상황에 놓여 있나요?","options":[{"t":"오늘 전학을 왔다","correct":true},{"t":"비 오는 날 우산을 잃어버렸다","mis":"K6-2-u6-X07"},{"t":"첫눈을 보러 산에 갔다","mis":"K6-2-u6-X07"},{"t":"번개가 쳐서 집에 일찍 갔다","mis":"K6-2-u6-X08"}],"explanation":["『국어』 263쪽 6번 (1)의 물음이에요.","시의 끝에 오늘 전학 온 나라는 말이 나와요.","말하는 이는 새 반 아이들을 날씨에 빗대어 보고 있어요."],"asset":{"type":"passage","lines":["수다스러운 소나기는","수줍음 많은 첫눈은","장난기 많은 번개는","목소리가 큰 천둥은","소나기처럼 첫눈처럼 번개처럼 천둥처럼","(간추림) 말하는 이는 오늘 전학을 왔고, 새 반 아이들이","자신을 어떤 날씨라고 생각할지 궁금해한다."],"numbered":false,"title":"「오늘 날씨는」(양슬기) 가운데 — 『국어』 262쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#4','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C8',1,'ox','auto','‘처럼’을 써서 두 대상을 직접 비교하는 것은 직유법이에요.',ARRAY['K6-2-u6-X11']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":1,"kind":"ox","stem":"‘처럼’을 써서 두 대상을 직접 비교하는 것은 직유법이에요.","answer":"O","reason_options":[{"t":"‘같이’, ‘처럼’, ‘듯이’를 써서 두 대상을 직접 비교하면 직유법이기 때문에","correct":true},{"t":"‘처럼’이 들어가면 은유법이 되기 때문에","mis":"K6-2-u6-X11"}],"mis":"K6-2-u6-X11","explanation":["‘같이’, ‘처럼’, ‘듯이’로 직접 비교하면 직유법이에요.","‘……은/는 ……(이)다’처럼 빗대면 은유법이에요.","두 방법 모두 비유적 표현이에요."],"asset":{"type":"passage","lines":["비슷한 현상이나 사물을 다른 것에 빗대어 표현하는 것을 비유적 표현이라고 해요.","‘같이’, ‘처럼’, ‘듯이’를 써서 두 대상을 직접 비교하면 직유법,","‘……은/는 ……(이)다’처럼 빗대어 표현하면 은유법이에요."],"title":"비유적 표현 — 『국어』 262~263쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#5','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C5',2,'mc','auto','「그때부터였나 봐」에서 말하는 이의 어떤 마음을 “축구공이 수북이 쌓였어”로 표현한 것일까요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「그때부터였나 봐」에서 말하는 이의 어떤 마음을 “축구공이 수북이 쌓였어”로 표현한 것일까요?","options":[{"t":"수빈이를 향해 점점 커져 가는 마음","correct":true},{"t":"운동장에 축구공이 정말로 많이 쌓인 모습","mis":"K6-2-u6-X08"},{"t":"축구공을 정리하기 귀찮은 마음","mis":"K6-2-u6-X07"},{"t":"과학실 청소를 해야 하는 마음","mis":"K6-2-u6-X07"}],"explanation":["『국어』 260쪽 2번 (2)의 물음이에요.","축구공은 수빈이를 떠올리게 하는 것이에요.","공이 쌓이는 것처럼 수빈이를 향한 마음이 점점 커져 가요."],"asset":{"type":"passage","lines":["(간추림) 음악실에 가야 하는데 과학실에 가고, 종이 쳐도 운동장만 내다본다.","(간추림) 수학책을 꺼내라는데 수빈이가 찬 공이 굴러온다.","(간추림) 과학실에도 급식실에도, 건반과 곱셈 위에도 공이 쌓여 간다.","축구공이 수북이 쌓였어","(간추림) 눈을 감고 있어도 수빈이가 공을 몰고 다가온다."],"numbered":false,"title":"「그때부터였나 봐」(임수현) 뒷부분 — 『국어』 258~259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#6','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C37',2,'match','auto','「오늘 날씨는」의 비유적 표현과 그 표현이 나타낸 대상을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C37","difficulty":2,"kind":"match","stem":"「오늘 날씨는」의 비유적 표현과 그 표현이 나타낸 대상을 알맞게 이으세요.","pairs":[{"l":"소나기","r":"수다스러운 친구"},{"l":"첫눈","r":"수줍음이 많은 친구"},{"l":"번개","r":"장난기 많은 친구"},{"l":"천둥","r":"목소리가 큰 친구"}],"mis":"K6-2-u6-X10","explanation":["말하는 이는 새 반 아이들을 날씨에 빗대었어요.","날씨의 모습과 친구의 모습에서 비슷한 점을 찾았어요.","『국어』 263쪽 6번 (2)의 표를 떠올려 보아요."],"asset":{"type":"passage","lines":["수다스러운 소나기는","수줍음 많은 첫눈은","장난기 많은 번개는","목소리가 큰 천둥은","소나기처럼 첫눈처럼 번개처럼 천둥처럼","(간추림) 말하는 이는 오늘 전학을 왔고, 새 반 아이들이","자신을 어떤 날씨라고 생각할지 궁금해한다."],"numbered":false,"title":"「오늘 날씨는」(양슬기) 가운데 — 『국어』 262쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#7','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C9',2,'mc','auto','「축구공만 데굴데굴 굴러와」처럼 본 것이나 들은 것을 생생하게 살려 나타낸 표현을 무엇이라고 하나요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12','K6-2-u6-X46']::text[],false,'{"seq":7,"concept":"K6-2-u6-C9","difficulty":2,"kind":"mc","stem":"「축구공만 데굴데굴 굴러와」처럼 본 것이나 들은 것을 생생하게 살려 나타낸 표현을 무엇이라고 하나요?","options":[{"t":"감각적 표현","correct":true},{"t":"은유법","mis":"K6-2-u6-X11"},{"t":"비유적 표현","mis":"K6-2-u6-X12"},{"t":"주장하는 말","mis":"K6-2-u6-X46"}],"explanation":["「데굴데굴」은 공이 구르는 모습을 눈에 보이듯 나타냈어요.","본 것, 들은 것 같은 감각을 살린 표현이 감각적 표현이에요.","다른 것에 빗대는 비유적 표현과 구별해요."],"asset":{"type":"passage","lines":["축구공을 차며 골대로 뛰어가는","수빈이를 본 뒤부터","연우야, 급식실 가자, 누가 불러도","축구공만 데굴데굴 굴러와"],"title":"「그때부터였나 봐」(임수현) 첫 연 — 『국어』 258쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#8','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C6',2,'mc','auto','『국어』 261쪽에서 같은 경험을 쓴 글과 견주어 볼 때, 「그때부터였나 봐」는 경험을 어떻게 시로 표현했나요?',ARRAY['K6-2-u6-X09','K6-2-u6-X04','K6-2-u6-X13']::text[],false,'{"seq":8,"concept":"K6-2-u6-C6","difficulty":2,"kind":"mc","stem":"『국어』 261쪽에서 같은 경험을 쓴 글과 견주어 볼 때, 「그때부터였나 봐」는 경험을 어떻게 시로 표현했나요?","options":[{"t":"마음을 잘 전할 부분만 골라 짧고 간결하게 행으로 나누었다","correct":true},{"t":"경험을 하나도 빠짐없이 차례대로 다 적었다","mis":"K6-2-u6-X09"},{"t":"어려운 낱말로 바꾸어 길게 늘였다","mis":"K6-2-u6-X04"},{"t":"일기처럼 날짜와 날씨부터 썼다","mis":"K6-2-u6-X13"}],"explanation":["경험을 쓴 글은 겪은 일을 차례대로 풀어 썼어요.","시는 마음을 잘 전할 부분을 골라 짧게 썼어요.","리듬을 살려 행으로 나누었어요."],"asset":{"type":"passage","lines":["오늘 운동장에서 축구하는 수빈이를 보았다.","골대로 축구공을 차면서 뛰어가는 수빈이가 참 멋졌다.","그때부터 하루 종일 수빈이 생각만 났다.","(간추림) 점심시간에 친구가 급식실에 가자는 소리도 못 들었다."],"numbered":false,"title":"같은 경험을 쓴 글 — 『국어』 261쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#9','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C10',2,'ox','auto','시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이에요.',ARRAY['K6-2-u6-X17']::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"ox","stem":"시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이에요.","answer":"O","reason_options":[{"t":"경험 가운데 마음을 잘 전하는 부분을 골라 간결하게 쓰기 때문에","correct":true},{"t":"짧기만 하면 어떤 글이든 좋은 시가 되기 때문에","mis":"K6-2-u6-X17"}],"mis":"K6-2-u6-X17","explanation":["『국어』 263쪽 7번에서 친구가 한 말이에요.","시는 마음을 짧은 글로 압축해요.","짧은 것이 목적이 아니라 마음이 잘 드러나는 것이 중요해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이야. 연과 행으로 나누어 읽을 때 리듬감을 느낄 수 있어."},{"who":"친구 2","text":"비유적 표현을 활용해서 시를 쓴 사람이 표현하고 싶은 느낌을 더 생생하게 나타내기도 해."},{"who":"친구 3","text":"감각적 표현을 활용하여 생생하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_basic#10','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C37',3,'blank','auto','「오늘 날씨는」에서 첫눈을 수줍음이 많은 친구에 빗댄 까닭이에요. 「첫눈이 (    ) 주저하는 모습이 수줍은 친구와 비슷하기 때문」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X10']::text[],false,'{"seq":10,"concept":"K6-2-u6-C37","difficulty":3,"kind":"blank","stem":"「오늘 날씨는」에서 첫눈을 수줍음이 많은 친구에 빗댄 까닭이에요. 「첫눈이 (    ) 주저하는 모습이 수줍은 친구와 비슷하기 때문」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"올 듯 말 듯","correct":true},{"t":"쉴 새 없이","mis":"K6-2-u6-X10"},{"t":"번쩍 손을 들 듯","mis":"K6-2-u6-X10"},{"t":"우렁차게 외치듯","mis":"K6-2-u6-X10"}],"explanation":["비유적 표현에는 두 대상 사이의 비슷한 점이 있어요.","첫눈은 올 듯 말 듯 주저해요.","그 모습이 수줍음이 많은 친구와 닮았어요."],"asset":{"type":"passage","lines":["[표] 비유적 표현 — 대상 — 그 까닭","소나기 — 수다스러운 친구 — 쉴 새 없이 말을 걸기 때문","첫눈 — 수줍음이 많은 친구 — 올 듯 말 듯 주저하기 때문","번개 — 장난기 많은 친구 — 손을 들다가 아무것도 아니라며 고개 숙임","천둥 — 목소리가 큰 친구 — 우렁차게 말하기 때문"],"numbered":false,"title":"「오늘 날씨는」의 비유적 표현 정리 — 『국어』 263쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#1','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C36',2,'mc','auto','「그때부터였나 봐」에서 말하는 이가 수학책을 꺼낼 때 축구공이 통통 굴러왔다고 표현한 까닭은 무엇일까요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07','K6-2-u6-X03']::text[],false,'{"seq":1,"concept":"K6-2-u6-C36","difficulty":2,"kind":"mc","stem":"「그때부터였나 봐」에서 말하는 이가 수학책을 꺼낼 때 축구공이 통통 굴러왔다고 표현한 까닭은 무엇일까요?","options":[{"t":"축구공을 차던 수빈이 모습이 떠올랐기 때문","correct":true},{"t":"수업 시간에 진짜 공이 교실로 들어왔기 때문","mis":"K6-2-u6-X08"},{"t":"수학책에 축구공 그림이 있었기 때문","mis":"K6-2-u6-X07"},{"t":"축구공이라는 말을 많이 넣어야 좋은 시가 되기 때문","mis":"K6-2-u6-X03"}],"explanation":["『국어』 260쪽 2번 (1)의 물음이에요.","말하는 이는 수빈이 생각이 자꾸 나요.","그래서 수빈이가 찬 공이 굴러온다고 표현했어요."],"asset":{"type":"passage","lines":["(간추림) 음악실에 가야 하는데 과학실에 가고, 종이 쳐도 운동장만 내다본다.","(간추림) 수학책을 꺼내라는데 수빈이가 찬 공이 굴러온다.","(간추림) 과학실에도 급식실에도, 건반과 곱셈 위에도 공이 쌓여 간다.","축구공이 수북이 쌓였어","(간추림) 눈을 감고 있어도 수빈이가 공을 몰고 다가온다."],"numbered":false,"title":"「그때부터였나 봐」(임수현) 뒷부분 — 『국어』 258~259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#2','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C37',2,'mc','auto','「오늘 날씨는」의 「소나기처럼 첫눈처럼 번개처럼 천둥처럼」에 쓰인 표현 방법은 무엇인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":2,"concept":"K6-2-u6-C37","difficulty":2,"kind":"mc","stem":"「오늘 날씨는」의 「소나기처럼 첫눈처럼 번개처럼 천둥처럼」에 쓰인 표현 방법은 무엇인가요?","options":[{"t":"‘처럼’을 써서 아이들을 날씨에 직접 견준 직유법","correct":true},{"t":"‘……은/는 ……이다’로 빗댄 은유법","mis":"K6-2-u6-X11"},{"t":"본 것을 그대로 쓴 감각적 표현","mis":"K6-2-u6-X12"}],"explanation":["줄마다 ‘처럼’이 되풀이돼요.","‘처럼’으로 두 대상을 직접 비교하면 직유법이에요.","같은 말을 되풀이해 리듬도 살아나요."],"asset":{"type":"passage","lines":["수다스러운 소나기는","수줍음 많은 첫눈은","장난기 많은 번개는","목소리가 큰 천둥은","소나기처럼 첫눈처럼 번개처럼 천둥처럼","(간추림) 말하는 이는 오늘 전학을 왔고, 새 반 아이들이","자신을 어떤 날씨라고 생각할지 궁금해한다."],"numbered":false,"title":"「오늘 날씨는」(양슬기) 가운데 — 『국어』 262쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#3','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C36',3,'mc','auto','친구들이 「그때부터였나 봐」를 서로 다르게 읽었어요. 가장 알맞은 생각은 무엇인가요?',ARRAY['K6-2-u6-X44','K6-2-u6-X13','K6-2-u6-X08']::text[],false,'{"seq":3,"concept":"K6-2-u6-C36","difficulty":3,"kind":"mc","stem":"친구들이 「그때부터였나 봐」를 서로 다르게 읽었어요. 가장 알맞은 생각은 무엇인가요?","options":[{"t":"시 안의 말로 뒷받침된다면 좋아하는 마음으로도, 축구하고 싶은 마음으로도 읽을 수 있다","correct":true},{"t":"시는 한 가지 뜻으로만 읽어야 하니 한 친구는 틀렸다","mis":"K6-2-u6-X44"},{"t":"시인이 직접 알려 주기 전에는 아무 뜻도 알 수 없다","mis":"K6-2-u6-X13"},{"t":"공이 쌓인다는 말은 실제로 공을 모았다는 뜻이다","mis":"K6-2-u6-X08"}],"explanation":["이 시는 수빈이를 좋아하는 마음으로 읽을 수 있어요.","수빈이처럼 축구하고 싶은 마음으로도 읽을 수 있어요.","시 안의 말로 뒷받침되면 여러 풀이를 존중해요."],"asset":{"type":"passage","lines":["(간추림) 음악실에 가야 하는데 과학실에 가고, 종이 쳐도 운동장만 내다본다.","(간추림) 수학책을 꺼내라는데 수빈이가 찬 공이 굴러온다.","(간추림) 과학실에도 급식실에도, 건반과 곱셈 위에도 공이 쌓여 간다.","축구공이 수북이 쌓였어","(간추림) 눈을 감고 있어도 수빈이가 공을 몰고 다가온다."],"numbered":false,"title":"「그때부터였나 봐」(임수현) 뒷부분 — 『국어』 258~259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#4','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C6',3,'error','auto','「그때부터였나 봐」가 경험을 어떻게 표현했는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X17','K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C6","difficulty":3,"kind":"error","stem":"「그때부터였나 봐」가 경험을 어떻게 표현했는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「경험한 것을 하나도 빼지 않고 다 넣었기 때문에 생생해.」","correct":true,"mis_target":"K6-2-u6-X09"},{"t":"친구 1 — 「생각이나 느낌을 잘 전할 부분을 짧고 간결하게 표현했어.」","mis":"K6-2-u6-X17"},{"t":"친구 2 — 「친구가 한 말을 그대로 넣어 경험을 생생하게 표현했어.」","mis":"K6-2-u6-X12"}],"explanation":["친구 1과 친구 2는 『국어』 261쪽처럼 말했어요.","시는 경험을 모두 쓰지 않고 골라서 써요.","같은 경험을 쓴 글과 견주면 시가 훨씬 간결해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험에서 생각이나 느낌을 잘 전달할 수 있는 부분을 짧고 간결하게 표현하고, 리듬을 살려 행으로 나누었어."},{"who":"친구 2","text":"수빈이가 자꾸 생각나는 것을 축구공이 굴러오는 것으로 빗대어 표현했어."},{"who":"친구 3","text":"친구가 한 말을 그대로 넣어 경험을 생생하게 표현했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#5','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C7',3,'mc','auto','「그때부터였나 봐」에서 수빈이가 자꾸 생각나는 것을 축구공이 굴러오는 것에 빗댈 수 있는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X10','K6-2-u6-X03']::text[],false,'{"seq":5,"concept":"K6-2-u6-C7","difficulty":3,"kind":"mc","stem":"「그때부터였나 봐」에서 수빈이가 자꾸 생각나는 것을 축구공이 굴러오는 것에 빗댈 수 있는 까닭은 무엇인가요?","options":[{"t":"자꾸 떠오르는 생각이, 내게로 계속 굴러오는 공과 비슷하기 때문","correct":true},{"t":"수빈이와 축구공은 생김새가 똑같기 때문","mis":"K6-2-u6-X10"},{"t":"비슷한 점이 없어도 아무것에나 빗대면 되기 때문","mis":"K6-2-u6-X10"},{"t":"빗댄 표현은 많을수록 좋기 때문","mis":"K6-2-u6-X03"}],"explanation":["비유적 표현은 두 대상의 비슷한 점으로 빗대요.","생각이 자꾸 떠오르는 것과 공이 자꾸 굴러오는 것이 닮았어요.","그래서 마음이 더 생생하게 전해져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험에서 생각이나 느낌을 잘 전달할 수 있는 부분을 짧고 간결하게 표현하고, 리듬을 살려 행으로 나누었어."},{"who":"친구 2","text":"수빈이가 자꾸 생각나는 것을 축구공이 굴러오는 것으로 빗대어 표현했어."},{"who":"친구 3","text":"친구가 한 말을 그대로 넣어 경험을 생생하게 표현했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#6','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C37',3,'match','auto','「오늘 날씨는」의 비유적 표현과 그렇게 빗댄 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C37","difficulty":3,"kind":"match","stem":"「오늘 날씨는」의 비유적 표현과 그렇게 빗댄 까닭을 알맞게 이으세요.","pairs":[{"l":"소나기","r":"쉴 새 없이 말을 걸기 때문"},{"l":"첫눈","r":"올 듯 말 듯 주저하기 때문"},{"l":"번개","r":"손을 들다가 아무것도 아니라며 고개를 숙이기 때문"},{"l":"천둥","r":"우렁차게 말하기 때문"}],"mis":"K6-2-u6-X10","explanation":["비유한 까닭은 두 대상의 비슷한 점이에요.","날씨의 모습과 친구의 말이나 행동이 닮았어요.","『국어』 263쪽 예시 답안을 떠올려 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#7','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C10',3,'ox','auto','비유적 표현이 없으면 시라고 할 수 없어요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":7,"concept":"K6-2-u6-C10","difficulty":3,"kind":"ox","stem":"비유적 표현이 없으면 시라고 할 수 없어요.","answer":"X","reason_options":[{"t":"비유적 표현은 느낌을 생생하게 나타내는 방법의 하나이고, 시마다 알맞은 방법을 고르기 때문에","correct":true},{"t":"시에는 꼭 비유가 들어가야 하는 규칙이 있기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["시는 비유적 표현을 활용해 느낌을 생생하게 나타내기도 해요.","감각적 표현이나 되풀이도 쓸 수 있어요.","시의 특성은 지켜야 할 규칙이 아니라 쓰는 방법이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이야. 연과 행으로 나누어 읽을 때 리듬감을 느낄 수 있어."},{"who":"친구 2","text":"비유적 표현을 활용해서 시를 쓴 사람이 표현하고 싶은 느낌을 더 생생하게 나타내기도 해."},{"who":"친구 3","text":"감각적 표현을 활용하여 생생하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#8','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C37',4,'essay','teacher','「오늘 날씨는」의 말하는 이처럼 자신을 날씨나 사물에 빗대어 한 줄로 표현해 보세요. 그리고 무엇과 무엇이 어떤 점에서 비슷한지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C37","difficulty":4,"kind":"essay","stem":"「오늘 날씨는」의 말하는 이처럼 자신을 날씨나 사물에 빗대어 한 줄로 표현해 보세요. 그리고 무엇과 무엇이 어떤 점에서 비슷한지 쓰세요.","answer_guide":{"answer":"예: 나는 아침 햇살이다. 아침 햇살이 조용히 방 안을 밝히듯 나도 말없이 친구들을 도와주는 것을 좋아하기 때문이다.","scoring_points":["자신을 날씨나 사물에 빗대어 표현했는가","두 대상의 비슷한 점을 썼는가","직유법이나 은유법을 알맞게 썼는가"]},"explanation":["비유적 표현은 비슷한 점으로 빗대요.","‘처럼’을 쓰면 직유법, ‘……은 ……이다’면 은유법이에요.","빗댄 까닭을 쓰면 표현이 더 분명해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#9','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C36',4,'essay','teacher','『국어』 260쪽처럼 「그때부터였나 봐」에서 인상 깊은 장면을 하나 골라 이미지 카드를 만들려고 해요. 고른 장면, 그 장면에 담긴 마음, 카드에 그릴 대상, 그렇게 만든 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C36","difficulty":4,"kind":"essay","stem":"『국어』 260쪽처럼 「그때부터였나 봐」에서 인상 깊은 장면을 하나 골라 이미지 카드를 만들려고 해요. 고른 장면, 그 장면에 담긴 마음, 카드에 그릴 대상, 그렇게 만든 까닭을 쓰세요.","answer_guide":{"answer":"예: 축구공이 수북이 쌓이는 장면을 골랐다. 이 장면에는 수빈이를 향해 점점 커져 가는 마음이 담겨 있다. 카드에는 책상과 건반 위에 축구공이 산처럼 쌓인 모습을 그리겠다. 어디를 가도 수빈이 생각이 쌓여 가는 마음을 한눈에 보여 주고 싶기 때문이다.","scoring_points":["장면을 골랐는가","장면에 담긴 마음을 썼는가","그릴 대상과 까닭을 마음과 이어지게 썼는가"]},"explanation":["먼저 인상 깊은 장면을 골라요.","그 장면에 담긴 마음을 이야기해요.","마음과 어울리는 대상을 그리고 까닭을 말해요."],"asset":{"type":"passage","lines":["1 모둠별로 시를 다시 읽고 인상 깊은 장면을 선택한다.","2 선택한 장면에 어떤 마음이 담겨 있는지 이야기한다.","3 떠올린 마음과 어울리는 대상이나 장면을 이미지 카드에 그린다.","4 그린 그림에 자신이 느낀 마음을 글로 간단히 쓴다.","5 카드를 친구들에게 보여 주면서 그렇게 만든 까닭을 이야기한다."],"numbered":false,"title":"이미지 카드 만들기 — 『국어』 260쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L02_challenge#10','kor',6,2,'u6','L02','tb_g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C10',4,'essay','teacher','『국어』 263쪽 7번처럼 시의 특성을 세 가지로 정리하고, 「그때부터였나 봐」나 「오늘 날씨는」에서 그 특성이 드러난 부분을 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C10","difficulty":4,"kind":"essay","stem":"『국어』 263쪽 7번처럼 시의 특성을 세 가지로 정리하고, 「그때부터였나 봐」나 「오늘 날씨는」에서 그 특성이 드러난 부분을 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 시는 생각이나 느낌을 짧은 글로 압축해 쓴 글이다. 「그때부터였나 봐」는 수빈이 생각이 나는 하루를 몇 줄로 간결하게 나타냈다. 시는 연과 행으로 나누어 읽을 때 리듬감이 있다. 「오늘 날씨는」은 「……처럼」을 되풀이해 리듬이 느껴진다. 시는 비유적 표현과 감각적 표현으로 생생하게 나타낸다. 「오늘 날씨는」은 수다스러운 친구를 소나기에 빗대었다.","scoring_points":["시의 특성을 세 가지 썼는가","특성마다 시에서 드러난 부분을 찾았는가","특성을 규칙이 아닌 표현 방법으로 설명했는가"]},"explanation":["시는 생각이나 느낌을 압축한 글이에요.","연과 행으로 나누어 리듬감이 있어요.","비유적·감각적 표현으로 생생하게 나타내요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이야. 연과 행으로 나누어 읽을 때 리듬감을 느낄 수 있어."},{"who":"친구 2","text":"비유적 표현을 활용해서 시를 쓴 사람이 표현하고 싶은 느낌을 더 생생하게 나타내기도 해."},{"who":"친구 3","text":"감각적 표현을 활용하여 생생하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#1','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C11',1,'mc','auto','시로 표현하고 싶은 경험을 짝과 묻고 답하는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X15','K6-2-u6-X09']::text[],false,'{"seq":1,"concept":"K6-2-u6-C11","difficulty":1,"kind":"mc","stem":"시로 표현하고 싶은 경험을 짝과 묻고 답하는 까닭은 무엇인가요?","options":[{"t":"경험을 더 자세하고 생생하게 떠올려 생각을 정리하려고","correct":true},{"t":"시를 몇 줄로 쓸지 정하려고","mis":"K6-2-u6-X15"},{"t":"경험한 때를 몇 시 몇 분까지 정확히 알아내려고","mis":"K6-2-u6-X15"},{"t":"짝의 경험을 그대로 받아 적으려고","mis":"K6-2-u6-X09"}],"explanation":["『국어』 264쪽 계획하기 (2)의 활동이에요.","묻고 답하면서 경험이 더 자세해져요.","그때의 생각이나 느낌도 함께 떠올라요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"체육 시간에 배드민턴을 쳤던 경험을 시로 표현하고 싶어."},{"who":"친구 2","text":"배드민턴을 칠 때 어떤 경험이 가장 기억에 남았어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#2','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',1,'sa','auto','『국어』 265쪽 생각그물에서 「이마의 땀」은 무엇처럼 쏟아진다고 빗대었나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C12","difficulty":1,"kind":"sa","stem":"『국어』 265쪽 생각그물에서 「이마의 땀」은 무엇처럼 쏟아진다고 빗대었나요? 한 글자로 쓰세요.","answer":["비"],"explanation":["「이마의 땀」은 만진 것에 들어가요.","그 땀을 비처럼 쏟아지는 땀이라고 빗대었어요.","감각에서 비유적 표현으로 이어 갈 수 있어요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"},"mis":"K6-2-u6-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#3','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',1,'mc','auto','『국어』 265쪽 생각그물에서 「파이팅! / 친구들의 응원 소리」는 어느 갈래에 들어가나요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":3,"concept":"K6-2-u6-C12","difficulty":1,"kind":"mc","stem":"『국어』 265쪽 생각그물에서 「파이팅! / 친구들의 응원 소리」는 어느 갈래에 들어가나요?","options":[{"t":"들은 것","correct":true},{"t":"본 것","mis":"K6-2-u6-X12"},{"t":"만진 것","mis":"K6-2-u6-X12"},{"t":"비유적 표현","mis":"K6-2-u6-X12"}],"explanation":["응원 소리는 귀로 들은 것이에요.","생각그물에서 들은 것 칸에 적었어요.","그 소리를 듣고 힘이 난다는 느낌을 이어 적었어요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#4','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C14',1,'ox','auto','경험을 시로 창작할 때에는 시에 담긴 마음을 잘 드러내는 제목을 정해요.',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":4,"concept":"K6-2-u6-C14","difficulty":1,"kind":"ox","stem":"경험을 시로 창작할 때에는 시에 담긴 마음을 잘 드러내는 제목을 정해요.","answer":"O","reason_options":[{"t":"제목은 시에 담긴 마음을 읽는 사람에게 먼저 알려 주기 때문에","correct":true},{"t":"제목은 시의 내용과 상관없이 멋있게 붙이면 되기 때문에","mis":"K6-2-u6-X18"}],"mis":"K6-2-u6-X18","explanation":["『국어』 266쪽 글쓰기에서 말한 내용이에요.","제목은 시를 읽는 첫 문이에요.","시에 담긴 마음과 이어지는 제목이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#5','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C11',2,'mc','auto','시로 표현하고 싶은 경험을 짝과 묻고 답할 때 알맞은 질문은 무엇인가요?',ARRAY['K6-2-u6-X15','K6-2-u6-X03']::text[],false,'{"seq":5,"concept":"K6-2-u6-C11","difficulty":2,"kind":"mc","stem":"시로 표현하고 싶은 경험을 짝과 묻고 답할 때 알맞은 질문은 무엇인가요?","options":[{"t":"그때의 생각이나 느낌은 어땠나요?","correct":true},{"t":"그 경험은 몇 시 몇 분에 시작했나요?","mis":"K6-2-u6-X15"},{"t":"시를 모두 몇 줄로 쓸 건가요?","mis":"K6-2-u6-X15"},{"t":"빗댄 표현을 몇 개나 넣을 건가요?","mis":"K6-2-u6-X03"}],"explanation":["『국어』 264쪽에 질문의 예가 있어요.","누구와 함께 했는지, 그때 생각이나 느낌은 어땠는지 물어요.","경험을 자세히 떠올리게 하는 질문이 좋아요."],"asset":{"type":"passage","lines":["● 누구와 함께 한 경험인가요?","● 그때의 생각이나 느낌은 어땠나요?","● 그 경험을 시로 표현하고 싶은 까닭은 무엇인가요?","● 가장 재미있었던 순간은 언제인가요?","● 그 경험을 무엇에 빗대어 표현할 수 있을까요?"],"numbered":false,"title":"경험을 짝과 묻고 답하기 — 『국어』 264쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#6','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C13',2,'mc','auto','생각그물로 경험을 정리한 뒤 시를 쓸 때 해야 할 일은 무엇인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X07','K6-2-u6-X01']::text[],false,'{"seq":6,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"생각그물로 경험을 정리한 뒤 시를 쓸 때 해야 할 일은 무엇인가요?","options":[{"t":"경험을 전부 쓰지 않고 인상 깊었던 것을 골라 짧고 간결하게 쓴다","correct":true},{"t":"생각그물에 모은 것을 하나도 빠짐없이 모두 넣는다","mis":"K6-2-u6-X16"},{"t":"생각그물에 없는 일을 새로 많이 지어낸다","mis":"K6-2-u6-X07"},{"t":"되도록 길게 늘여 쓴다","mis":"K6-2-u6-X01"}],"explanation":["생각그물에는 경험이 많이 모여 있어요.","그 가운데 인상 깊었던 것을 골라요.","짧고 간결하게 써야 마음이 또렷해져요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 시의 연과 행으로 구분해서 표현하면 좋을 것 같아."},{"who":"친구 2","text":"대상을 다른 사물이나 비슷한 상황에 빗대어 표현할 수 있어."},{"who":"친구 3","text":"본 것, 들은 것, 맛본 것과 같은 감각적인 표현을 써서 경험을 생생하게 나타낼 수 있어."},{"who":"친구 4","text":"경험을 전부 쓰지 않고 인상 깊었던 것을 골라 짧고 간결하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#7','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',2,'mc','auto','「사탕」에 나오는 「달콤달콤」은 어떤 감각으로 느낀 것을 나타낸 말인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":7,"concept":"K6-2-u6-C12","difficulty":2,"kind":"mc","stem":"「사탕」에 나오는 「달콤달콤」은 어떤 감각으로 느낀 것을 나타낸 말인가요?","options":[{"t":"맛본 것","correct":true},{"t":"들은 것","mis":"K6-2-u6-X12"},{"t":"만진 것","mis":"K6-2-u6-X12"},{"t":"본 것","mis":"K6-2-u6-X12"}],"explanation":["「사탕」은 사탕을 먹는 경험을 쓴 시예요.","「달콤달콤」은 혀로 맛본 느낌이에요.","맛본 것도 감각적 표현이 될 수 있어요."],"asset":{"type":"passage","lines":["입안에서","오물오물","달콤달콤"],"title":"「사탕」(송현, 6학년 어린이) 가운데 — 경험을 표현한 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#8','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',2,'match','auto','『국어』 265쪽 생각그물에서 감각으로 떠올린 것과 그때의 생각이나 느낌을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C12","difficulty":2,"kind":"match","stem":"『국어』 265쪽 생각그물에서 감각으로 떠올린 것과 그때의 생각이나 느낌을 알맞게 이으세요.","pairs":[{"l":"서브 넣을 때 파르르 떨리는 배드민턴공","r":"서브가 넘어갈 수 있을지 긴장됩니다."},{"l":"파이팅! / 친구들의 응원 소리","r":"힘이 납니다."},{"l":"톡 / 탁 공을 치는 소리","r":"경쾌한 느낌이 납니다."}],"mis":"K6-2-u6-X12","explanation":["본 것과 들은 것에 생각이나 느낌을 이어 적었어요.","떨리는 공을 보니 긴장되고, 응원을 들으니 힘이 나요.","공 치는 소리는 경쾌한 느낌을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#9','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C15',2,'ox','auto','자신이 쓴 시를 고쳐 쓸 때에는 시의 특성이 잘 드러나도록 표현했는지 확인해요.',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":9,"concept":"K6-2-u6-C15","difficulty":2,"kind":"ox","stem":"자신이 쓴 시를 고쳐 쓸 때에는 시의 특성이 잘 드러나도록 표현했는지 확인해요.","answer":"O","reason_options":[{"t":"연과 행, 비유적 표현, 감각적 표현으로 경험이 잘 드러났는지 살피기 때문에","correct":true},{"t":"고쳐 쓰기는 글씨 모양만 다듬는 일이기 때문에","mis":"K6-2-u6-X19"}],"mis":"K6-2-u6-X19","explanation":["『국어』 266쪽 수정하기 활동이에요.","시의 특성이 잘 드러났는지 확인해요.","글씨 모양보다 표현이 마음을 잘 전하는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_basic#10','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C13',3,'blank','auto','경험을 시로 표현할 때 생각할 특성이에요. 「경험을 전부 쓰지 않고 (    ) 것을 골라 짧고 간결하게 표현할 수 있어.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X16','K6-2-u6-X02']::text[],false,'{"seq":10,"concept":"K6-2-u6-C13","difficulty":3,"kind":"blank","stem":"경험을 시로 표현할 때 생각할 특성이에요. 「경험을 전부 쓰지 않고 (    ) 것을 골라 짧고 간결하게 표현할 수 있어.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"인상 깊었던","correct":true},{"t":"가장 길게 쓸 수 있는","mis":"K6-2-u6-X01"},{"t":"생각그물에 있는 모든","mis":"K6-2-u6-X16"},{"t":"남이 대단하다고 여길","mis":"K6-2-u6-X02"}],"explanation":["『국어』 266쪽 (4)의 예시 답안이에요.","모든 경험을 다 쓰면 마음이 흐려져요.","인상 깊었던 것을 골라 간결하게 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 시의 연과 행으로 구분해서 표현하면 좋을 것 같아."},{"who":"친구 2","text":"대상을 다른 사물이나 비슷한 상황에 빗대어 표현할 수 있어."},{"who":"친구 3","text":"본 것, 들은 것, 맛본 것과 같은 감각적인 표현을 써서 경험을 생생하게 나타낼 수 있어."},{"who":"친구 4","text":"경험을 전부 쓰지 않고 인상 깊었던 것을 골라 짧고 간결하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#1','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C12',2,'mc','auto','『국어』 265쪽 생각그물에서 높이 날아가는 배드민턴공을 「날아가는 새」에 빗댈 수 있는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X12','K6-2-u6-X03','K6-2-u6-X10']::text[],false,'{"seq":1,"concept":"K6-2-u6-C12","difficulty":2,"kind":"mc","stem":"『국어』 265쪽 생각그물에서 높이 날아가는 배드민턴공을 「날아가는 새」에 빗댈 수 있는 까닭은 무엇인가요?","options":[{"t":"높이 날아가는 모습이 서로 비슷하기 때문","correct":true},{"t":"새는 들은 것을 나타내는 말이기 때문","mis":"K6-2-u6-X12"},{"t":"빗댄 표현은 많을수록 좋기 때문","mis":"K6-2-u6-X03"},{"t":"비슷한 점이 없어도 멋있으면 되기 때문","mis":"K6-2-u6-X10"}],"explanation":["본 것에서 비유적 표현을 떠올렸어요.","배드민턴공과 새는 높이 날아가는 모습이 닮았어요.","비슷한 점이 있어야 알맞게 빗댈 수 있어요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#2','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C14',2,'mc','auto','경험을 시로 창작할 때 제목을 정하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X04']::text[],false,'{"seq":2,"concept":"K6-2-u6-C14","difficulty":2,"kind":"mc","stem":"경험을 시로 창작할 때 제목을 정하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"시에 담긴 마음이 잘 드러나도록 정한다","correct":true},{"t":"글자 수가 가장 많은 말로 정한다","mis":"K6-2-u6-X18"},{"t":"시의 내용과 상관없이 멋진 낱말로 정한다","mis":"K6-2-u6-X18"},{"t":"어려운 낱말이 들어가게 정한다","mis":"K6-2-u6-X04"}],"explanation":["제목은 시에 담긴 마음을 드러내요.","읽는 사람은 제목을 보고 시를 만나요.","내용과 마음에 어울리는 제목이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#3','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',3,'error','auto','시로 표현할 경험을 정하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X15','K6-2-u6-X10']::text[],false,'{"seq":3,"concept":"K6-2-u6-C11","difficulty":3,"kind":"error","stem":"시로 표현할 경험을 정하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「배드민턴 같은 평범한 일 말고 큰 대회에서 우승한 일처럼 대단한 일을 써야 시가 돼.」","correct":true,"mis_target":"K6-2-u6-X02"},{"t":"친구 1 — 「짝과 묻고 답하면서 그때 느낌을 더 자세히 떠올려 볼래.」","mis":"K6-2-u6-X15"},{"t":"친구 2 — 「늘 쓰는 배드민턴채나 공도 다른 사물에 빗대어 표현할 수 있어.」","mis":"K6-2-u6-X10"}],"explanation":["시는 거창하거나 화려한 것이 아니라 생활 속 경험에서 나와요.","일상에서 쓰는 사물도 모두 빗대어 표현할 수 있어요.","묻고 답하기는 경험을 자세히 떠올리게 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"체육 시간에 배드민턴을 쳤던 경험을 시로 표현하고 싶어."},{"who":"친구 2","text":"배드민턴을 칠 때 어떤 경험이 가장 기억에 남았어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#4','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',3,'mc','auto','시 쓰기를 어려워하는 친구에게 해 줄 도움으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X16','K6-2-u6-X03']::text[],false,'{"seq":4,"concept":"K6-2-u6-C11","difficulty":3,"kind":"mc","stem":"시 쓰기를 어려워하는 친구에게 해 줄 도움으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"경험을 먼저 말로 자유롭게 표현하고, 생각그물로 정리한 뒤 시로 쓰게 한다","correct":true},{"t":"처음부터 끝까지 한 번에 길게 쓰게 한다","mis":"K6-2-u6-X09"},{"t":"생각그물에 모은 것을 빠짐없이 차례대로 옮기게 한다","mis":"K6-2-u6-X16"},{"t":"빗댄 표현부터 많이 모아 외우게 한다","mis":"K6-2-u6-X03"}],"explanation":["먼저 말로 자유롭게 표현해 보아요.","그다음 생각그물로 간결하게 정리해요.","그렇게 하면 한 편의 시로 쓰기 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#5','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C15',3,'mc','auto','시를 고쳐 쓸 때, 시의 장면이 바뀌는 곳에서는 어떻게 하면 좋을까요?',ARRAY['K6-2-u6-X14','K6-2-u6-X18']::text[],false,'{"seq":5,"concept":"K6-2-u6-C15","difficulty":3,"kind":"mc","stem":"시를 고쳐 쓸 때, 시의 장면이 바뀌는 곳에서는 어떻게 하면 좋을까요?","options":[{"t":"행이나 연을 바꾸어 쓴다","correct":true},{"t":"장면이 바뀌어도 한 연으로 이어 쓴다","mis":"K6-2-u6-X14"},{"t":"글자 수가 같아지도록 아무 데서나 줄을 바꾼다","mis":"K6-2-u6-X14"},{"t":"장면이 바뀔 때마다 제목을 새로 붙인다","mis":"K6-2-u6-X18"}],"explanation":["시는 연과 행으로 나누어 써요.","장면이 바뀌는 곳에서 행이나 연을 바꾸면 읽기 쉬워요.","아무 데서나 나누면 리듬과 장면이 흐트러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#6','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C15',3,'mc','auto','시에 리듬감이 느껴지도록 고쳐 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X14','K6-2-u6-X04','K6-2-u6-X19']::text[],false,'{"seq":6,"concept":"K6-2-u6-C15","difficulty":3,"kind":"mc","stem":"시에 리듬감이 느껴지도록 고쳐 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"같은 표현을 되풀이해 리듬이 느껴지게 한다","correct":true},{"t":"모든 줄을 한 줄로 이어 붙인다","mis":"K6-2-u6-X14"},{"t":"쉬운 말을 어려운 말로 바꾼다","mis":"K6-2-u6-X04"},{"t":"글씨를 크고 예쁘게 다시 쓴다","mis":"K6-2-u6-X19"}],"explanation":["「오늘 날씨는」의 「……처럼」처럼 되풀이하면 리듬이 생겨요.","연과 행으로 나누어도 리듬감이 살아나요.","글씨 모양은 리듬과 상관이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#7','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C12',3,'ox','auto','생각그물에 모은 본 것, 들은 것, 만진 것은 시에 모두 넣어야 해요.',ARRAY['K6-2-u6-X16']::text[],false,'{"seq":7,"concept":"K6-2-u6-C12","difficulty":3,"kind":"ox","stem":"생각그물에 모은 본 것, 들은 것, 만진 것은 시에 모두 넣어야 해요.","answer":"X","reason_options":[{"t":"인상 깊었던 것을 골라 짧고 간결하게 써야 마음이 잘 드러나기 때문에","correct":true},{"t":"하나라도 빠지면 경험을 제대로 쓴 시가 아니기 때문에","mis":"K6-2-u6-X16"}],"mis":"K6-2-u6-X16","explanation":["생각그물은 경험을 넓게 모으는 단계예요.","시를 쓸 때에는 그 가운데에서 골라요.","버리는 것도 시를 쓰는 중요한 일이에요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#8','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',4,'essay','teacher','시로 표현하고 싶은 경험을 하나 정하고, 『국어』 264쪽의 질문 가운데 두 가지를 골라 스스로 답해 보세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C11","difficulty":4,"kind":"essay","stem":"시로 표현하고 싶은 경험을 하나 정하고, 『국어』 264쪽의 질문 가운데 두 가지를 골라 스스로 답해 보세요.","answer_guide":{"answer":"예: 시로 표현하고 싶은 경험은 동생과 처음 자전거를 탄 일이다. 「누구와 함께 한 경험인가요?」 — 동생과 함께 공원에서 탔다. 「그때의 생각이나 느낌은 어땠나요?」 — 넘어질까 봐 무서웠지만 바람을 가르며 달릴 때 날아가는 것처럼 신이 났다.","scoring_points":["시로 쓸 경험을 정했는가","질문 두 가지를 골라 답했는가","생각이나 느낌을 구체적으로 썼는가"]},"explanation":["일상의 경험도 좋은 시가 돼요.","묻고 답하면 경험이 자세해져요.","그때의 생각이나 느낌을 꼭 떠올려요."],"asset":{"type":"passage","lines":["● 누구와 함께 한 경험인가요?","● 그때의 생각이나 느낌은 어땠나요?","● 그 경험을 시로 표현하고 싶은 까닭은 무엇인가요?","● 가장 재미있었던 순간은 언제인가요?","● 그 경험을 무엇에 빗대어 표현할 수 있을까요?"],"numbered":false,"title":"경험을 짝과 묻고 답하기 — 『국어』 264쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#9','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C12',4,'essay','teacher','시로 표현하고 싶은 경험을 『국어』 265쪽처럼 생각그물로 정리하려고 해요. 본 것, 들은 것, 만진 것 가운데 두 가지를 쓰고, 그 가운데 하나를 비유적 표현으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C12","difficulty":4,"kind":"essay","stem":"시로 표현하고 싶은 경험을 『국어』 265쪽처럼 생각그물로 정리하려고 해요. 본 것, 들은 것, 만진 것 가운데 두 가지를 쓰고, 그 가운데 하나를 비유적 표현으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 경험 — 운동장에서 줄넘기를 한 일. 본 것 — 머리 위로 휙휙 넘어가는 줄. 들은 것 — 줄이 땅을 치는 탁탁 소리. 비유적 표현 — 머리 위로 넘어가는 줄은 무지개처럼 둥글게 휜다.","scoring_points":["감각 갈래를 두 가지 바르게 썼는가","비유적 표현을 하나 만들었는가","빗댄 두 대상에 비슷한 점이 있는가"]},"explanation":["생각그물은 감각 갈래로 나누어 모아요.","본 것, 들은 것, 만진 것으로 나누어 적어요.","비슷한 점을 찾아 빗대면 비유적 표현이 돼요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L04_challenge#10','kor',6,2,'u6','L04','tb_g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',4,'mc','auto','친구가 생각그물의 다섯 가지를 모두 넣어 길게 시를 썼어요. 고쳐 쓰도록 도와줄 조언으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X17','K6-2-u6-X03']::text[],false,'{"seq":10,"concept":"K6-2-u6-C13","difficulty":4,"kind":"mc","stem":"친구가 생각그물의 다섯 가지를 모두 넣어 길게 시를 썼어요. 고쳐 쓰도록 도와줄 조언으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"전할 마음을 정하고, 그 마음을 드러내는 것만 골라 연과 행으로 나누자","correct":true},{"t":"다섯 가지를 빠짐없이 다 넣었으니 잘 썼어","mis":"K6-2-u6-X16"},{"t":"짧을수록 좋으니 한 줄로만 줄여 보자","mis":"K6-2-u6-X17"},{"t":"빗댄 표현을 줄마다 하나씩 더 넣어 보자","mis":"K6-2-u6-X03"}],"explanation":["다 넣으면 정작 전하고 싶은 마음이 흐려져요.","마음을 정하고 그 마음에 맞는 것을 골라요.","짧게 줄이는 것이 목적이 아니라 마음을 또렷하게 하는 것이 목적이에요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#1','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',1,'mc','auto','시 낭송 계획을 세울 때 가장 먼저 정하는 것은 무엇인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":1,"concept":"K6-2-u6-C16","difficulty":1,"kind":"mc","stem":"시 낭송 계획을 세울 때 가장 먼저 정하는 것은 무엇인가요?","options":[{"t":"듣는 사람에게 꼭 전달하고 싶은 마음","correct":true},{"t":"가장 크게 낼 수 있는 목소리","mis":"K6-2-u6-X21"},{"t":"함께 틀 배경 음악","mis":"K6-2-u6-X22"},{"t":"친구들 앞에 나갈 낭송 순서","mis":"K6-2-u6-X20"}],"explanation":["『국어』 267쪽 계획하기 (1)의 활동이에요.","먼저 전하고 싶은 마음을 정해요.","목소리와 속도, 효과음은 그 마음에 맞추어 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#2','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',1,'mc','auto','시 낭송에서 마음을 잘 전달하는 다른 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X20','K6-2-u6-X22','K6-2-u6-X23']::text[],false,'{"seq":2,"concept":"K6-2-u6-C17","difficulty":1,"kind":"mc","stem":"시 낭송에서 마음을 잘 전달하는 다른 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"시와 어울리는 효과음을 활용한다","correct":true},{"t":"시를 아주 빨리 읽고 끝낸다","mis":"K6-2-u6-X20"},{"t":"시와 상관없는 화려한 영상을 크게 튼다","mis":"K6-2-u6-X22"},{"t":"작은 목소리로 혼자 읽는다","mis":"K6-2-u6-X23"}],"explanation":["『국어』 267쪽 (3)의 예시 답안을 떠올려 보아요.","심장 박동 소리 같은 효과음을 쓸 수 있어요.","어울리는 배경 음악이나 영상도 활용할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#3','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',1,'sa','auto','『국어』 268쪽 그림에서 시를 낭송할 때 주의할 점을 지키지 않은 친구의 번호 두 개를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C19","difficulty":1,"kind":"sa","stem":"『국어』 268쪽 그림에서 시를 낭송할 때 주의할 점을 지키지 않은 친구의 번호 두 개를 쓰세요.","answer":["①, ③","①③","① ③","1, 3","1 3","①,③","1,3"],"explanation":["①은 목소리가 너무 작아서 들리지 않아요.","③은 한 글자씩 끊어 읽어 리듬이 살지 않아요.","낭송하는 사람은 잘 들리게, 리듬을 살려 읽어요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"},"mis":"K6-2-u6-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#4','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C18',1,'ox','auto','시 낭송을 감상할 때에는 낭송하는 사람을 바라보며 들어요.',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":4,"concept":"K6-2-u6-C18","difficulty":1,"kind":"ox","stem":"시 낭송을 감상할 때에는 낭송하는 사람을 바라보며 들어요.","answer":"O","reason_options":[{"t":"집중해서 들어야 시에 담긴 경험과 마음을 느낄 수 있기 때문에","correct":true},{"t":"듣는 동안 옆 친구와 이야기해도 시는 들리기 때문에","mis":"K6-2-u6-X24"}],"mis":"K6-2-u6-X24","explanation":["『국어』 268쪽 감상할 때 주의할 점이에요.","낭송하는 사람을 바라보며 집중해서 들어요.","시와 관련 있는 경험을 떠올리며 감상하면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#5','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',2,'mc','auto','『국어』 268쪽 그림의 ①에게 해 줄 조언으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X23','K6-2-u6-X47']::text[],false,'{"seq":5,"concept":"K6-2-u6-C19","difficulty":2,"kind":"mc","stem":"『국어』 268쪽 그림의 ①에게 해 줄 조언으로 알맞은 것은 무엇인가요?","options":[{"t":"목소리가 너무 작아 들리지 않아. 잘 들리게 낭송해 줘.","correct":true},{"t":"마음은 상관없이 무조건 가장 크게 소리쳐.","mis":"K6-2-u6-X21"},{"t":"작아도 마음만 담겼으면 괜찮아.","mis":"K6-2-u6-X23"},{"t":"글자를 하나씩 끊어서 또박또박 읽어.","mis":"K6-2-u6-X47"}],"explanation":["①은 들리지 않을 만큼 작게 읽고 있어요.","시가 들려야 마음도 전해져요.","무조건 크게가 아니라 잘 들리게 읽어요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#6','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',2,'mc','auto','『국어』 268쪽 그림의 ③에게 해 줄 조언으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X47','K6-2-u6-X20','K6-2-u6-X21']::text[],false,'{"seq":6,"concept":"K6-2-u6-C19","difficulty":2,"kind":"mc","stem":"『국어』 268쪽 그림의 ③에게 해 줄 조언으로 알맞은 것은 무엇인가요?","options":[{"t":"분위기에 어울리는 목소리와 속도로 리듬을 살려 읽어 줘.","correct":true},{"t":"글자마다 끊어 읽으면 정확하니 그대로 해.","mis":"K6-2-u6-X47"},{"t":"모든 부분을 같은 목소리와 속도로 읽어.","mis":"K6-2-u6-X20"},{"t":"큰 소리로만 읽으면 돼.","mis":"K6-2-u6-X21"}],"explanation":["③은 「그, 랬, 어, 요.」 하고 끊어 읽어요.","시는 리듬을 살려 이어 읽어야 해요.","분위기에 맞는 목소리와 속도를 찾아요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#7','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C18',2,'mc','auto','『국어』 268쪽 그림의 ⑤에게 해 줄 조언으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X24','K6-2-u6-X25']::text[],false,'{"seq":7,"concept":"K6-2-u6-C18","difficulty":2,"kind":"mc","stem":"『국어』 268쪽 그림의 ⑤에게 해 줄 조언으로 알맞은 것은 무엇인가요?","options":[{"t":"장난치지 말고 낭송하는 사람을 바라보며 들어야 해.","correct":true},{"t":"틀린 글자가 있는지만 찾으며 들어.","mis":"K6-2-u6-X24"},{"t":"낭송이 끝나면 잘했다고만 말해 주면 돼.","mis":"K6-2-u6-X25"},{"t":"낭송하는 친구보다 크게 이야기해도 괜찮아.","mis":"K6-2-u6-X24"}],"explanation":["⑤는 감상하는 동안 장난을 치고 있어요.","감상할 때에도 지킬 점이 있어요.","낭송하는 사람을 바라보며 집중해서 들어요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#8','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',2,'mc','auto','배드민턴 시를 낭송할 때 서브를 넣기 전까지는 숨을 내쉬면서 느린 속도로 읽으려고 해요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X20','K6-2-u6-X23']::text[],false,'{"seq":8,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"배드민턴 시를 낭송할 때 서브를 넣기 전까지는 숨을 내쉬면서 느린 속도로 읽으려고 해요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"서브를 넣기 전 긴장되는 마음을 잘 전하려고","correct":true},{"t":"빨리 끝내기 싫어서","mis":"K6-2-u6-X20"},{"t":"목소리를 작게 하려고","mis":"K6-2-u6-X23"},{"t":"모든 부분을 같은 속도로 읽으려고","mis":"K6-2-u6-X20"}],"explanation":["이 시에서 전하고 싶은 마음은 서브 전의 긴장이에요.","느린 속도는 긴장되는 순간을 살려 줘요.","공이 오고 갈 때에는 빠른 속도로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#9','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',2,'ox','auto','효과음이나 배경 음악은 낭송하는 목소리보다 크게 틀어야 해요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":9,"concept":"K6-2-u6-C17","difficulty":2,"kind":"ox","stem":"효과음이나 배경 음악은 낭송하는 목소리보다 크게 틀어야 해요.","answer":"X","reason_options":[{"t":"효과음과 음악은 낭송을 돕는 만큼만, 목소리보다 크지 않게 써야 하기 때문에","correct":true},{"t":"음악이 클수록 시의 분위기가 더 잘 살기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["효과음과 배경 음악은 낭송을 돕는 것이에요.","목소리보다 크면 시가 들리지 않아요.","낭송하는 목소리가 주인공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_basic#10','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',3,'mc','auto','전자 칠판으로 시와 어울리는 영상을 함께 보여 줄 때 주의할 점은 무엇인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":10,"concept":"K6-2-u6-C17","difficulty":3,"kind":"mc","stem":"전자 칠판으로 시와 어울리는 영상을 함께 보여 줄 때 주의할 점은 무엇인가요?","options":[{"t":"영상이 지나치게 화려하면 시 낭송의 흐름을 방해할 수 있으니 주의한다","correct":true},{"t":"영상은 화려할수록 친구들이 더 집중한다","mis":"K6-2-u6-X22"},{"t":"영상만 보여 주고 낭송은 하지 않아도 된다","mis":"K6-2-u6-X20"},{"t":"시와 상관없어도 인기 있는 영상이면 된다","mis":"K6-2-u6-X22"}],"explanation":["영상은 시의 장면을 떠올리게 도와요.","너무 화려하면 시보다 영상에 눈이 가요.","시 낭송의 흐름을 방해하지 않게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#1','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',2,'mc','auto','친구의 시 낭송을 감상하고 잘한 점을 쓴 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X24']::text[],false,'{"seq":1,"concept":"K6-2-u6-C18","difficulty":2,"kind":"mc","stem":"친구의 시 낭송을 감상하고 잘한 점을 쓴 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"배경 음악과 시가 어울려서 시의 장면이 생생하게 떠올랐어.","correct":true},{"t":"잘했어. 정말 멋진 낭송이었어.","mis":"K6-2-u6-X25"},{"t":"시를 적은 종이를 예쁘게 꾸며서 좋았어.","mis":"K6-2-u6-X25"},{"t":"틀린 글자가 두 개 있었으니 고쳐야 해.","mis":"K6-2-u6-X24"}],"explanation":["『국어』 269쪽 점검하기 (1)의 예시 답안이에요.","어느 부분이 왜 좋았는지 구체적으로 써요.","틀린 곳 찾기는 잘한 점 쓰기가 아니에요."],"asset":{"type":"passage","lines":["[친구의 시 낭송을 감상하고 잘한 점]","서연 — 배경 음악과 시가 어울려서 시의 장면이 생생하게 떠올랐어.","동욱 — 감각적 표현을 사용해 경험을 시로 재미있게 표현했어."],"numbered":false,"title":"친구의 시 낭송 감상하기 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#2','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C19',2,'mc','auto','『국어』 269쪽 시 낭송회 스스로 확인하기에 들어 있는 물음은 무엇인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":2,"concept":"K6-2-u6-C19","difficulty":2,"kind":"mc","stem":"『국어』 269쪽 시 낭송회 스스로 확인하기에 들어 있는 물음은 무엇인가요?","options":[{"t":"시의 내용에 어울리는 목소리와 속도로 시를 낭송했나요?","correct":true},{"t":"가장 큰 목소리로 처음부터 끝까지 낭송했나요?","mis":"K6-2-u6-X21"},{"t":"배경 음악을 목소리보다 크게 틀었나요?","mis":"K6-2-u6-X22"},{"t":"친구들보다 가장 빨리 낭송을 끝냈나요?","mis":"K6-2-u6-X20"}],"explanation":["스스로 확인하기는 계획부터 감상까지 돌아봐요.","시의 분위기에 맞게 계획했는지, 어울리는 목소리와 속도였는지 살펴요.","친구 낭송을 집중해 들었는지도 확인해요."],"asset":{"type":"passage","lines":["• 시의 분위기에 알맞게 시 낭송을 계획했나요?","• 시의 내용에 어울리는 목소리와 속도로 시를 낭송했나요?","• 친구가 시를 낭송할 때 집중하며 들었나요?","• 어떤 경험을 시로 표현했는지 생각하며 감상했나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"시 낭송회 스스로 확인하기 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#3','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',3,'error','auto','시 낭송 계획을 세우며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X20','K6-2-u6-X21','K6-2-u6-X47']::text[],false,'{"seq":3,"concept":"K6-2-u6-C16","difficulty":3,"kind":"error","stem":"시 낭송 계획을 세우며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「시는 겪은 일을 알려 주는 글이니까 뉴스처럼 처음부터 끝까지 같은 목소리로 읽을래.」","correct":true,"mis_target":"K6-2-u6-X20"},{"t":"친구 1 — 「여러 가지 방법으로 읽어 보고 시에 어울리는 목소리와 속도를 찾을래.」","mis":"K6-2-u6-X21"},{"t":"친구 2 — 「긴장되는 장면은 느리게, 신나는 장면은 빠르게 읽을래.」","mis":"K6-2-u6-X47"}],"explanation":["시는 단순히 경험을 전달하는 글이 아니에요.","말하는 이의 마음을 담고 있어요.","장면마다 마음에 어울리는 목소리와 속도를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#4','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',3,'match','auto','『국어』 267쪽 낭송 계획 예시에서 시의 장면과 그에 어울리는 목소리나 속도를 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u6-C16","difficulty":3,"kind":"match","stem":"『국어』 267쪽 낭송 계획 예시에서 시의 장면과 그에 어울리는 목소리나 속도를 알맞게 이으세요.","pairs":[{"l":"서브를 넣기 전","r":"숨을 내쉬면서 느린 속도"},{"l":"공이 그물 위를 오고 갈 때","r":"빠른 속도"},{"l":"공이 튀어 오를 때","r":"경쾌한 목소리"}],"mis":"K6-2-u6-X20","explanation":["장면마다 마음이 달라져요.","긴장되는 순간은 느리게, 바쁘게 오가는 순간은 빠르게 읽어요.","공이 튀어 오르는 순간은 경쾌하게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#5','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',3,'mc','auto','『국어』 268쪽 그림에서 감상할 때 주의할 점을 잘 지킨 친구들의 다짐으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":5,"concept":"K6-2-u6-C18","difficulty":3,"kind":"mc","stem":"『국어』 268쪽 그림에서 감상할 때 주의할 점을 잘 지킨 친구들의 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"집중해서 듣고, 시와 관련 있는 경험을 떠올리며 감상한다","correct":true},{"t":"옆 친구와 이야기하며 편하게 듣는다","mis":"K6-2-u6-X24"},{"t":"틀린 글자만 찾아 적으며 듣는다","mis":"K6-2-u6-X24"}],"explanation":["④는 「집중해서 들어야지.」라고 다짐했어요.","⑥은 시와 관련 있는 경험을 떠올리며 감상하겠다고 했어요.","그래야 시에 담긴 마음을 함께 느낄 수 있어요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#6','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',3,'mc','auto','배드민턴 서브 전 긴장되는 마음을 전하려는 시에 효과음을 넣으려고 해요. 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":6,"concept":"K6-2-u6-C17","difficulty":3,"kind":"mc","stem":"배드민턴 서브 전 긴장되는 마음을 전하려는 시에 효과음을 넣으려고 해요. 가장 알맞은 것은 무엇인가요?","options":[{"t":"심장 박동 소리를 목소리보다 작게 넣는다","correct":true},{"t":"시와 상관없이 가장 신나는 노래를 크게 튼다","mis":"K6-2-u6-X22"},{"t":"효과음은 많을수록 좋으니 여러 소리를 한꺼번에 넣는다","mis":"K6-2-u6-X22"},{"t":"목소리가 안 들릴 만큼 큰 박수 소리를 넣는다","mis":"K6-2-u6-X22"}],"explanation":["효과음은 전하고 싶은 마음에 어울려야 해요.","심장 박동 소리는 긴장감을 살려 줘요.","목소리보다 크지 않게 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#7','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C19',3,'ox','auto','시 낭송을 잘한다는 것은 시에 담긴 마음이 듣는 사람에게 잘 전해지도록 읽는 것이에요.',ARRAY['K6-2-u6-X21']::text[],false,'{"seq":7,"concept":"K6-2-u6-C19","difficulty":3,"kind":"ox","stem":"시 낭송을 잘한다는 것은 시에 담긴 마음이 듣는 사람에게 잘 전해지도록 읽는 것이에요.","answer":"O","reason_options":[{"t":"목소리와 속도, 효과음은 모두 마음을 전하려고 고르는 것이기 때문에","correct":true},{"t":"가장 큰 목소리로 실수 없이 읽기만 하면 되기 때문에","mis":"K6-2-u6-X21"}],"mis":"K6-2-u6-X21","explanation":["낭송은 시의 마음을 소리로 전하는 일이에요.","목소리와 속도는 마음에 맞추어 골라요.","크게만 읽는다고 마음이 전해지지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#8','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',4,'essay','teacher','자신이 쓴 시(또는 이 단원에서 읽은 시 한 편)를 낭송할 계획을 『국어』 267쪽처럼 세우세요. 꼭 전하고 싶은 마음, 어울리는 목소리와 속도, 마음을 전하는 다른 방법을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C16","difficulty":4,"kind":"essay","stem":"자신이 쓴 시(또는 이 단원에서 읽은 시 한 편)를 낭송할 계획을 『국어』 267쪽처럼 세우세요. 꼭 전하고 싶은 마음, 어울리는 목소리와 속도, 마음을 전하는 다른 방법을 쓰세요.","answer_guide":{"answer":"예: 「눈꺼풀」을 낭송하겠다. 전하고 싶은 마음은 졸음을 참으려고 애쓰는 마음이다. 「꾸벅 꾸우벅」은 졸린 목소리로 느리게, 「세상에서 가장 무거운 풀」은 무겁고 힘겨운 목소리로 읽겠다. 다른 방법으로 하품 소리 같은 효과음을 목소리보다 작게 넣겠다.","scoring_points":["전하고 싶은 마음을 정했는가","마음에 맞는 목소리와 속도를 장면별로 썼는가","다른 방법을 목소리보다 크지 않게 계획했는가"]},"explanation":["먼저 전하고 싶은 마음을 정해요.","장면마다 목소리와 속도를 마음에 맞추어요.","효과음·음악·영상은 돕는 만큼만 써요."],"asset":{"type":"passage","lines":["(1) 전하고 싶은 마음 — 배드민턴 서브를 넣기 전 긴장되는 마음","(2) 목소리 — 공이 그물을 넘어가기를 바라는 간절한 목소리,","공이 튀어 오를 때에는 경쾌한 목소리","(2) 속도 — 서브를 넣기 전까지는 숨을 내쉬면서 느린 속도,","공이 그물 위를 오고 갈 때에는 빠른 속도","(3) 다른 방법 — 심장 박동 소리 같은 효과음 · 긴장감이 고조되는 음악","· 시와 어울리는 영상"],"numbered":false,"title":"시 낭송 계획 예시 — 『국어』 267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#9','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',4,'essay','teacher','『국어』 268쪽 그림에서 주의할 점을 지키지 않은 친구 가운데 낭송하는 친구 한 명과 감상하는 친구 한 명을 골라 번호를 쓰고, 각각 알맞은 조언을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C18","difficulty":4,"kind":"essay","stem":"『국어』 268쪽 그림에서 주의할 점을 지키지 않은 친구 가운데 낭송하는 친구 한 명과 감상하는 친구 한 명을 골라 번호를 쓰고, 각각 알맞은 조언을 쓰세요.","answer_guide":{"answer":"예: ③에게 — 한 글자씩 끊어 읽으면 시의 리듬이 살지 않아. 시의 분위기에 어울리는 목소리와 속도로 이어 읽어 줘. ⑤에게 — 친구가 낭송할 때 장난치지 말고 낭송하는 사람을 바라보며 집중해서 들어 줘.","scoring_points":["낭송하는 친구(① 또는 ③)를 바르게 골랐는가","감상하는 친구(⑤)를 바르게 골랐는가","조언이 무엇을 어떻게 하라는지 구체적인가"]},"explanation":["①은 너무 작게, ③은 끊어 읽었어요.","⑤는 감상하며 장난을 쳤어요.","조언은 무엇을 어떻게 고치면 되는지 구체적으로 해요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L06_challenge#10','kor',6,2,'u6','L06','tb_g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C19',4,'essay','teacher','『국어』 269쪽 스스로 확인하기 물음 가운데 두 가지를 골라 시 낭송회를 할 때 자신은 어땠을지 돌아보고, 다음에 더 잘하려면 무엇을 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C19","difficulty":4,"kind":"essay","stem":"『국어』 269쪽 스스로 확인하기 물음 가운데 두 가지를 골라 시 낭송회를 할 때 자신은 어땠을지 돌아보고, 다음에 더 잘하려면 무엇을 할지 쓰세요.","answer_guide":{"answer":"예: 「시의 분위기에 알맞게 시 낭송을 계획했나요?」 — 전하고 싶은 마음을 먼저 정해서 잘했다. 「친구가 시를 낭송할 때 집중하며 들었나요?」 — 다음 차례를 걱정하느라 집중하지 못한 때가 있었다. 다음에는 친구를 바라보며 들으며 그 시와 비슷한 내 경험을 떠올리겠다.","scoring_points":["스스로 확인하기 물음을 두 가지 골랐는가","자신을 솔직하게 돌아보았는가","다음에 할 일을 구체적으로 썼는가"]},"explanation":["스스로 확인하기는 계획·낭송·감상을 모두 돌아봐요.","잘한 점과 부족한 점을 함께 살펴요.","다음에 할 일을 구체적으로 정해요."],"asset":{"type":"passage","lines":["• 시의 분위기에 알맞게 시 낭송을 계획했나요?","• 시의 내용에 어울리는 목소리와 속도로 시를 낭송했나요?","• 친구가 시를 낭송할 때 집중하며 들었나요?","• 어떤 경험을 시로 표현했는지 생각하며 감상했나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"시 낭송회 스스로 확인하기 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#1','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C38',1,'mc','auto','「알라딘과 요술 램프」에서 알라딘과 어머니가 낯선 남자를 삼촌이라고 믿은 까닭은 무엇인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C38","difficulty":1,"kind":"mc","stem":"「알라딘과 요술 램프」에서 알라딘과 어머니가 낯선 남자를 삼촌이라고 믿은 까닭은 무엇인가요?","options":[{"t":"귀한 선물을 잔뜩 가지고 왔고, 말을 잘하는 데다 친절했기 때문","correct":true},{"t":"남자가 아버지와 똑같이 생겼기 때문","mis":"K6-2-u6-X07"},{"t":"어머니가 남자를 예전부터 잘 알았기 때문","mis":"K6-2-u6-X07"},{"t":"남자가 반지 요정을 보여 주었기 때문","mis":"K6-2-u6-X07"}],"explanation":["『국어』 274쪽 2번 (1)의 물음이에요.","남자는 귀한 선물을 가지고 찾아왔어요.","말을 잘하고 친절해서 진짜 삼촌이라고 믿게 되었어요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#2','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C38',1,'mc','auto','「알라딘과 요술 램프」에서 알라딘이 동굴에 갇히게 된 까닭은 무엇인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":2,"concept":"K6-2-u6-C38","difficulty":1,"kind":"mc","stem":"「알라딘과 요술 램프」에서 알라딘이 동굴에 갇히게 된 까닭은 무엇인가요?","options":[{"t":"삼촌에게 램프를 먼저 주지 않았기 때문","correct":true},{"t":"램프를 찾지 못했기 때문","mis":"K6-2-u6-X07"},{"t":"보물을 너무 많이 가져왔기 때문","mis":"K6-2-u6-X07"},{"t":"반지를 잃어버렸기 때문","mis":"K6-2-u6-X07"}],"explanation":["삼촌은 램프를 먼저 내놓으라고 했어요.","알라딘은 먼저 꺼내 달라며 램프를 주지 않았어요.","그러자 삼촌은 화를 내며 돌문을 닫았어요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#3','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C38',1,'sa','auto','「알라딘과 요술 램프」에서 알라딘은 무엇으로 램프의 먼지를 닦아 요정을 불러냈나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C38","difficulty":1,"kind":"sa","stem":"「알라딘과 요술 램프」에서 알라딘은 무엇으로 램프의 먼지를 닦아 요정을 불러냈나요? 세 글자로 쓰세요.","answer":["옷자락"],"explanation":["『국어』 274쪽 2번 (3)의 물음이에요.","알라딘은 램프를 자세히 보려고 먼지를 닦았어요.","옷자락으로 닦자 램프의 요정 지니가 나타났어요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"},"mis":"K6-2-u6-X50"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#4','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C39',1,'ox','auto','「알라딘과 신기한 램프」의 알라딘은 지니가 권한 궁전과 보물을 받았어요.',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":4,"concept":"K6-2-u6-C39","difficulty":1,"kind":"ox","stem":"「알라딘과 신기한 램프」의 알라딘은 지니가 권한 궁전과 보물을 받았어요.","answer":"X","reason_options":[{"t":"그것들이 쓸모없다고 생각해 거절하고 전쟁을 없애 달라고 했기 때문에","correct":true},{"t":"보물을 가지고 싶지 않다는 말은 장난이었기 때문에","mis":"K6-2-u6-X07"}],"mis":"K6-2-u6-X07","explanation":["글 ㉯의 알라딘은 보물도, 궁전도 거절했어요.","알라딘은 더 쓸모 있는 것을 원했어요.","그래서 전쟁을 없애 달라는 소원을 빌었어요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#5','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C39',2,'mc','auto','「알라딘과 신기한 램프」에서 알라딘이 황금과 보석을 가지고 싶어 하지 않은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C39","difficulty":2,"kind":"mc","stem":"「알라딘과 신기한 램프」에서 알라딘이 황금과 보석을 가지고 싶어 하지 않은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"보석에 대해 잘 모르고, 보물이 함정일지도 모른다고 생각했기 때문","correct":true},{"t":"지니가 가져온 보석이 모두 가짜였기 때문","mis":"K6-2-u6-X07"},{"t":"보석이 너무 무거워 융단에 실을 수 없었기 때문","mis":"K6-2-u6-X07"},{"t":"삼촌에게 이미 보석을 잔뜩 받았기 때문","mis":"K6-2-u6-X07"}],"explanation":["『국어』 278쪽 3번 (1)의 물음이에요.","알라딘은 보석에 대해 아는 게 없다고 했어요.","그 보물이 함정일지도 모른다고 생각했어요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#6','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C39',2,'mc','auto','「알라딘과 신기한 램프」에서 지니는 알라딘의 소원을 듣고 어떻게 반응했나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":6,"concept":"K6-2-u6-C39","difficulty":2,"kind":"mc","stem":"「알라딘과 신기한 램프」에서 지니는 알라딘의 소원을 듣고 어떻게 반응했나요?","options":[{"t":"익숙하지 않은 일이라며 놀랐다","correct":true},{"t":"기뻐하며 바로 춤을 추었다","mis":"K6-2-u6-X07"},{"t":"화를 내며 램프 속으로 돌아갔다","mis":"K6-2-u6-X07"},{"t":"그런 소원은 들어줄 수 없다며 떠났다","mis":"K6-2-u6-X07"}],"explanation":["이전의 주인들은 적을 물리치는 것 같은 일을 원했어요.","평화는 지니에게 낯선 일이었어요.","그래서 놀란 눈으로 익숙하지 않다고 대답했어요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#7','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C39',2,'match','auto','『국어』 279쪽처럼 두 글의 인물과 그 성격을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u6-C39","difficulty":2,"kind":"match","stem":"『국어』 279쪽처럼 두 글의 인물과 그 성격을 알맞게 이으세요.","pairs":[{"l":"글 ㉮의 알라딘","r":"지혜롭지만 욕심이 많음"},{"l":"글 ㉯의 알라딘","r":"이타적이고 욕심이 없음"},{"l":"글 ㉮의 지니","r":"맡은 일을 충실히 해냄"},{"l":"글 ㉯의 지니","r":"성질이 급하고 지기 싫어함"}],"mis":"K6-2-u6-X33","explanation":["인물이 한 말과 선택을 보면 성격을 알 수 있어요.","글 ㉯의 알라딘은 남을 위한 소원을 골랐어요.","글 ㉮의 지니는 시키는 일을 충실히 해냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#8','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C21',2,'blank','auto','『국어』 281쪽 주의할 점이에요. 「이야기의 세 가지 요소 가운데에서 (    )을/를 바꾸면 사건이 어떻게 달라질지 생각하며 쓴다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X46','K6-2-u6-X05']::text[],false,'{"seq":8,"concept":"K6-2-u6-C21","difficulty":2,"kind":"blank","stem":"『국어』 281쪽 주의할 점이에요. 「이야기의 세 가지 요소 가운데에서 (    )을/를 바꾸면 사건이 어떻게 달라질지 생각하며 쓴다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"인물이나 배경","correct":true},{"t":"주장과 근거","mis":"K6-2-u6-X46"},{"t":"원인과 결과","mis":"K6-2-u6-X05"},{"t":"자신의 경험","mis":"K6-2-u6-X05"}],"explanation":["이야기의 세 가지 요소는 인물, 배경, 사건이에요.","인물이나 배경을 바꾸면 사건도 달라져요.","주장과 근거는 이야기의 요소가 아니에요."],"asset":{"type":"passage","lines":["보기: 주장과 근거 · 자신의 경험 · 원인과 결과 · 인물이나 배경","● 이야기를 자신이 잘 알거나 익숙한 내용으로 바꾸고 싶을 때에는","(  ㉠  )을/를 떠올려 본다.","● 이야기의 세 가지 요소 가운데에서 (  ㉡  )을/를 바꾸면","사건이 어떻게 달라질지 생각하며 쓴다.","● 사건 사이의 (  ㉢  )을/를 생각하며 이야기를 바꾸어 쓴다."],"numbered":false,"title":"이야기를 바꾸어 쓸 때 주의할 점 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#9','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C20',2,'ox','auto','유명한 원작을 비틀어 새로운 메시지를 만드는 패러디는 표절과 같아요.',ARRAY['K6-2-u6-X26']::text[],false,'{"seq":9,"concept":"K6-2-u6-C20","difficulty":2,"kind":"ox","stem":"유명한 원작을 비틀어 새로운 메시지를 만드는 패러디는 표절과 같아요.","answer":"X","reason_options":[{"t":"패러디는 원작을 바탕으로 새로운 뜻을 만들어 내기 때문에","correct":true},{"t":"원작의 인물이 나오면 모두 베낀 것이기 때문에","mis":"K6-2-u6-X26"}],"mis":"K6-2-u6-X26","explanation":["「알라딘과 신기한 램프」는 원래 알라딘 이야기를 비틀어 썼어요.","원작을 바탕으로 새로운 메시지를 만드는 것이 패러디예요.","그대로 베끼는 표절과는 구분돼요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_basic#10','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C23',3,'mc','auto','이야기를 바꾸어 쓸 때 사건을 이어 가는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X46']::text[],false,'{"seq":10,"concept":"K6-2-u6-C23","difficulty":3,"kind":"mc","stem":"이야기를 바꾸어 쓸 때 사건을 이어 가는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"앞의 일이 원인이 되어 뒤의 일이 일어나도록 원인과 결과를 생각하며 잇는다","correct":true},{"t":"앞의 일과 상관없는 놀라운 사건을 갑자기 넣는다","mis":"K6-2-u6-X29"},{"t":"사건마다 마무리 없이 새 사건을 계속 벌인다","mis":"K6-2-u6-X29"},{"t":"주장과 근거가 잘 드러나게 쓴다","mis":"K6-2-u6-X46"}],"explanation":["사건은 원인과 결과로 촘촘하게 이어져요.","엉뚱하고 갑작스러운 사건이 계속되면 안 돼요.","한 사건에는 그에 알맞은 마무리가 있어야 해요."],"asset":{"type":"passage","lines":["보기: 주장과 근거 · 자신의 경험 · 원인과 결과 · 인물이나 배경","● 이야기를 자신이 잘 알거나 익숙한 내용으로 바꾸고 싶을 때에는","(  ㉠  )을/를 떠올려 본다.","● 이야기의 세 가지 요소 가운데에서 (  ㉡  )을/를 바꾸면","사건이 어떻게 달라질지 생각하며 쓴다.","● 사건 사이의 (  ㉢  )을/를 생각하며 이야기를 바꾸어 쓴다."],"numbered":false,"title":"이야기를 바꾸어 쓸 때 주의할 점 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#1','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C38',2,'mc','auto','「알라딘과 요술 램프」에서 램프의 요정 지니가 나타난 바로 다음에 일어난 일은 무엇인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":1,"concept":"K6-2-u6-C38","difficulty":2,"kind":"mc","stem":"「알라딘과 요술 램프」에서 램프의 요정 지니가 나타난 바로 다음에 일어난 일은 무엇인가요?","options":[{"t":"알라딘이 배가 고프다고 하자 지니가 음식을 차려 주었다","correct":true},{"t":"반지 요정의 도움으로 집에 돌아왔다","mis":"K6-2-u6-X34"},{"t":"부자가 되고 싶다는 소원으로 보물을 얻었다","mis":"K6-2-u6-X34"},{"t":"삼촌이 돌문을 닫았다","mis":"K6-2-u6-X34"}],"explanation":["『국어』 280쪽 5번에서 사건을 차례대로 정리했어요.","지니가 소원을 들어주겠다고 하자 알라딘은 먹을 것을 청했어요.","그다음에 부자가 되고 싶다는 소원을 빌었어요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#2','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C22',2,'mc','auto','『국어』 279쪽에서 정리한 글 ㉯의 배경을 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['K6-2-u6-X28']::text[],false,'{"seq":2,"concept":"K6-2-u6-C22","difficulty":2,"kind":"mc","stem":"『국어』 279쪽에서 정리한 글 ㉯의 배경을 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"동굴 → 하늘을 나는 융단 위 → 알라딘의 집","correct":true},{"t":"시장 → 알라딘의 집 → 동굴 → 알라딘의 집","mis":"K6-2-u6-X28"},{"t":"시장 → 하늘을 나는 융단 위 → 동굴","mis":"K6-2-u6-X28"},{"t":"알라딘의 집 → 동굴 → 시장","mis":"K6-2-u6-X28"}],"explanation":["글 ㉮는 시장, 알라딘의 집, 동굴, 알라딘의 집으로 이어져요.","글 ㉯는 동굴, 하늘을 나는 융단 위, 알라딘의 집이에요.","두 글은 이야기 전체가 아니라 일부라 배경이 다르게 정리돼요."],"asset":{"type":"passage","lines":["[표] 인물의 성격","알라딘 — 글 ㉮ 지혜롭지만 욕심이 많음 · 글 ㉯ 이타적이고 욕심이 없음","지니 — 글 ㉮ 맡은 일을 충실히 해냄 · 글 ㉯ 성질이 급하고 지기 싫어함","[표] 배경","글 ㉮ 시장 → 알라딘의 집 → 동굴 → 알라딘의 집","글 ㉯ 동굴 → 하늘을 나는 융단 위 → 알라딘의 집"],"numbered":false,"title":"두 글의 인물과 배경 — 『국어』 279쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#3','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C39',3,'mc','auto','알라딘이 요술 램프를 가지게 된 뒤 두 글의 사건이 가장 크게 달라진 부분은 무엇인가요?',ARRAY['K6-2-u6-X06','K6-2-u6-X07']::text[],false,'{"seq":3,"concept":"K6-2-u6-C39","difficulty":3,"kind":"mc","stem":"알라딘이 요술 램프를 가지게 된 뒤 두 글의 사건이 가장 크게 달라진 부분은 무엇인가요?","options":[{"t":"글 ㉮는 부자가 되는 소원을, 글 ㉯는 전쟁을 없애는 소원을 빌었다","correct":true},{"t":"두 글의 알라딘은 똑같이 부자가 되는 소원을 빌었다","mis":"K6-2-u6-X06"},{"t":"글 ㉯의 알라딘은 아무 소원도 빌지 않고 집에 갔다","mis":"K6-2-u6-X07"},{"t":"두 글은 배경만 다르고 사건은 똑같이 흘러간다","mis":"K6-2-u6-X06"}],"explanation":["가장 핵심적인 부분은 알라딘이 소원을 청하는 장면이에요.","글 ㉮는 보석과 보물을 얻는 쪽으로 흘러가요.","글 ㉯는 무기를 사라지게 하는 쪽으로 흘러가요."],"asset":{"type":"passage","lines":["글 ㉮ ① 반지 요정의 도움으로 램프를 가지고 집으로 돌아옴.","② 지니가 나타나 소원을 들어주겠다고 말함.","③ 배가 고프다고 하자 지니가 음식을 차려 줌.","④ 부자가 되고 싶다는 소원을 빌고, 보석과 보물을 얻음.","글 ㉯ ① 지니의 도움으로 융단을 타고 집으로 돌아옴.","② 지니가 부와 권력을 얻게 해 주겠다고 권함.","③ 그런 소원은 빌고 싶지 않다고 말함.","④ 전쟁을 없애고 무기를 사라지게 해 달라고 빌고, 이루어짐."],"numbered":false,"title":"요술 램프를 가지게 된 뒤 사건 전개 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#4','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C21',3,'mc','auto','「알라딘과 신기한 램프」에서 알라딘의 성격이 바뀌자 이야기에서 무엇이 함께 달라졌나요?',ARRAY['K6-2-u6-X27','K6-2-u6-X45','K6-2-u6-X05']::text[],false,'{"seq":4,"concept":"K6-2-u6-C21","difficulty":3,"kind":"mc","stem":"「알라딘과 신기한 램프」에서 알라딘의 성격이 바뀌자 이야기에서 무엇이 함께 달라졌나요?","options":[{"t":"보물과 권력 대신 사람들을 위하는 소원을 고르는 선택","correct":true},{"t":"성격만 바뀌고 알라딘이 한 일은 글 ㉮와 똑같다","mis":"K6-2-u6-X27"},{"t":"알라딘이 아가씨로 바뀌어서 욕심이 없어졌다","mis":"K6-2-u6-X45"},{"t":"배경이 시장에서 궁전으로 바뀌었다","mis":"K6-2-u6-X05"}],"explanation":["성격이 바뀌면 인물이 하는 말과 선택이 달라져요.","욕심 없는 알라딘은 전쟁을 없애는 소원을 골랐어요.","성별 때문이 아니라 인물이 한 선택에서 성격이 드러나요."],"asset":{"type":"passage","lines":["글 ㉮ ① 반지 요정의 도움으로 램프를 가지고 집으로 돌아옴.","② 지니가 나타나 소원을 들어주겠다고 말함.","③ 배가 고프다고 하자 지니가 음식을 차려 줌.","④ 부자가 되고 싶다는 소원을 빌고, 보석과 보물을 얻음.","글 ㉯ ① 지니의 도움으로 융단을 타고 집으로 돌아옴.","② 지니가 부와 권력을 얻게 해 주겠다고 권함.","③ 그런 소원은 빌고 싶지 않다고 말함.","④ 전쟁을 없애고 무기를 사라지게 해 달라고 빌고, 이루어짐."],"numbered":false,"title":"요술 램프를 가지게 된 뒤 사건 전개 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#5','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C39',3,'error','auto','두 글의 인물이 어떻게 달라졌는지 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X45','K6-2-u6-X33']::text[],false,'{"seq":5,"concept":"K6-2-u6-C39","difficulty":3,"kind":"error","stem":"두 글의 인물이 어떻게 달라졌는지 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「글 ㉯의 알라딘은 아가씨라서 욕심이 없는 거야.」","correct":true,"mis_target":"K6-2-u6-X45"},{"t":"친구 1 — 「글 ㉯의 알라딘은 보물보다 쓸모 있는 것을 원하는 선택에서 성격이 드러나.」","mis":"K6-2-u6-X33"},{"t":"친구 2 — 「지니는 성격보다 한 일을 중심으로 다른 점을 찾으면 돼.」","mis":"K6-2-u6-X33"}],"explanation":["글 ㉯에서 알라딘이 아가씨로 바뀌지만 그 때문에 크게 달라지는 점은 없어요.","성격 차이를 남녀의 차이로 넓혀 풀이하지 않아요.","인물이 한 말과 선택에서 성격을 찾아요."],"asset":{"type":"passage","lines":["[표] 인물의 성격","알라딘 — 글 ㉮ 지혜롭지만 욕심이 많음 · 글 ㉯ 이타적이고 욕심이 없음","지니 — 글 ㉮ 맡은 일을 충실히 해냄 · 글 ㉯ 성질이 급하고 지기 싫어함","[표] 배경","글 ㉮ 시장 → 알라딘의 집 → 동굴 → 알라딘의 집","글 ㉯ 동굴 → 하늘을 나는 융단 위 → 알라딘의 집"],"numbered":false,"title":"두 글의 인물과 배경 — 『국어』 279쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#6','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C25',3,'blank','auto','『국어』 281쪽 이야기를 바꾸어 쓸 때 생각할 점의 예시 답안이에요. 「상상한 이야기의 처음, 가운데, 끝이 (    ) 이어지나요?」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X46','K6-2-u6-X31']::text[],false,'{"seq":6,"concept":"K6-2-u6-C25","difficulty":3,"kind":"blank","stem":"『국어』 281쪽 이야기를 바꾸어 쓸 때 생각할 점의 예시 답안이에요. 「상상한 이야기의 처음, 가운데, 끝이 (    ) 이어지나요?」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"자연스럽게","correct":true},{"t":"놀랍고 갑작스럽게","mis":"K6-2-u6-X30"},{"t":"주장과 근거로","mis":"K6-2-u6-X46"},{"t":"일기처럼 겪은 그대로","mis":"K6-2-u6-X31"}],"explanation":["이야기를 바꾸어 쓸 때 생각할 점을 물음으로 정리했어요.","인물·시간과 공간·표현하고 싶은 생각·비슷한 경험을 물어요.","처음, 가운데, 끝이 자연스럽게 이어지는지도 살펴요."],"asset":{"type":"speech","turns":[{"who":"물음 1","text":"이야기의 인물을 어떤 인물로 바꾸고 싶나요?"},{"who":"물음 2","text":"자신이 이야기로 표현하고 싶은 생각은 무엇인가요? 그 까닭은 무엇인가요?"},{"who":"물음 3","text":"자신에게 익숙하거나 자신이 잘 표현할 수 있는 시간과 공간이 있나요?"},{"who":"물음 4","text":"이야기와 비슷한 사건을 경험해 보거나 들어 본 적이 있나요?"},{"who":"물음 5","text":"상상한 이야기의 처음, 가운데, 끝이 자연스럽게 이어지나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#7','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C20',3,'mc','auto','「흑설 공주 이야기」에서 왕비는 거울이 흑설 공주를 가장 예쁘다고 할 것이라면서도 화를 내지 않았어요. 옛이야기를 이렇게 바꾸어 쓴 것에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X06','K6-2-u6-X26','K6-2-u6-X32']::text[],false,'{"seq":7,"concept":"K6-2-u6-C20","difficulty":3,"kind":"mc","stem":"「흑설 공주 이야기」에서 왕비는 거울이 흑설 공주를 가장 예쁘다고 할 것이라면서도 화를 내지 않았어요. 옛이야기를 이렇게 바꾸어 쓴 것에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"왕비의 성격을 바꾸니 신하의 꾀가 통하지 않는 새로운 사건이 생겼다","correct":true},{"t":"인물의 성격을 바꾸어도 사건은 원래와 똑같다","mis":"K6-2-u6-X06"},{"t":"원작을 바꾸어 쓰는 것은 모두 표절이다","mis":"K6-2-u6-X26"},{"t":"글을 길게 늘이려고 바꾼 것일 뿐이다","mis":"K6-2-u6-X32"}],"explanation":["옛이야기를 바꾸어 쓴 작품은 어떤 부분이 바뀌었는지 찾아봐요.","왕비가 질투하지 않으니 신하는 뜻을 이루지 못했어요.","작가는 왜 이렇게 바꾸었을까 하고 생각해 보아요."],"asset":{"type":"passage","lines":["(간추림) 흑설 공주의 어머니가 죽은 뒤, 왕은 마법사와 다시 혼인했다.","(간추림) 청혼을 거절당한 신하가 왕비에게 마법 거울에 물어보라고 부추겼다.","(간추림) 왕비는 거울이 흑설 공주라고 답할 것이고 자신도 그렇게 생각한다며 웃었다.","(간추림) 신하는 왕비를 통해 제 뜻을 이룰 수 없음을 깨닫고 가 버렸다."],"numbered":false,"title":"옛이야기를 바꾸어 쓴 「흑설 공주 이야기」 줄거리 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#8','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C25',4,'essay','teacher','『국어』 281쪽 6번 (3)처럼 글 ㉮를 어떻게 바꾸어 쓰고 싶은지 생각해 보세요. 바꾸고 싶은 인물이나 시간과 공간, 이야기로 표현하고 싶은 생각, 그와 관련된 자신의 경험을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C25","difficulty":4,"kind":"essay","stem":"『국어』 281쪽 6번 (3)처럼 글 ㉮를 어떻게 바꾸어 쓰고 싶은지 생각해 보세요. 바꾸고 싶은 인물이나 시간과 공간, 이야기로 표현하고 싶은 생각, 그와 관련된 자신의 경험을 쓰세요.","answer_guide":{"answer":"예: 시간과 공간을 요즘 우리 학교로 바꾸고 싶다. 알라딘이 교실 사물함에서 요술 램프를 발견하는 이야기로 쓰겠다. 바라는 것을 다 얻는 것보다 친구와 함께 나누는 것이 더 소중하다는 생각을 표현하고 싶다. 내가 좋아하던 물건을 친구와 나누었을 때 더 즐거웠던 경험이 있기 때문이다.","scoring_points":["인물이나 시간·공간을 무엇으로 바꿀지 썼는가","표현하고 싶은 생각을 썼는가","바꾸려는 내용과 이어지는 자신의 경험을 썼는가"]},"explanation":["익숙한 시간과 공간을 고르면 쓰기 쉬워요.","이야기로 전하고 싶은 생각을 정해요.","비슷한 경험을 떠올리면 이야기가 생생해져요."],"asset":{"type":"speech","turns":[{"who":"물음 1","text":"이야기의 인물을 어떤 인물로 바꾸고 싶나요?"},{"who":"물음 2","text":"자신이 이야기로 표현하고 싶은 생각은 무엇인가요? 그 까닭은 무엇인가요?"},{"who":"물음 3","text":"자신에게 익숙하거나 자신이 잘 표현할 수 있는 시간과 공간이 있나요?"},{"who":"물음 4","text":"이야기와 비슷한 사건을 경험해 보거나 들어 본 적이 있나요?"},{"who":"물음 5","text":"상상한 이야기의 처음, 가운데, 끝이 자연스럽게 이어지나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#9','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C39',4,'essay','teacher','두 글의 알라딘이 어떤 성격인지, 그 성격이 어떤 선택으로 드러났는지 비교해 쓰세요. 그리고 작가가 글 ㉯를 왜 이렇게 바꾸었을지 자신의 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C39","difficulty":4,"kind":"essay","stem":"두 글의 알라딘이 어떤 성격인지, 그 성격이 어떤 선택으로 드러났는지 비교해 쓰세요. 그리고 작가가 글 ㉯를 왜 이렇게 바꾸었을지 자신의 생각을 쓰세요.","answer_guide":{"answer":"예: 글 ㉮의 알라딘은 지혜롭지만 욕심이 많아 부자가 되게 해 달라고 빌었다. 글 ㉯의 알라딘은 이타적이고 욕심이 없어 보물과 왕자 비 자리를 거절하고 전쟁을 없애 달라고 빌었다. 작가는 보물이나 권력보다 모두가 평화롭게 사는 것이 더 쓸모 있다는 생각을 전하려고 이렇게 바꾼 것 같다.","scoring_points":["두 알라딘의 성격을 바르게 썼는가","성격을 인물의 선택(소원)과 이었는가","작가가 바꾼 까닭을 이야기 안의 근거로 짐작했는가"]},"explanation":["성격은 인물의 말과 선택에서 드러나요.","두 글은 소원을 청하는 장면에서 크게 갈라져요.","「작가는 왜 이렇게 바꾸었을까?」 하고 생각해 보아요."],"asset":{"type":"passage","lines":["글 ㉮ ① 반지 요정의 도움으로 램프를 가지고 집으로 돌아옴.","② 지니가 나타나 소원을 들어주겠다고 말함.","③ 배가 고프다고 하자 지니가 음식을 차려 줌.","④ 부자가 되고 싶다는 소원을 빌고, 보석과 보물을 얻음.","글 ㉯ ① 지니의 도움으로 융단을 타고 집으로 돌아옴.","② 지니가 부와 권력을 얻게 해 주겠다고 권함.","③ 그런 소원은 빌고 싶지 않다고 말함.","④ 전쟁을 없애고 무기를 사라지게 해 달라고 빌고, 이루어짐."],"numbered":false,"title":"요술 램프를 가지게 된 뒤 사건 전개 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L07_challenge#10','kor',6,2,'u6','L07','tb_g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C23',4,'essay','teacher','글 ㉯ 뒤에 이어질 내용을 상상해 사건 두 가지를 쓰세요. 앞의 사건이 원인이 되어 뒤의 사건이 일어나도록 쓰고, 그렇게 이어 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C23","difficulty":4,"kind":"essay","stem":"글 ㉯ 뒤에 이어질 내용을 상상해 사건 두 가지를 쓰세요. 앞의 사건이 원인이 되어 뒤의 사건이 일어나도록 쓰고, 그렇게 이어 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 지니 덕분에 세상에서 무기가 사라져 전쟁이 멈추었다. 사람들이 다시 농사를 짓게 되자, 알라딘은 두 번째 소원으로 지구의 기후 위기를 해결해 달라고 말했다. 무기가 사라진 다음에는 사람들이 함께 살아갈 땅을 지키는 일이 필요하다고 생각했기 때문이다.","scoring_points":["글 ㉯의 끝과 이어지는 사건을 썼는가","앞 사건이 뒤 사건의 원인이 되게 이었는가","알라딘의 성격(이타적·욕심 없음)을 지켰는가"]},"explanation":["이어질 내용은 앞 이야기와 자연스럽게 이어져야 해요.","원인과 결과로 사건을 이어요.","앞에서 드러난 인물의 성격을 그대로 살려요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#1','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C40',1,'blank','auto','『국어』 289쪽 (1)처럼 옹고집의 성격을 써 보아요. 「옹고집은 (    ) 사람이다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X33']::text[],false,'{"seq":1,"concept":"K6-2-u6-C40","difficulty":1,"kind":"blank","stem":"『국어』 289쪽 (1)처럼 옹고집의 성격을 써 보아요. 「옹고집은 (    ) 사람이다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"심술궂은","correct":true},{"t":"배려심 많은","mis":"K6-2-u6-X33"},{"t":"겁이 많은","mis":"K6-2-u6-X33"},{"t":"부지런한","mis":"K6-2-u6-X33"}],"explanation":["옹고집은 남 잘되는 꼴을 못 보았어요.","자신에게 아무런 해도 끼치지 않은 걸인을 몽둥이질해 내쫓았어요.","이런 행동에서 심술궂은 성격이 드러나요."],"asset":{"type":"passage","lines":["(간추림) 옹진골의 옹고집은 고집이 아주 세고 심술궂은 큰 부자였다.","(간추림) 병든 어머니를 돌보지 않았고, 가족과 일꾼에게도 심술궂게 굴었다.","“흥! 내가 그리해 달라고 부탁한 것도 아니잖소?”","(간추림) 동냥을 온 늙은 걸인을 몽둥이질해 내쫓았다.","(간추림) 걸인은 도를 닦은 도사였고, 짚 인형으로 가짜 옹고집을 만들었다."],"numbered":false,"title":"「옹고집전」 앞부분 간추림 — 『국어』 282~283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#2','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C41',1,'mc','auto','『국어』 288쪽에서 「다른 사람에게 말씀드려서 알리다.」라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K6-2-u6-X49']::text[],false,'{"seq":2,"concept":"K6-2-u6-C41","difficulty":1,"kind":"mc","stem":"『국어』 288쪽에서 「다른 사람에게 말씀드려서 알리다.」라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"아뢰다","correct":true},{"t":"탄식하다","mis":"K6-2-u6-X49"},{"t":"괴이쩍다","mis":"K6-2-u6-X49"},{"t":"극진하다","mis":"K6-2-u6-X49"}],"explanation":["하인들이 안채로 뛰어가 부인에게 아뢰었어요.","아뢰다는 윗사람에게 말씀드려 알리는 말이에요.","낱말의 앞뒤 문맥을 보면 뜻을 짐작할 수 있어요."],"asset":{"type":"passage","lines":["보기: 탄식하다 · 아뢰다 · 괴이쩍다 · 극진하다","● 어떤 대상에게 정성을 다하는 태도가 있다.","● 별나고 괴상한 느낌이 있다.","● 다른 사람에게 말씀드려서 알리다.","● 한탄하여 한숨을 쉬다."],"numbered":false,"title":"낱말 알기 — 『국어』 288쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#3','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C41',1,'sa','auto','『국어』 288쪽 보기에서 「한탄하여 한숨을 쉬다.」라는 뜻을 가진 낱말을 찾아 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C41","difficulty":1,"kind":"sa","stem":"『국어』 288쪽 보기에서 「한탄하여 한숨을 쉬다.」라는 뜻을 가진 낱말을 찾아 쓰세요.","answer":["탄식하다"],"explanation":["냉방에 홀로 누운 어머니가 서럽게 울며 탄식했어요.","한탄하여 한숨을 쉬는 것이 탄식하다예요.","보기의 네 낱말과 뜻을 하나씩 이어 보아요."],"asset":{"type":"passage","lines":["보기: 탄식하다 · 아뢰다 · 괴이쩍다 · 극진하다","● 어떤 대상에게 정성을 다하는 태도가 있다.","● 별나고 괴상한 느낌이 있다.","● 다른 사람에게 말씀드려서 알리다.","● 한탄하여 한숨을 쉬다."],"numbered":false,"title":"낱말 알기 — 『국어』 288쪽"},"mis":"K6-2-u6-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#4','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C40',1,'ox','auto','「옹고집전」에서 가짜 옹고집을 짚으로 만든 사람은 도사예요.',ARRAY['K6-2-u6-X50']::text[],false,'{"seq":4,"concept":"K6-2-u6-C40","difficulty":1,"kind":"ox","stem":"「옹고집전」에서 가짜 옹고집을 짚으로 만든 사람은 도사예요.","answer":"O","reason_options":[{"t":"걸인으로 변장했던 도사가 짚 인형에 주문을 외웠기 때문에","correct":true},{"t":"사또가 재판을 하려고 만들었기 때문에","mis":"K6-2-u6-X50"}],"mis":"K6-2-u6-X50","explanation":["걸인은 사실 도를 닦은 도사였어요.","도사는 짚 한 단으로 인형을 만들어 주문을 외웠어요.","그러자 인형이 옹고집과 똑같은 사람으로 변했어요."],"asset":{"type":"passage","lines":["(간추림) 옹진골의 옹고집은 고집이 아주 세고 심술궂은 큰 부자였다.","(간추림) 병든 어머니를 돌보지 않았고, 가족과 일꾼에게도 심술궂게 굴었다.","“흥! 내가 그리해 달라고 부탁한 것도 아니잖소?”","(간추림) 동냥을 온 늙은 걸인을 몽둥이질해 내쫓았다.","(간추림) 걸인은 도를 닦은 도사였고, 짚 인형으로 가짜 옹고집을 만들었다."],"numbered":false,"title":"「옹고집전」 앞부분 간추림 — 『국어』 282~283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#5','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C41',2,'match','auto','『국어』 288쪽 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C41","difficulty":2,"kind":"match","stem":"『국어』 288쪽 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"극진하다","r":"어떤 대상에게 정성을 다하는 태도가 있다"},{"l":"괴이쩍다","r":"별나고 괴상한 느낌이 있다"},{"l":"아뢰다","r":"다른 사람에게 말씀드려서 알리다"},{"l":"탄식하다","r":"한탄하여 한숨을 쉬다"}],"mis":"K6-2-u6-X49","explanation":["뜻풀이를 문장에 넣어 읽어 보아요.","사또는 똑같은 두 옹고집을 괴이쩍게 여겼어요.","뉘우친 옹고집은 가족에게 극진히 대했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#6','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C40',2,'mc','auto','『국어』 289쪽 인물 관계에서 ㉡에 들어갈 인물은 누구인가요?',ARRAY['K6-2-u6-X50']::text[],false,'{"seq":6,"concept":"K6-2-u6-C40","difficulty":2,"kind":"mc","stem":"『국어』 289쪽 인물 관계에서 ㉡에 들어갈 인물은 누구인가요?","options":[{"t":"가짜 옹고집","correct":true},{"t":"옹고집의 부인","mis":"K6-2-u6-X50"},{"t":"사또","mis":"K6-2-u6-X50"},{"t":"도사","mis":"K6-2-u6-X50"}],"explanation":["진짜 옹고집과 ㉡은 싸움으로 이어져 있어요.","마당에서 서로 「내가 옹가다!」 하며 삿대질을 했어요.","진짜와 싸운 인물은 가짜 옹고집이에요."],"asset":{"type":"passage","lines":["● 진짜 옹고집 — 옹고집의 어머니: 부모 자식","● 진짜 옹고집 — (  ㉠  ): 부부","● 진짜 옹고집 — (  ㉡  ): 싸움","● (  ㉢  ) → 가짜 옹고집: 짚으로 만듦","● 진짜 옹고집과 가짜 옹고집 — 사또: 재판"],"numbered":false,"title":"「옹고집전」 인물 관계 — 『국어』 289쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#7','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',2,'mc','auto','「옹고집전」의 흐름에서 절정에 해당하는 일은 무엇인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":7,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「옹고집전」의 흐름에서 절정에 해당하는 일은 무엇인가요?","options":[{"t":"진짜와 가짜가 싸우고, 사또가 진짜를 가짜라고 판결했다","correct":true},{"t":"옛날에 고집 세고 심술궂은 옹고집이 살았다","mis":"K6-2-u6-X34"},{"t":"옹고집이 걸인을 몽둥이질해 쫓아냈다","mis":"K6-2-u6-X34"},{"t":"옹고집이 뉘우치고 돌아와 착하게 살았다","mis":"K6-2-u6-X34"}],"explanation":["발단은 인물과 배경을 소개해요.","전개에서 사건이 시작되고, 절정에서 갈등이 가장 커져요.","진짜 옹고집이 쫓겨나는 재판 장면이 절정이에요."],"asset":{"type":"passage","lines":["발단 — 옛날에 고집 세고 심술궂은 옹고집이 살았다.","전개 — 걸인을 몽둥이질해 쫓아냈고, 도사는 짚으로 가짜 옹고집을 만들었다.","절정 — 진짜와 가짜가 싸웠고, 사또가 진짜를 가짜라고 판결해 쫓겨났다.","결말 — 떠돌며 고생한 진짜 옹고집은 뉘우치고 돌아와 착하게 살았다."],"numbered":false,"title":"「옹고집전」 사건의 흐름 — 『국어』 289쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#8','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',2,'mc','auto','「옹고집전」의 배경을 바꾸려고 해요. 배경을 두 가지로 나누면 무엇과 무엇인가요?',ARRAY['K6-2-u6-X05','K6-2-u6-X46']::text[],false,'{"seq":8,"concept":"K6-2-u6-C28","difficulty":2,"kind":"mc","stem":"「옹고집전」의 배경을 바꾸려고 해요. 배경을 두 가지로 나누면 무엇과 무엇인가요?","options":[{"t":"공간적 배경과 시간적 배경","correct":true},{"t":"이야기의 인물과 사건","mis":"K6-2-u6-X05"},{"t":"주장과 그 근거","mis":"K6-2-u6-X46"},{"t":"이야기의 처음과 끝","mis":"K6-2-u6-X05"}],"explanation":["배경은 일이 일어난 곳과 때예요.","곳은 공간적 배경, 때는 시간적 배경이에요.","배경을 바꾸면 인물의 행동이나 사건이 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#9','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C29',2,'ox','auto','바꾸어 쓴 이야기의 제목은 나중에 붙여도 되고, 맨 처음에 붙여도 돼요.',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":9,"concept":"K6-2-u6-C29","difficulty":2,"kind":"ox","stem":"바꾸어 쓴 이야기의 제목은 나중에 붙여도 되고, 맨 처음에 붙여도 돼요.","answer":"O","reason_options":[{"t":"바꾼 인물의 성격, 배경, 사건 전개 과정을 생각해 어울리는 제목을 정하면 되기 때문에","correct":true},{"t":"제목은 반드시 쓰기 전에 맨 처음 정해야 하기 때문에","mis":"K6-2-u6-X18"}],"mis":"K6-2-u6-X18","explanation":["『국어』 291쪽 글쓰기에서 알려 준 내용이에요.","제목은 새로 바꾼 인물, 배경, 사건을 생각해 정해요.","나중에 붙여도 되고 처음에 붙여도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_basic#10','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C30',3,'mc','auto','바꾸어 쓴 이야기를 돌려 읽고 칭찬 쪽지를 쓸 때 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X42']::text[],false,'{"seq":10,"concept":"K6-2-u6-C30","difficulty":3,"kind":"mc","stem":"바꾸어 쓴 이야기를 돌려 읽고 칭찬 쪽지를 쓸 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"인물의 말과 행동이 실감 나게 표현되었어.","correct":true},{"t":"잘 썼다. 정말 재미있다.","mis":"K6-2-u6-X25"},{"t":"맞춤법이 틀린 곳이 세 군데 있어.","mis":"K6-2-u6-X42"},{"t":"글씨가 반듯하고 깨끗해.","mis":"K6-2-u6-X25"}],"explanation":["칭찬 쪽지는 어느 부분이 왜 좋은지 구체적으로 써요.","「……한 점이 재미있다.」처럼 쓰면 좋아요.","고칠 점부터 쓰는 것은 칭찬 쪽지가 아니에요."],"asset":{"type":"passage","lines":["[칭찬 쪽지] 박○○ — 인물의 성격을 반대로 바꾸니까 재미있었어.","[칭찬 쪽지] 이○○ — 예상하지 못한 결말이라서 놀랐어.","[칭찬 쪽지] 신○○ — 인물의 말과 행동이 실감 나게 표현되었어."],"numbered":false,"title":"칭찬 쪽지 예시 — 『국어』 291쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#1','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C41',2,'mc','auto','「옹고집전」에 나온 낱말 「개과천선」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X49']::text[],false,'{"seq":1,"concept":"K6-2-u6-C41","difficulty":2,"kind":"mc","stem":"「옹고집전」에 나온 낱말 「개과천선」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"지난날의 잘못이나 허물을 고쳐 올바르고 착하게 됨","correct":true},{"t":"여러 산이 겹치고 겹친 산속","mis":"K6-2-u6-X49"},{"t":"심한 모욕. 또는 참기 힘든 일","mis":"K6-2-u6-X49"},{"t":"거지가 돌아다니며 돈이나 물건을 거저 달라고 비는 일","mis":"K6-2-u6-X49"}],"explanation":["도사는 뉘우치는 옹고집에게 돌아가 개과천선하라고 했어요.","개과천선은 잘못을 고쳐 착하게 되는 것이에요.","첩첩산중·곤욕·동냥의 뜻과 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#2','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C40',2,'mc','auto','「옹고집전」에서 두견새 울음소리를 들은 진짜 옹고집은 무엇을 깨달았나요?',ARRAY['K6-2-u6-X33','K6-2-u6-X07']::text[],false,'{"seq":2,"concept":"K6-2-u6-C40","difficulty":2,"kind":"mc","stem":"「옹고집전」에서 두견새 울음소리를 들은 진짜 옹고집은 무엇을 깨달았나요?","options":[{"t":"가족이 그리워지며 불효하고 못난 자신을 부끄러워했다","correct":true},{"t":"잃어버린 재산을 되찾을 방법을 깨달았다","mis":"K6-2-u6-X33"},{"t":"도사에게 갚아 줄 방법을 떠올렸다","mis":"K6-2-u6-X33"},{"t":"사또에게 다시 재판을 해 달라고 하기로 했다","mis":"K6-2-u6-X07"}],"explanation":["옹고집은 떠돌아다니며 고생했어요.","두견새 울음을 듣고 진짜 잃어버린 것이 가족임을 깨달았어요.","이 깨달음에서 옹고집이 달라지기 시작해요."],"asset":{"type":"passage","lines":["(간추림) 몇 해 뒤 깊은 산속에서 두견새 울음을 듣고 잃어버린 것을 깨달았다.","“부끄럽구나. 나는 불효막심한 자식에, 못난 남편, 못난 아비였다.”","(간추림) 도사 앞에 엎드려 뉘우치자 도사는 돌아가 개과천선하라고 했다.","(간추림) 집에 돌아오니 가짜가 있던 방에는 지푸라기 인형 하나뿐이었다.","(간추림) 그 뒤 옹고집은 효도하고 가족에게 극진히 대하며 착한 일을 했다."],"numbered":false,"title":"「옹고집전」 뒷부분 간추림 — 『국어』 286~287쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#3','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C26',3,'mc','auto','『국어』 290쪽 예시처럼 옹고집을 착한 성격으로 바꾸어 쓰자 원래 이야기와 어떤 점이 달라졌나요?',ARRAY['K6-2-u6-X32','K6-2-u6-X27']::text[],false,'{"seq":3,"concept":"K6-2-u6-C26","difficulty":3,"kind":"mc","stem":"『국어』 290쪽 예시처럼 옹고집을 착한 성격으로 바꾸어 쓰자 원래 이야기와 어떤 점이 달라졌나요?","options":[{"t":"분신술이 벌이 아니라 남을 더 많이 돕는 일로 쓰여 새로운 뜻이 생겼다","correct":true},{"t":"인물의 이름만 바뀌었을 뿐 뜻은 원래와 똑같다","mis":"K6-2-u6-X32"},{"t":"글을 길게 늘인 것이 원래와 가장 달라진 점이다","mis":"K6-2-u6-X32"},{"t":"착한 옹고집도 여전히 걸인을 몽둥이질해 쫓아낸다","mis":"K6-2-u6-X27"}],"explanation":["원래 이야기에서 가짜 옹고집은 심술궂은 옹고집을 벌하는 일이었어요.","바꾼 이야기에서는 도사가 착한 옹고집에게 분신술을 알려 주어요.","바꾸어 쓰면 원래 없던 새로운 뜻이 생겨요."],"asset":{"type":"passage","lines":["(1) 나는 주인공을 착한 성격으로 바꾸고 싶어.","(2) [보기] 옛날 어느 마을에 마음 착한 옹고집이 살았다.","옹고집은 큰 회사 사장이었다.","옹고집과 똑같이 생긴 사람이 나타나 자신이 진짜라고 주장했다.","(2) [예시] 다른 사람을 항상 배려하고 돕는 옹고집이 살았다.","옹고집은 남을 돕느라 몸이 열 개라도 부족할 정도로 바빴다.","도사가 나타나 옹고집에게 분신술을 알려 주었다.","옹고집은 몸을 둘로 나누어 다른 사람을 더 많이 돕고 살았다."],"numbered":false,"title":"「옹고집전」을 바꿀 계획 — 『국어』 290쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#4','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',3,'error','auto','「옹고집전」을 바꿀 계획을 세우며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X28','K6-2-u6-X35']::text[],false,'{"seq":4,"concept":"K6-2-u6-C28","difficulty":3,"kind":"error","stem":"「옹고집전」을 바꿀 계획을 세우며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「성격은 착하게 바꾸고, 걸인을 몽둥이질해 쫓아내는 장면은 그대로 둘래.」","correct":true,"mis_target":"K6-2-u6-X27"},{"t":"친구 1 — 「시간적 배경을 현대로 바꾸면 옹고집을 큰 회사 사장으로 바꿀 수 있어.」","mis":"K6-2-u6-X28"},{"t":"친구 2 — 「인물을 바꿀 때 새로운 인물을 넣거나 서술자를 바꿀 수도 있어.」","mis":"K6-2-u6-X35"}],"explanation":["성격을 바꾸면 그 인물의 말과 행동도 함께 바꾸어야 해요.","배경이 바뀌면 인물이 할 수 있는 일도 달라져요.","새 인물을 넣거나 서술자를 바꾸는 것도 방법이에요."],"asset":{"type":"passage","lines":["(1) 나는 주인공을 착한 성격으로 바꾸고 싶어.","(2) [보기] 옛날 어느 마을에 마음 착한 옹고집이 살았다.","옹고집은 큰 회사 사장이었다.","옹고집과 똑같이 생긴 사람이 나타나 자신이 진짜라고 주장했다.","(2) [예시] 다른 사람을 항상 배려하고 돕는 옹고집이 살았다.","옹고집은 남을 돕느라 몸이 열 개라도 부족할 정도로 바빴다.","도사가 나타나 옹고집에게 분신술을 알려 주었다.","옹고집은 몸을 둘로 나누어 다른 사람을 더 많이 돕고 살았다."],"numbered":false,"title":"「옹고집전」을 바꿀 계획 — 『국어』 290쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#5','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',3,'mc','auto','「옹고집전」의 시간적 배경을 현대로 바꾸었을 때 함께 손볼 곳으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X36']::text[],false,'{"seq":5,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"「옹고집전」의 시간적 배경을 현대로 바꾸었을 때 함께 손볼 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"인물이 하는 일과 사또의 재판 같은 사건을 현대에 어울리게 바꾼다","correct":true},{"t":"배경만 바꾸고 나머지는 하나도 손보지 않는다","mis":"K6-2-u6-X35"},{"t":"인물·배경·사건을 모두 처음부터 새로 바꾼다","mis":"K6-2-u6-X36"},{"t":"글자 수를 원래 이야기와 똑같이 맞춘다","mis":"K6-2-u6-X35"}],"explanation":["인물, 배경, 사건은 밀접하게 이어져 있어요.","하나가 달라지면 다른 요소도 함께 달라져요.","그 연결이 자연스러워야 이야기가 그럴듯해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#6','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C29',3,'mc','auto','옹고집을 착한 성격으로 바꾼 이야기의 첫 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X37','K6-2-u6-X34']::text[],false,'{"seq":6,"concept":"K6-2-u6-C29","difficulty":3,"kind":"mc","stem":"옹고집을 착한 성격으로 바꾼 이야기의 첫 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"언제나 먼저 양보하고 어려운 사람을 돕는 옹고집이라는 사람이 살았다.","correct":true},{"t":"옛날 옹진골에 고집이 아주 세고 심술궂은 옹고집이 살았다.","mis":"K6-2-u6-X37"},{"t":"옛날 옛적 아주 먼 곳에 이야기 하나가 있었다.","mis":"K6-2-u6-X37"},{"t":"옹고집은 곤장을 맞고 관아에서 쫓겨났다.","mis":"K6-2-u6-X34"}],"explanation":["첫 문장은 무엇이 바뀌었는지 먼저 알려 줘요.","착하게 바뀐 성격이 첫 문장에 드러나면 좋아요.","원래 이야기 그대로 시작하면 바뀐 점을 알아채기 어려워요."],"asset":{"type":"passage","lines":["[첫 문장] 언제나 먼저 양보하고 어려운 사람을 돕는","옹고집이라는 사람이 살았다.","[제목] 착한 옹고집의 분신술"],"numbered":false,"title":"바꾸어 쓴 이야기 예시 — 『국어』 291쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#7','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C30',3,'ox','auto','칭찬 쪽지에는 ‘잘 썼다.’, ‘재미있다.’처럼 짧게 쓰는 것이 가장 좋아요.',ARRAY['K6-2-u6-X25']::text[],false,'{"seq":7,"concept":"K6-2-u6-C30","difficulty":3,"kind":"ox","stem":"칭찬 쪽지에는 ‘잘 썼다.’, ‘재미있다.’처럼 짧게 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"‘……한 점이 재미있다.’처럼 어느 부분이 왜 좋은지 구체적으로 써야 하기 때문에","correct":true},{"t":"칭찬은 짧을수록 듣기 좋기 때문에","mis":"K6-2-u6-X25"}],"mis":"K6-2-u6-X25","explanation":["구체적인 칭찬은 친구가 무엇을 잘했는지 알려 줘요.","「…… 부분이 인상 깊다.」처럼 써요.","『국어』 291쪽 칭찬 쪽지 예시를 떠올려 보아요."],"asset":{"type":"passage","lines":["[칭찬 쪽지] 박○○ — 인물의 성격을 반대로 바꾸니까 재미있었어.","[칭찬 쪽지] 이○○ — 예상하지 못한 결말이라서 놀랐어.","[칭찬 쪽지] 신○○ — 인물의 말과 행동이 실감 나게 표현되었어."],"numbered":false,"title":"칭찬 쪽지 예시 — 『국어』 291쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#8','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',4,'essay','teacher','「옹고집전」을 바꿀 계획을 세우세요. 무엇(인물의 성격 또는 배경)을 어떻게 바꿀지 쓰고, 그에 따라 달라질 사건을 차례대로 세 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C28","difficulty":4,"kind":"essay","stem":"「옹고집전」을 바꿀 계획을 세우세요. 무엇(인물의 성격 또는 배경)을 어떻게 바꿀지 쓰고, 그에 따라 달라질 사건을 차례대로 세 가지 쓰세요.","answer_guide":{"answer":"예: 시간적 배경을 현대로 바꾸겠다. 옹고집은 큰 회사 사장이지만 직원들에게 심술궂게 군다. 어느 날 옹고집과 똑같이 생긴 사람이 나타나 자신이 진짜 옹고집이라고 주장한다. 회사에서 쫓겨난 옹고집은 여기저기 떠돌다 직원들의 마음을 알게 되고, 뉘우친 뒤 직원들을 아끼는 사장이 된다.","scoring_points":["바꿀 요소와 바꿀 내용을 썼는가","바뀐 요소에 따라 사건이 달라지게 썼는가","사건 세 가지가 원인과 결과로 자연스럽게 이어지는가"]},"explanation":["인물이나 배경 가운데에서 바꿀 것을 골라요.","바뀐 것에 따라 사건이 어떻게 달라질지 생각해요.","사건을 시간 순서와 원인과 결과에 맞게 정리해요."],"asset":{"type":"passage","lines":["(1) 나는 주인공을 착한 성격으로 바꾸고 싶어.","(2) [보기] 옛날 어느 마을에 마음 착한 옹고집이 살았다.","옹고집은 큰 회사 사장이었다.","옹고집과 똑같이 생긴 사람이 나타나 자신이 진짜라고 주장했다.","(2) [예시] 다른 사람을 항상 배려하고 돕는 옹고집이 살았다.","옹고집은 남을 돕느라 몸이 열 개라도 부족할 정도로 바빴다.","도사가 나타나 옹고집에게 분신술을 알려 주었다.","옹고집은 몸을 둘로 나누어 다른 사람을 더 많이 돕고 살았다."],"numbered":false,"title":"「옹고집전」을 바꿀 계획 — 『국어』 290쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#9','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C40',4,'essay','teacher','『국어』 288쪽 예처럼 「옹고집은 (    ) 사람이다. 왜냐하면 ……」의 꼴로 옹고집의 성격을 쓰세요. 그리고 결말에서 옹고집이 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C40","difficulty":4,"kind":"essay","stem":"『국어』 288쪽 예처럼 「옹고집은 (    ) 사람이다. 왜냐하면 ……」의 꼴로 옹고집의 성격을 쓰세요. 그리고 결말에서 옹고집이 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 옹고집은 심술궂은 사람이다. 왜냐하면 자신에게 아무런 해도 끼치지 않은 걸인을 몽둥이질해서 내쫓았기 때문이다. 결말에서 옹고집은 잘못을 뉘우치고 어머니께 효도하며 다른 사람을 위하는 일에 앞장서는 사람이 되었다.","scoring_points":["성격을 알맞은 낱말로 썼는가","그 성격이 드러난 행동을 근거로 들었는가","결말에서 달라진 모습을 썼는가"]},"explanation":["인물의 성격은 그 인물이 한 말과 행동에서 찾아요.","「왜냐하면」 뒤에 그 행동을 써요.","결말에서 옹고집은 뉘우치고 착하게 살았어요."],"asset":{"type":"passage","lines":["(간추림) 옹진골의 옹고집은 고집이 아주 세고 심술궂은 큰 부자였다.","(간추림) 병든 어머니를 돌보지 않았고, 가족과 일꾼에게도 심술궂게 굴었다.","“흥! 내가 그리해 달라고 부탁한 것도 아니잖소?”","(간추림) 동냥을 온 늙은 걸인을 몽둥이질해 내쫓았다.","(간추림) 걸인은 도를 닦은 도사였고, 짚 인형으로 가짜 옹고집을 만들었다."],"numbered":false,"title":"「옹고집전」 앞부분 간추림 — 『국어』 282~283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L09_challenge#10','kor',6,2,'u6','L09','tb_g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C30',4,'essay','teacher','『국어』 290쪽 예시로 바꾸어 쓴 「착한 옹고집의 분신술」을 친구가 쓴 이야기라고 생각하고, 칭찬 쪽지를 써 보세요. 어느 부분이 왜 좋은지 구체적으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C30","difficulty":4,"kind":"essay","stem":"『국어』 290쪽 예시로 바꾸어 쓴 「착한 옹고집의 분신술」을 친구가 쓴 이야기라고 생각하고, 칭찬 쪽지를 써 보세요. 어느 부분이 왜 좋은지 구체적으로 쓰세요.","answer_guide":{"answer":"예: 도사가 착한 옹고집에게 분신술을 알려 주는 부분이 재미있었어. 원래 이야기에서는 가짜 옹고집이 벌이었는데, 바꾼 이야기에서는 분신술이 남을 더 많이 돕는 일로 쓰여서 새롭게 느껴졌어.","scoring_points":["칭찬할 부분을 구체적으로 짚었는가","그 부분이 좋은 까닭을 썼는가","막연한 말이 아니라 「……한 점이 ……하다」처럼 썼는가"]},"explanation":["칭찬 쪽지는 구체적으로 써요.","어느 부분인지 밝히고 왜 좋은지 써요.","원래 이야기와 달라진 점을 짚으면 더 좋아요."],"asset":{"type":"passage","lines":["(1) 나는 주인공을 착한 성격으로 바꾸고 싶어.","(2) [보기] 옛날 어느 마을에 마음 착한 옹고집이 살았다.","옹고집은 큰 회사 사장이었다.","옹고집과 똑같이 생긴 사람이 나타나 자신이 진짜라고 주장했다.","(2) [예시] 다른 사람을 항상 배려하고 돕는 옹고집이 살았다.","옹고집은 남을 돕느라 몸이 열 개라도 부족할 정도로 바빴다.","도사가 나타나 옹고집에게 분신술을 알려 주었다.","옹고집은 몸을 둘로 나누어 다른 사람을 더 많이 돕고 살았다."],"numbered":false,"title":"「옹고집전」을 바꿀 계획 — 『국어』 290쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#1','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',1,'mc','auto','『국어』 292쪽에서 학급 이야기책의 형태로 예를 든 것은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39','K6-2-u6-X41']::text[],false,'{"seq":1,"concept":"K6-2-u6-C31","difficulty":1,"kind":"mc","stem":"『국어』 292쪽에서 학급 이야기책의 형태로 예를 든 것은 무엇인가요?","options":[{"t":"소리를 녹음해 만든 오디오 북","correct":true},{"t":"가장 비싼 종이로 만든 책","mis":"K6-2-u6-X38"},{"t":"반 친구들은 볼 수 없는 혼자만의 책","mis":"K6-2-u6-X39"},{"t":"표지만 있는 책","mis":"K6-2-u6-X41"}],"explanation":["첫 단계는 학급에서 만들고 싶은 이야기책 형태 정하기예요.","오디오 북이나 프레젠테이션 프로그램으로 만든 책을 예로 들었어요.","종이책, 전자책 같은 형태도 있어요."],"asset":{"type":"passage","lines":["① 학급에서 만들고 싶은 이야기책 형태 정하기","(소리를 녹음한 오디오 북 · 프레젠테이션 프로그램으로 만든 책)","② 쓰고 싶은 이야기의 중심 사건, 등장인물, 배경 정하기","③ 사건의 전개 과정을 간단히 써 보기","④ 매체를 활용해 이야기를 만들고 학급 온라인 게시판에 올리기","⑤ 반 친구들의 이야기를 모아 이야기책으로 만들기"],"numbered":false,"title":"매체를 활용한 학급 이야기책 만들기 — 『국어』 292쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#2','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C32',1,'mc','auto','학급 이야기책에 실을 이야기를 쓰기 전에 정할 것은 무엇인가요?',ARRAY['K6-2-u6-X40','K6-2-u6-X46']::text[],false,'{"seq":2,"concept":"K6-2-u6-C32","difficulty":1,"kind":"mc","stem":"학급 이야기책에 실을 이야기를 쓰기 전에 정할 것은 무엇인가요?","options":[{"t":"이야기의 중심 사건, 등장인물, 배경","correct":true},{"t":"책 표지의 색깔과 글자 수","mis":"K6-2-u6-X40"},{"t":"책의 무게와 모두 몇 쪽인지","mis":"K6-2-u6-X40"},{"t":"이야기로 내세울 주장과 근거","mis":"K6-2-u6-X46"}],"explanation":["『국어』 292쪽 둘째 단계예요.","등장인물의 이름과 성격, 일이 일어난 시간과 공간을 정해요.","그리고 중심 사건을 정해요."],"asset":{"type":"passage","lines":["① 학급에서 만들고 싶은 이야기책 형태 정하기","(소리를 녹음한 오디오 북 · 프레젠테이션 프로그램으로 만든 책)","② 쓰고 싶은 이야기의 중심 사건, 등장인물, 배경 정하기","③ 사건의 전개 과정을 간단히 써 보기","④ 매체를 활용해 이야기를 만들고 학급 온라인 게시판에 올리기","⑤ 반 친구들의 이야기를 모아 이야기책으로 만들기"],"numbered":false,"title":"매체를 활용한 학급 이야기책 만들기 — 『국어』 292쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#3','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',1,'sa','auto','「약속 시간에 늦을까 봐 얼마나 마음을 조렸는지 몰라.」에서 ‘조렸는지’를 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C34","difficulty":1,"kind":"sa","stem":"「약속 시간에 늦을까 봐 얼마나 마음을 조렸는지 몰라.」에서 ‘조렸는지’를 바르게 고쳐 쓰세요.","answer":["졸였는지"],"explanation":["‘조리다’는 양념이 배어들게 끓이는 것이에요.","‘졸이다’에는 속을 태우다시피 초조해한다는 뜻이 있어요.","마음을 졸였다고 써야 해요."],"asset":{"type":"passage","lines":["[문자] 약속 시간에 늦을까 봐 얼마나 마음을 조렸는지 몰라.","[생각] 마음을 조렸다고? 왠지 어색한데.","‘조리다’: 양념을 한 재료를 국물에 넣고 끓여 양념이 배어들게 하다.","‘졸이다’: 국물을 증발시켜 분량을 적어지게 하다.","또는 속을 태우다시피 초조해하다."],"numbered":false,"title":"기초 다지기 — 『국어』 297쪽"},"mis":"K6-2-u6-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#4','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',1,'ox','auto','‘조리다’와 ‘졸이다’처럼 소리는 같지만 뜻이 다른 낱말은 쓰이는 상황에 맞게 골라 써야 해요.',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":4,"concept":"K6-2-u6-C34","difficulty":1,"kind":"ox","stem":"‘조리다’와 ‘졸이다’처럼 소리는 같지만 뜻이 다른 낱말은 쓰이는 상황에 맞게 골라 써야 해요.","answer":"O","reason_options":[{"t":"소리가 같아도 뜻이 달라 잘못 쓰면 문장의 뜻이 바뀌기 때문에","correct":true},{"t":"소리가 같으니 아무것이나 써도 뜻이 통하기 때문에","mis":"K6-2-u6-X43"}],"mis":"K6-2-u6-X43","explanation":["『국어』 297쪽 기초 다지기에서 배운 내용이에요.","소리가 같은 낱말은 뜻이 서로 달라요.","쓰이는 상황에 맞는 낱말을 골라 써요."],"asset":{"type":"passage","lines":["[문자] 약속 시간에 늦을까 봐 얼마나 마음을 조렸는지 몰라.","[생각] 마음을 조렸다고? 왠지 어색한데.","‘조리다’: 양념을 한 재료를 국물에 넣고 끓여 양념이 배어들게 하다.","‘졸이다’: 국물을 증발시켜 분량을 적어지게 하다.","또는 속을 태우다시피 초조해하다."],"numbered":false,"title":"기초 다지기 — 『국어』 297쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#5','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C42',2,'mc','auto','「양말 한 짝」은 어떤 경험을 시로 표현했나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C42","difficulty":2,"kind":"mc","stem":"「양말 한 짝」은 어떤 경험을 시로 표현했나요?","options":[{"t":"양말 한 짝이 사라진 경험","correct":true},{"t":"새 양말을 선물 받은 경험","mis":"K6-2-u6-X07"},{"t":"세탁기를 고친 경험","mis":"K6-2-u6-X07"},{"t":"신발을 잃어버린 경험","mis":"K6-2-u6-X07"}],"explanation":["『국어』 294쪽 1번 (1)의 물음이에요.","세탁기에서 나올 때 양말 한 짝이 사라져요.","양말 한 짝이 사라진 경험을 시로 표현했어요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#6','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',2,'mc','auto','『국어』 297쪽 2번에서 알맞은 낱말을 골라 바르게 쓴 문장은 무엇인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":6,"concept":"K6-2-u6-C34","difficulty":2,"kind":"mc","stem":"『국어』 297쪽 2번에서 알맞은 낱말을 골라 바르게 쓴 문장은 무엇인가요?","options":[{"t":"이 산 너머에 바다가 있어.","correct":true},{"t":"이 산 넘어에 바다가 있어.","mis":"K6-2-u6-X43"},{"t":"놀이터를 걷혀 학교로 갔다.","mis":"K6-2-u6-X43"},{"t":"마음속을 들어내 보여 주고 싶다.","mis":"K6-2-u6-X43"}],"explanation":["소리가 같은 낱말 가운데 문장에 맞는 것을 골라요.","『국어』 297쪽 2번의 예시 답안은 ‘너머’, ‘거쳐’, ‘드러내’예요.","소리가 같아도 뜻이 달라 서로 바꾸어 쓸 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#7','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',2,'mc','auto','학급 이야기책의 형태를 정하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":7,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"학급 이야기책의 형태를 정하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"읽을 독자를 떠올리고, 그 독자에게 가장 잘 전할 형태를 정한다","correct":true},{"t":"가장 새롭고 멋있어 보이는 형태를 먼저 고른다","mis":"K6-2-u6-X38"},{"t":"누가 읽을지는 책을 다 만든 뒤에 생각한다","mis":"K6-2-u6-X39"},{"t":"가장 빨리 끝나는 형태가 언제나 가장 좋다","mis":"K6-2-u6-X38"}],"explanation":["예상 독자는 우리 반 친구들이나 부모님이 될 수 있어요.","독자에게 가장 잘 전할 형태를 생각해요.","형태마다 장단점이 있어 등수를 매길 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#8','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C32',2,'mc','auto','경험을 바탕으로 이야기를 쓰는 것에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X31','K6-2-u6-X48','K6-2-u6-X41']::text[],false,'{"seq":8,"concept":"K6-2-u6-C32","difficulty":2,"kind":"mc","stem":"경험을 바탕으로 이야기를 쓰는 것에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"경험을 인물·배경·사건으로 나누어 바꾸어 보는 것이라 일기나 생활문과는 다르다","correct":true},{"t":"겪은 일을 날짜와 함께 그대로 적는 일기와 같다","mis":"K6-2-u6-X31"},{"t":"직접 겪은 일만 쓸 수 있고 읽은 이야기는 쓸 수 없다","mis":"K6-2-u6-X48"},{"t":"표지 그림을 먼저 그려야 쓸 수 있다","mis":"K6-2-u6-X41"}],"explanation":["경험을 이야기의 요소로 나누어 보아요.","인물, 배경, 사건을 어떻게 바꿀지 생각해요.","그래서 일기나 생활문을 쓰는 것과는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#9','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C33',2,'ox','auto','학급 이야기책을 공유한 뒤에는 잘한 점에 초점을 맞추어 소감을 나눠요.',ARRAY['K6-2-u6-X42']::text[],false,'{"seq":9,"concept":"K6-2-u6-C33","difficulty":2,"kind":"ox","stem":"학급 이야기책을 공유한 뒤에는 잘한 점에 초점을 맞추어 소감을 나눠요.","answer":"O","reason_options":[{"t":"친구들의 이야기를 읽고 칭찬 댓글로 서로의 글을 북돋우기 때문에","correct":true},{"t":"고칠 점부터 말해야 다음에 더 잘 쓰기 때문에","mis":"K6-2-u6-X42"}],"mis":"K6-2-u6-X42","explanation":["완성된 이야기책은 학급 온라인 게시판으로 함께 나눠요.","읽은 소감은 칭찬 댓글로 써요.","잘한 점에 초점을 맞추어 소감을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_basic#10','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C42',3,'mc','auto','「양말 한 짝」에서 경험을 재미있게 표현한 부분으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07','K6-2-u6-X09']::text[],false,'{"seq":10,"concept":"K6-2-u6-C42","difficulty":3,"kind":"mc","stem":"「양말 한 짝」에서 경험을 재미있게 표현한 부분으로 알맞은 것은 무엇인가요?","options":[{"t":"한 짝만 사라져도 두 짝 다 사라진 것과 같다고 표현한 부분","correct":true},{"t":"양말이 정말로 발로 걸어 문밖에 나갔다고 쓴 부분","mis":"K6-2-u6-X08"},{"t":"양말의 색깔과 크기를 자세히 적은 부분","mis":"K6-2-u6-X07"},{"t":"세탁기 쓰는 방법을 차례대로 적은 부분","mis":"K6-2-u6-X09"}],"explanation":["『국어』 294쪽 1번 (2)의 물음이에요.","한 짝만 남으면 신을 수 없으니 두 짝 다 사라진 것과 같아요.","양말이 기회를 틈타 사라진다는 표현도 재미있어요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#1','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C42',2,'mc','auto','「양말 한 짝」에서 세탁기에서 나오는 양말의 모습을 흉내 낸 말은 무엇인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C42","difficulty":2,"kind":"mc","stem":"「양말 한 짝」에서 세탁기에서 나오는 양말의 모습을 흉내 낸 말은 무엇인가요?","options":[{"t":"꼬물꼬물","correct":true},{"t":"데굴데굴","mis":"K6-2-u6-X07"},{"t":"꾸벅 꾸우벅","mis":"K6-2-u6-X07"},{"t":"오물오물","mis":"K6-2-u6-X07"}],"explanation":["양말이 세탁기에서 꼬물꼬물 나온다고 했어요.","이 말 덕분에 양말이 살아 있는 것처럼 느껴져요.","데굴데굴·꾸벅 꾸우벅·오물오물은 다른 시에 나온 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#2','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C33',2,'mc','auto','배운 내용을 실천하는 활동을 하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X42','K6-2-u6-X41']::text[],false,'{"seq":2,"concept":"K6-2-u6-C33","difficulty":2,"kind":"mc","stem":"배운 내용을 실천하는 활동을 하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"하고 싶은 활동 정하기 → 활동하기 → 활동 소감 나누기","correct":true},{"t":"활동 소감 나누기 → 하고 싶은 활동 정하기 → 활동하기","mis":"K6-2-u6-X42"},{"t":"표지 꾸미기 → 활동하기 → 하고 싶은 활동 정하기","mis":"K6-2-u6-X41"}],"explanation":["『국어』 293쪽에 차례가 나와요.","먼저 우리 반이 하고 싶은 활동을 정해요.","반 전체·모둠·짝·혼자 가운데 어떻게 할지도 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#3','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',3,'mc','auto','『국어』 297쪽 2번의 두 문장에서 알맞은 낱말을 바르게 고른 것은 무엇인가요? 「놀이터를 (걷혀, 거쳐) 학교로 갔다.」 「마음속을 (드러내, 들어내) 보여 주고 싶다.」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":3,"concept":"K6-2-u6-C34","difficulty":3,"kind":"mc","stem":"『국어』 297쪽 2번의 두 문장에서 알맞은 낱말을 바르게 고른 것은 무엇인가요? 「놀이터를 (걷혀, 거쳐) 학교로 갔다.」 「마음속을 (드러내, 들어내) 보여 주고 싶다.」","options":[{"t":"거쳐 — 드러내","correct":true},{"t":"걷혀 — 들어내","mis":"K6-2-u6-X43"},{"t":"걷혀 — 드러내","mis":"K6-2-u6-X43"},{"t":"거쳐 — 들어내","mis":"K6-2-u6-X43"}],"explanation":["두 낱말은 소리가 같아도 뜻이 달라요.","『국어』 297쪽 예시 답안은 ‘거쳐’와 ‘드러내’예요.","쓰이는 상황에 맞는 낱말을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#4','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',3,'match','auto','『국어』 297쪽 기초 다지기의 낱말과 그 낱말을 알맞게 쓴 문장을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u6-C34","difficulty":3,"kind":"match","stem":"『국어』 297쪽 기초 다지기의 낱말과 그 낱말을 알맞게 쓴 문장을 이으세요.","pairs":[{"l":"시켰다","r":"할아버지께서 심부름을 시키셨다."},{"l":"식혔다","r":"뜨거운 죽을 식혔다."},{"l":"졸였다","r":"약속에 늦을까 봐 마음을 졸였다."}],"mis":"K6-2-u6-X43","explanation":["3번 예시 답안에서 ‘시켰다’와 ‘식혔다’로 짧은 글을 썼어요.","심부름은 시키고, 뜨거운 죽은 식혀요.","초조한 마음은 ‘졸였다’로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#5','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',3,'error','auto','학급 이야기책의 형태를 정하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":5,"concept":"K6-2-u6-C31","difficulty":3,"kind":"error","stem":"학급 이야기책의 형태를 정하며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「오디오 북이 가장 새로우니까 무조건 제일 좋은 형태야. 다른 형태는 볼 필요 없어.」","correct":true,"mis_target":"K6-2-u6-X38"},{"t":"친구 1 — 「부모님도 읽으실 거니까 누구나 쉽게 볼 수 있는 형태가 좋겠어.」","mis":"K6-2-u6-X39"},{"t":"친구 2 — 「종이책, 오디오 북, 전자책은 저마다 장단점이 있어.」","mis":"K6-2-u6-X38"}],"explanation":["책의 형태에는 등수가 없어요.","형태마다 장단점이 있어요.","독자에게 가장 잘 전할 형태를 함께 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#6','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C32',3,'mc','auto','『국어』 292쪽 셋째 단계 「사건의 전개 과정을 간단히 써 보기」에서 할 일은 무엇인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X40','K6-2-u6-X31']::text[],false,'{"seq":6,"concept":"K6-2-u6-C32","difficulty":3,"kind":"mc","stem":"『국어』 292쪽 셋째 단계 「사건의 전개 과정을 간단히 써 보기」에서 할 일은 무엇인가요?","options":[{"t":"사건을 중심으로 이야기 내용을 간략하게 정리한다","correct":true},{"t":"표지 그림을 먼저 완성한다","mis":"K6-2-u6-X41"},{"t":"글자 수를 정한다","mis":"K6-2-u6-X40"},{"t":"겪은 일을 일기처럼 날짜 순서로 적는다","mis":"K6-2-u6-X31"}],"explanation":["셋째 단계는 개요를 만드는 단계예요.","사건을 중심으로 내용을 간략하게 정리해요.","이 개요를 바탕으로 매체를 활용해 글을 써요."],"asset":{"type":"passage","lines":["① 학급에서 만들고 싶은 이야기책 형태 정하기","(소리를 녹음한 오디오 북 · 프레젠테이션 프로그램으로 만든 책)","② 쓰고 싶은 이야기의 중심 사건, 등장인물, 배경 정하기","③ 사건의 전개 과정을 간단히 써 보기","④ 매체를 활용해 이야기를 만들고 학급 온라인 게시판에 올리기","⑤ 반 친구들의 이야기를 모아 이야기책으로 만들기"],"numbered":false,"title":"매체를 활용한 학급 이야기책 만들기 — 『국어』 292쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#7','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C33',3,'mc','auto','모둠 패러디 책을 만들 때 원본 이야기를 정하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X42','K6-2-u6-X41','K6-2-u6-X26']::text[],false,'{"seq":7,"concept":"K6-2-u6-C33","difficulty":3,"kind":"mc","stem":"모둠 패러디 책을 만들 때 원본 이야기를 정하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"모둠원이 모두 알고 있는 이야기로 정한다","correct":true},{"t":"한 사람만 아는 새로운 이야기로 정한다","mis":"K6-2-u6-X42"},{"t":"표지가 가장 화려한 책으로 정한다","mis":"K6-2-u6-X41"},{"t":"원본을 밝히지 않고 그대로 베껴 쓴다","mis":"K6-2-u6-X26"}],"explanation":["모둠 패러디 책은 하나의 이야기를 여러 개로 바꾸어 쓴 책이에요.","모둠원이 모두 원본을 알아야 각자 바꾸어 쓸 수 있어요.","인물, 배경, 사건 가운데에서 하나를 바꾸어 보아요."],"asset":{"type":"passage","lines":["① 서너 명이 한 모둠이 되어 모둠원이 모두 아는 원본 이야기를 정한다.","② 인물, 배경, 사건 가운데에서 하나를 바꾸면 어떻게 될지 발상을 모은다.","③ 각자 아이디어를 한 개씩 선정한다.","④ 자신이 선택한 이야기를 컴퓨터로 쓰고 출력하거나 저장한다.","⑤ 표지와 평가표를 덧붙이고 작품들을 한 권으로 묶는다.","⑥ 다른 모둠 작품과 돌려 읽고 평가표를 작성한다.","⑦ 평가회를 열고 좋은 점을 중심으로 소감을 나눈다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 모둠 패러디 책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#8','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',4,'essay','teacher','우리 반 이야기책을 어떤 형태로 만들지 정하고, 그 책을 주로 읽을 독자와 그 형태를 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C31","difficulty":4,"kind":"essay","stem":"우리 반 이야기책을 어떤 형태로 만들지 정하고, 그 책을 주로 읽을 독자와 그 형태를 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 오디오 북으로 만들고 싶다. 이 책은 동생들과 부모님이 들을 것이다. 소리로 들으면 글을 읽기 어려운 동생들도 인물의 목소리를 실감 나게 들을 수 있고, 부모님도 일하시면서 들으실 수 있기 때문이다.","scoring_points":["책의 형태를 정했는가","예상 독자를 썼는가","독자에게 잘 전할 수 있다는 까닭을 썼는가"]},"explanation":["먼저 이야기책을 읽을 독자를 떠올려요.","종이책·오디오 북·전자책의 장단점을 생각해요.","독자에게 가장 잘 전할 형태를 골라요."],"asset":{"type":"passage","lines":["① 학급에서 만들고 싶은 이야기책 형태 정하기","(소리를 녹음한 오디오 북 · 프레젠테이션 프로그램으로 만든 책)","② 쓰고 싶은 이야기의 중심 사건, 등장인물, 배경 정하기","③ 사건의 전개 과정을 간단히 써 보기","④ 매체를 활용해 이야기를 만들고 학급 온라인 게시판에 올리기","⑤ 반 친구들의 이야기를 모아 이야기책으로 만들기"],"numbered":false,"title":"매체를 활용한 학급 이야기책 만들기 — 『국어』 292쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#9','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C42',4,'essay','teacher','「양말 한 짝」은 어떤 경험을 시로 표현했는지 쓰고, 경험을 재미있게 표현한 부분을 두 가지 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C42","difficulty":4,"kind":"essay","stem":"「양말 한 짝」은 어떤 경험을 시로 표현했는지 쓰고, 경험을 재미있게 표현한 부분을 두 가지 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 「양말 한 짝」은 양말 한 짝이 사라진 경험을 시로 표현했다. 세탁기에서 「꼬물꼬물」 나온다고 한 부분이 재미있다. 양말이 살아 있는 것처럼 느껴지기 때문이다. 또 한 짝만 사라져도 두 짝 다 사라진 거라고 한 부분이 인상 깊다. 한 짝만 남으면 신을 수 없는 마음을 재치 있게 나타냈기 때문이다.","scoring_points":["시에 담긴 경험을 바르게 썼는가","재미있는 부분을 두 가지 골랐는가","부분마다 까닭을 썼는가"]},"explanation":["시에 담긴 경험은 시 안의 말에서 찾아요.","흉내 내는 말과 빗댄 표현이 재미를 줘요.","왜 재미있는지 까닭을 함께 써요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_L12_challenge#10','kor',6,2,'u6','L12','tb_g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',4,'essay','teacher','『국어』 297쪽 3번처럼 ‘시켰다’와 ‘식혔다’를 활용해 짧은 글을 각각 한 문장씩 쓰세요. 그리고 두 낱말을 잘못 바꾸어 쓰면 어떤 문제가 생기는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C34","difficulty":4,"kind":"essay","stem":"『국어』 297쪽 3번처럼 ‘시켰다’와 ‘식혔다’를 활용해 짧은 글을 각각 한 문장씩 쓰세요. 그리고 두 낱말을 잘못 바꾸어 쓰면 어떤 문제가 생기는지 쓰세요.","answer_guide":{"answer":"예: 엄마께서 동생에게 방 청소를 시켰다. 나는 뜨거운 국을 후후 불어 식혔다. 두 낱말은 소리가 같지만 뜻이 달라서 잘못 바꾸어 쓰면 읽는 사람이 엉뚱한 뜻으로 알아듣게 된다.","scoring_points":["‘시켰다’를 뜻에 맞게 썼는가","‘식혔다’를 뜻에 맞게 썼는가","바꾸어 쓰면 뜻이 달라진다는 점을 썼는가"]},"explanation":["소리는 같아도 뜻이 다른 낱말이 있어요.","심부름은 ‘시키다’, 뜨거운 것은 ‘식히다’예요.","쓰이는 상황에 맞게 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#1','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C1',1,'mc','auto','경험을 시나 이야기로 표현하면 좋은 점으로 『국어』 257쪽에서 친구가 말한 것은 무엇인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X02','K6-2-u6-X04']::text[],false,'{"seq":1,"concept":"K6-2-u6-C1","difficulty":1,"kind":"mc","stem":"경험을 시나 이야기로 표현하면 좋은 점으로 『국어』 257쪽에서 친구가 말한 것은 무엇인가요?","options":[{"t":"오랫동안 생생하게 기억할 수 있다","correct":true},{"t":"글씨를 예쁘게 쓰게 된다","mis":"K6-2-u6-X01"},{"t":"대단한 일만 골라 쓸 수 있다","mis":"K6-2-u6-X02"},{"t":"어려운 말을 많이 배울 수 있다","mis":"K6-2-u6-X04"}],"explanation":["경험을 재미있게 표현할 수 있어요.","오랫동안 생생하게 기억할 수 있어요.","느낀 마음을 다른 사람에게 잘 전할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#2','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C36',1,'mc','auto','「그때부터였나 봐」에서 축구공을 차며 골대로 뛰어간 친구는 누구인가요?',ARRAY['K6-2-u6-X50']::text[],false,'{"seq":2,"concept":"K6-2-u6-C36","difficulty":1,"kind":"mc","stem":"「그때부터였나 봐」에서 축구공을 차며 골대로 뛰어간 친구는 누구인가요?","options":[{"t":"수빈","correct":true},{"t":"연우","mis":"K6-2-u6-X50"},{"t":"선생님","mis":"K6-2-u6-X50"}],"explanation":["첫 연에 「수빈이를 본 뒤부터」라고 나와요.","연우는 말하는 이를 부른 이름이에요.","말하는 이는 수빈이 생각을 자꾸 해요."],"asset":{"type":"passage","lines":["축구공을 차며 골대로 뛰어가는","수빈이를 본 뒤부터","연우야, 급식실 가자, 누가 불러도","축구공만 데굴데굴 굴러와"],"title":"「그때부터였나 봐」(임수현) 첫 연 — 『국어』 258쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#3','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C8',1,'mc','auto','‘……은/는 ……(이)다’처럼 빗대어 표현하는 방법을 무엇이라고 하나요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":3,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"‘……은/는 ……(이)다’처럼 빗대어 표현하는 방법을 무엇이라고 하나요?","options":[{"t":"은유법","correct":true},{"t":"직유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"}],"explanation":["비유적 표현에는 직유법과 은유법이 있어요.","‘같이’, ‘처럼’, ‘듯이’로 직접 비교하면 직유법이에요.","‘……은/는 ……(이)다’로 빗대면 은유법이에요."],"asset":{"type":"passage","lines":["비슷한 현상이나 사물을 다른 것에 빗대어 표현하는 것을 비유적 표현이라고 해요.","‘같이’, ‘처럼’, ‘듯이’를 써서 두 대상을 직접 비교하면 직유법,","‘……은/는 ……(이)다’처럼 빗대어 표현하면 은유법이에요."],"title":"비유적 표현 — 『국어』 262~263쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#4','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C12',1,'mc','auto','『국어』 265쪽 생각그물에서 「톡 / 탁 공을 치는 소리」는 어느 갈래에 들어가나요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C12","difficulty":1,"kind":"mc","stem":"『국어』 265쪽 생각그물에서 「톡 / 탁 공을 치는 소리」는 어느 갈래에 들어가나요?","options":[{"t":"들은 것","correct":true},{"t":"본 것","mis":"K6-2-u6-X12"},{"t":"만진 것","mis":"K6-2-u6-X12"},{"t":"비유적 표현","mis":"K6-2-u6-X12"}],"explanation":["공을 치는 소리는 귀로 들은 것이에요.","그 소리에서 경쾌한 느낌을 떠올렸어요.","감각 갈래로 나누어 모으면 경험이 생생해져요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#5','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C19',1,'mc','auto','시를 낭송할 때 지켜야 할 점으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X23','K6-2-u6-X47','K6-2-u6-X21']::text[],false,'{"seq":5,"concept":"K6-2-u6-C19","difficulty":1,"kind":"mc","stem":"시를 낭송할 때 지켜야 할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"시가 잘 들리도록 알맞은 크기의 목소리로 낭송한다","correct":true},{"t":"들리지 않을 만큼 작게 읽는다","mis":"K6-2-u6-X23"},{"t":"글자를 하나씩 끊어 읽는다","mis":"K6-2-u6-X47"},{"t":"마음과 상관없이 무조건 가장 크게 소리친다","mis":"K6-2-u6-X21"}],"explanation":["시가 들려야 마음이 전해져요.","리듬을 살려 이어 읽어요.","무조건 크게가 아니라 마음에 맞게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#6','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C38',1,'mc','auto','「알라딘과 요술 램프」에서 알라딘을 속인 남자는 사실 누구였나요?',ARRAY['K6-2-u6-X50']::text[],false,'{"seq":6,"concept":"K6-2-u6-C38","difficulty":1,"kind":"mc","stem":"「알라딘과 요술 램프」에서 알라딘을 속인 남자는 사실 누구였나요?","options":[{"t":"램프를 가지려던 못된 마법사","correct":true},{"t":"오랫동안 외국에 있던 진짜 삼촌","mis":"K6-2-u6-X50"},{"t":"알라딘을 지켜 주는 반지 요정","mis":"K6-2-u6-X50"},{"t":"램프 속에 사는 요정 지니","mis":"K6-2-u6-X50"}],"explanation":["남자는 자신이 삼촌이라고 했어요.","사실은 램프를 가지려고 알라딘을 속인 못된 마법사였어요.","램프를 주지 않자 돌문을 닫아 버렸어요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#7','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C41',1,'mc','auto','『국어』 288쪽에서 「어떤 대상에게 정성을 다하는 태도가 있다.」라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K6-2-u6-X49']::text[],false,'{"seq":7,"concept":"K6-2-u6-C41","difficulty":1,"kind":"mc","stem":"『국어』 288쪽에서 「어떤 대상에게 정성을 다하는 태도가 있다.」라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"극진하다","correct":true},{"t":"탄식하다","mis":"K6-2-u6-X49"},{"t":"아뢰다","mis":"K6-2-u6-X49"},{"t":"괴이쩍다","mis":"K6-2-u6-X49"}],"explanation":["뉘우친 옹고집은 아내와 자식에게 극진히 대했어요.","정성을 다하는 태도가 극진하다예요.","낱말의 앞뒤 문맥을 보면 뜻을 짐작할 수 있어요."],"asset":{"type":"passage","lines":["보기: 탄식하다 · 아뢰다 · 괴이쩍다 · 극진하다","● 어떤 대상에게 정성을 다하는 태도가 있다.","● 별나고 괴상한 느낌이 있다.","● 다른 사람에게 말씀드려서 알리다.","● 한탄하여 한숨을 쉬다."],"numbered":false,"title":"낱말 알기 — 『국어』 288쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#8','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C34',1,'mc','auto','「약속 시간에 늦을까 봐 얼마나 마음을 (    ) 몰라.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"mc","stem":"「약속 시간에 늦을까 봐 얼마나 마음을 (    ) 몰라.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"졸였는지","correct":true},{"t":"조렸는지","mis":"K6-2-u6-X43"},{"t":"줄였는지","mis":"K6-2-u6-X43"}],"explanation":["‘조리다’는 양념이 배어들게 끓이는 것이에요.","‘졸이다’는 속을 태우다시피 초조해하는 것이기도 해요.","초조한 마음은 ‘졸였는지’로 써요."],"asset":{"type":"passage","lines":["[문자] 약속 시간에 늦을까 봐 얼마나 마음을 조렸는지 몰라.","[생각] 마음을 조렸다고? 왠지 어색한데.","‘조리다’: 양념을 한 재료를 국물에 넣고 끓여 양념이 배어들게 하다.","‘졸이다’: 국물을 증발시켜 분량을 적어지게 하다.","또는 속을 태우다시피 초조해하다."],"numbered":false,"title":"기초 다지기 — 『국어』 297쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#9','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C10',2,'mc','auto','시의 특성으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X13','K6-2-u6-X04']::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"mc","stem":"시의 특성으로 알맞은 것은 무엇인가요?","options":[{"t":"연과 행으로 나누어 읽을 때 리듬감을 느낄 수 있다","correct":true},{"t":"겪은 일을 빠짐없이 길게 쓴 글이다","mis":"K6-2-u6-X09"},{"t":"비유적 표현이 없으면 시가 아니다","mis":"K6-2-u6-X13"},{"t":"어려운 말을 쓸수록 좋은 시다","mis":"K6-2-u6-X04"}],"explanation":["시는 생각이나 느낌을 짧은 글로 압축해요.","연과 행으로 나누어 읽으면 리듬감이 있어요.","비유적·감각적 표현으로 생생하게 나타내기도 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이야. 연과 행으로 나누어 읽을 때 리듬감을 느낄 수 있어."},{"who":"친구 2","text":"비유적 표현을 활용해서 시를 쓴 사람이 표현하고 싶은 느낌을 더 생생하게 나타내기도 해."},{"who":"친구 3","text":"감각적 표현을 활용하여 생생하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#10','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',2,'mc','auto','경험을 생각그물로 정리한 뒤 시를 쓸 때 알맞은 방법은 무엇인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X17','K6-2-u6-X07']::text[],false,'{"seq":10,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"경험을 생각그물로 정리한 뒤 시를 쓸 때 알맞은 방법은 무엇인가요?","options":[{"t":"인상 깊었던 것을 골라 짧고 간결하게 쓴다","correct":true},{"t":"모은 것을 모두 넣는다","mis":"K6-2-u6-X16"},{"t":"짧을수록 좋으니 한 줄만 쓴다","mis":"K6-2-u6-X17"},{"t":"생각그물에 없는 일을 꾸며 넣는다","mis":"K6-2-u6-X07"}],"explanation":["생각그물은 경험을 넓게 모은 것이에요.","시를 쓸 때에는 인상 깊었던 것을 골라요.","한 줄로 줄이는 것이 아니라 마음이 또렷해지게 골라요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#11','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C16',2,'mc','auto','시를 낭송할 때 목소리와 속도를 정하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X20','K6-2-u6-X22']::text[],false,'{"seq":11,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"시를 낭송할 때 목소리와 속도를 정하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"듣는 사람에게 전하고 싶은 마음과 시의 장면","correct":true},{"t":"가장 크게 들리는 목소리","mis":"K6-2-u6-X21"},{"t":"처음부터 끝까지 같은 빠르기","mis":"K6-2-u6-X20"},{"t":"친구들이 좋아하는 노래의 빠르기","mis":"K6-2-u6-X22"}],"explanation":["먼저 전하고 싶은 마음을 정해요.","장면마다 마음에 어울리는 목소리와 속도를 찾아요.","여러 방법으로 읽어 보며 알맞은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#12','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C21',2,'mc','auto','이야기에서 인물의 성격이 바뀌면 무엇이 함께 달라지나요?',ARRAY['K6-2-u6-X06','K6-2-u6-X27','K6-2-u6-X35']::text[],false,'{"seq":12,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"이야기에서 인물의 성격이 바뀌면 무엇이 함께 달라지나요?","options":[{"t":"인물이 하는 말과 행동, 그리고 사건","correct":true},{"t":"아무것도 달라지지 않는다","mis":"K6-2-u6-X06"},{"t":"인물의 이름만 달라진다","mis":"K6-2-u6-X27"},{"t":"책의 쪽수가 달라진다","mis":"K6-2-u6-X35"}],"explanation":["인물의 성격에 따라 행동이 바뀌어요.","행동이 바뀌면 사건도 다르게 전개돼요.","알라딘의 성격이 바뀌자 소원도 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#13','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C25',2,'blank','auto','『국어』 281쪽 주의할 점의 ㉠에 들어갈 말은 무엇인가요? 「이야기를 자신이 잘 알거나 익숙한 내용으로 바꾸고 싶을 때에는 (  ㉠  )을/를 떠올려 본다.」',ARRAY['K6-2-u6-X46','K6-2-u6-X05']::text[],false,'{"seq":13,"concept":"K6-2-u6-C25","difficulty":2,"kind":"blank","stem":"『국어』 281쪽 주의할 점의 ㉠에 들어갈 말은 무엇인가요? 「이야기를 자신이 잘 알거나 익숙한 내용으로 바꾸고 싶을 때에는 (  ㉠  )을/를 떠올려 본다.」","options":[{"t":"자신의 경험","correct":true},{"t":"주장과 근거","mis":"K6-2-u6-X46"},{"t":"원인과 결과","mis":"K6-2-u6-X05"},{"t":"인물이나 배경","mis":"K6-2-u6-X05"}],"explanation":["익숙한 내용으로 바꾸려면 자기 경험을 떠올려요.","경험을 바탕으로 하면 이야기가 생생해져요.","주장과 근거는 이야기의 요소가 아니에요."],"asset":{"type":"passage","lines":["보기: 주장과 근거 · 자신의 경험 · 원인과 결과 · 인물이나 배경","● 이야기를 자신이 잘 알거나 익숙한 내용으로 바꾸고 싶을 때에는","(  ㉠  )을/를 떠올려 본다.","● 이야기의 세 가지 요소 가운데에서 (  ㉡  )을/를 바꾸면","사건이 어떻게 달라질지 생각하며 쓴다.","● 사건 사이의 (  ㉢  )을/를 생각하며 이야기를 바꾸어 쓴다."],"numbered":false,"title":"이야기를 바꾸어 쓸 때 주의할 점 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#14','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C27',2,'mc','auto','「옹고집전」의 흐름에서 전개에 해당하는 일은 무엇인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":14,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「옹고집전」의 흐름에서 전개에 해당하는 일은 무엇인가요?","options":[{"t":"옹고집이 걸인을 쫓아냈고, 도사가 짚으로 가짜 옹고집을 만들었다","correct":true},{"t":"옛날에 고집 세고 심술궂은 옹고집이 살았다","mis":"K6-2-u6-X34"},{"t":"사또가 진짜 옹고집을 가짜라고 판결했다","mis":"K6-2-u6-X34"},{"t":"옹고집이 뉘우치고 돌아와 착하게 살았다","mis":"K6-2-u6-X34"}],"explanation":["발단에서 인물과 배경을 소개해요.","전개에서 사건이 시작돼요.","걸인을 내쫓은 일이 가짜 옹고집을 불러왔어요."],"asset":{"type":"passage","lines":["발단 — 옛날에 고집 세고 심술궂은 옹고집이 살았다.","전개 — 걸인을 몽둥이질해 쫓아냈고, 도사는 짚으로 가짜 옹고집을 만들었다.","절정 — 진짜와 가짜가 싸웠고, 사또가 진짜를 가짜라고 판결해 쫓겨났다.","결말 — 떠돌며 고생한 진짜 옹고집은 뉘우치고 돌아와 착하게 살았다."],"numbered":false,"title":"「옹고집전」 사건의 흐름 — 『국어』 289쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#15','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C42',2,'mc','auto','「양말 한 짝」에서 양말이 사라지는 때는 언제인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":15,"concept":"K6-2-u6-C42","difficulty":2,"kind":"mc","stem":"「양말 한 짝」에서 양말이 사라지는 때는 언제인가요?","options":[{"t":"세탁기에서 나올 때","correct":true},{"t":"신발을 신을 때","mis":"K6-2-u6-X07"},{"t":"서랍을 정리할 때","mis":"K6-2-u6-X07"},{"t":"잠자리에 들 때","mis":"K6-2-u6-X07"}],"explanation":["시에 「세탁기에서 나올 때」라는 행이 있어요.","그때 기회를 틈타 양말이 사라진다고 했어요.","빨래를 꺼낼 때 한 짝이 없어진 경험이에요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#16','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C31',2,'mc','auto','종이책, 오디오 북, 전자책 가운데 학급 이야기책의 형태를 고를 때 알맞은 생각은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39','K6-2-u6-X41']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"종이책, 오디오 북, 전자책 가운데 학급 이야기책의 형태를 고를 때 알맞은 생각은 무엇인가요?","options":[{"t":"저마다 장단점이 있으니 독자에게 잘 전할 형태를 고른다","correct":true},{"t":"가장 새로운 형태가 언제나 가장 좋다","mis":"K6-2-u6-X38"},{"t":"형태부터 고르고 독자는 나중에 생각한다","mis":"K6-2-u6-X39"},{"t":"표지가 화려해지는 형태를 고른다","mis":"K6-2-u6-X41"}],"explanation":["책의 형태는 여러 가지예요.","형태마다 장단점이 있어요.","예상 독자에게 가장 잘 전할 형태를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#17','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',3,'mc','auto','경험을 시로 창작한 것을 평가할 때 살펴볼 점으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X03','K6-2-u6-X19']::text[],false,'{"seq":17,"concept":"K6-2-u6-C13","difficulty":3,"kind":"mc","stem":"경험을 시로 창작한 것을 평가할 때 살펴볼 점으로 알맞은 것은 무엇인가요?","options":[{"t":"생각이나 느낌을 감각적·비유적 표현으로 잘 나타냈는지","correct":true},{"t":"완성된 시가 얼마나 길고 줄 수가 많은지","mis":"K6-2-u6-X09"},{"t":"빗댄 표현을 시 안에 몇 개나 넣었는지","mis":"K6-2-u6-X03"},{"t":"글씨를 반듯하고 깨끗하게 썼는지","mis":"K6-2-u6-X19"}],"explanation":["경험을 생생하게 표현했는지 살펴요.","생각이나 느낌이 감각적·비유적 표현으로 잘 드러났는지 봐요.","길이나 개수, 글씨는 평가의 중점이 아니에요."],"asset":{"type":"passage","lines":["[활동지] 경험을 시로 창작하기","• 시로 표현하고 싶은 경험","• 생각이나 느낌","• 경험을 시로 창작하기"],"numbered":false,"title":"단원 마무리 활동지 — 경험을 시로 창작하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#18','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C23',3,'mc','auto','앞 이야기와 전혀 이어지지 않는 엉뚱한 이야기를 쓴 친구에게 해 줄 도움으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X29']::text[],false,'{"seq":18,"concept":"K6-2-u6-C23","difficulty":3,"kind":"mc","stem":"앞 이야기와 전혀 이어지지 않는 엉뚱한 이야기를 쓴 친구에게 해 줄 도움으로 알맞은 것은 무엇인가요?","options":[{"t":"원인과 결과의 연쇄로 앞 이야기와 이어지게 하도록 돕는다","correct":true},{"t":"엉뚱할수록 재미있으니 그대로 둔다","mis":"K6-2-u6-X30"},{"t":"앞 이야기를 모두 지우고 새로 쓰게 한다","mis":"K6-2-u6-X36"},{"t":"더 놀라운 사건을 하나 더 넣게 한다","mis":"K6-2-u6-X29"}],"explanation":["바꾸어 쓴 이야기는 앞부분과 자연스럽게 이어져야 해요.","앞의 일이 원인이 되어 뒤의 일이 일어나게 해요.","원인과 결과로 이으면 연결성이 높아져요."],"asset":{"type":"passage","lines":["[활동지] 재미있게 읽은 이야기의 일부분을 바꾸어 쓰기","• 이야기의 원래 제목","• 바꾸어 쓰고 싶은 부분","• 제목 · 바꾸어 쓴 이야기","• 독자의 소감(독자 이름 · 재미있었거나 기억에 남는 부분 · 그 밖의 의견)"],"numbered":false,"title":"단원 마무리 활동지 — 이야기의 일부분을 바꾸어 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#19','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C20',3,'mc','auto','패러디에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X26','K6-2-u6-X32']::text[],false,'{"seq":19,"concept":"K6-2-u6-C20","difficulty":3,"kind":"mc","stem":"패러디에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"원작을 비틀어 새로운 메시지를 만든 것으로, 표절과 다르다","correct":true},{"t":"원작을 그대로 베껴 쓴 표절과 같은 것이다","mis":"K6-2-u6-X26"},{"t":"원작보다 글을 길게 늘인 것일 뿐이다","mis":"K6-2-u6-X32"},{"t":"원작의 글자만 몇 개 바꾸어 쓴 것이다","mis":"K6-2-u6-X26"}],"explanation":["「알라딘과 신기한 램프」는 알라딘 이야기를 비틀어 썼어요.","원작을 바탕으로 새로운 메시지를 만드는 것이 패러디예요.","그대로 베끼는 표절과는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#20','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C30',3,'mc','auto','친구의 글에 칭찬 쪽지를 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X42']::text[],false,'{"seq":20,"concept":"K6-2-u6-C30","difficulty":3,"kind":"mc","stem":"친구의 글에 칭찬 쪽지를 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"‘……한 점이 재미있다.’, ‘…… 부분이 인상 깊다.’처럼 구체적으로 쓴다","correct":true},{"t":"‘잘 썼다.’, ‘재미있다.’처럼 짧고 막연하게 쓴다","mis":"K6-2-u6-X25"},{"t":"친구 글에서 고칠 점과 틀린 곳부터 찾아 쓴다","mis":"K6-2-u6-X42"},{"t":"글씨가 예쁘고 반듯하다는 것만 칭찬해 쓴다","mis":"K6-2-u6-X25"}],"explanation":["칭찬 쪽지는 친구의 글에서 좋은 점을 찾아 써요.","어느 부분이 왜 좋은지 구체적으로 써요.","‘잘 썼다.’, ‘재미있다.’보다 자세하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#21','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C25',3,'mc','auto','이야기를 바꾸어 쓸 때 담을 수 있는 경험에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X48','K6-2-u6-X31','K6-2-u6-X02']::text[],false,'{"seq":21,"concept":"K6-2-u6-C25","difficulty":3,"kind":"mc","stem":"이야기를 바꾸어 쓸 때 담을 수 있는 경험에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"직접 겪은 일뿐 아니라 읽거나 들은 간접 경험도 담을 수 있다","correct":true},{"t":"직접 겪은 일만 담을 수 있다","mis":"K6-2-u6-X48"},{"t":"겪은 일을 일기처럼 그대로 옮겨야 한다","mis":"K6-2-u6-X31"},{"t":"대단한 일을 겪은 경험만 담을 수 있다","mis":"K6-2-u6-X02"}],"explanation":["직접 경험뿐만 아니라 간접 경험도 활용할 수 있어요.","읽거나 들은 이야기도 경험이 돼요.","경험에 너무 얽매이지 않고 자유롭게 상상해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#22','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C10',3,'mc','auto','『국어』 296쪽에서 이 단원에서 공부한 내용을 정리한 말로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X46','K6-2-u6-X30']::text[],false,'{"seq":22,"concept":"K6-2-u6-C10","difficulty":3,"kind":"mc","stem":"『국어』 296쪽에서 이 단원에서 공부한 내용을 정리한 말로 알맞은 것은 무엇인가요?","options":[{"t":"시를 쓸 때 비유적 표현이나 감각적 표현을 활용할 수 있다","correct":true},{"t":"시를 쓸 때 겪은 일을 빠짐없이 모두 적는다","mis":"K6-2-u6-X09"},{"t":"이야기를 바꾸어 쓸 때 주장과 근거를 먼저 정한다","mis":"K6-2-u6-X46"},{"t":"이야기를 바꾸어 쓸 때 놀라운 사건을 많이 넣는다","mis":"K6-2-u6-X30"}],"explanation":["시는 비유적·감각적 표현으로 생생하게 써요.","이야기는 경험을 바탕으로 인물이나 배경을 바꾸어 봐요.","처음, 가운데, 끝이 자연스럽게 이어지게 써요."],"asset":{"type":"passage","lines":["● 이야기를 바꾸어 쓸 때에는 자신의 경험을 바탕으로 인물이나 배경을 바꾸어 본다.","● 이야기를 바꾸어 쓸 때에는 처음, 가운데, 끝으로 자연스럽게 이어지도록 한다.","● 시를 쓸 때 비유적 표현이나 감각적 표현을 활용할 수 있다."],"numbered":false,"title":"이 단원에서 공부한 내용 정리 — 『국어』 296쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#23','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C11',4,'essay','teacher','「경험을 시로 창작하기」 활동지처럼 시로 표현하고 싶은 경험과 그때의 생각이나 느낌을 쓰고, 그 경험을 두 연 이상의 짧은 시로 써 보세요. 비유적 표현이나 감각적 표현을 한 가지 이상 넣으세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u6-C11","difficulty":4,"kind":"essay","stem":"「경험을 시로 창작하기」 활동지처럼 시로 표현하고 싶은 경험과 그때의 생각이나 느낌을 쓰고, 그 경험을 두 연 이상의 짧은 시로 써 보세요. 비유적 표현이나 감각적 표현을 한 가지 이상 넣으세요.","answer_guide":{"answer":"예: 경험 — 비 오는 날 혼자 우산을 쓰고 집에 온 일. 생각이나 느낌 — 처음엔 쓸쓸했지만 빗소리를 들으며 마음이 편해졌다. 시 — 「우산 속 음악회」 / 톡톡 투둑 / 우산 위로 빗방울이 노래한다 // 혼자 걷는 길인데 / 우산 속은 작은 음악회 / 나는 맨 앞자리 관객이다","scoring_points":["경험과 생각이나 느낌을 썼는가","연과 행을 나누어 시의 형식을 갖추었는가","비유적 표현이나 감각적 표현으로 마음을 생생하게 나타냈는가"]},"explanation":["일상 속 경험도 좋은 시가 돼요.","연과 행으로 나누고 인상 깊은 것만 골라 써요.","감각적·비유적 표현으로 생각이나 느낌을 살려요."],"asset":{"type":"passage","lines":["[활동지] 경험을 시로 창작하기","• 시로 표현하고 싶은 경험","• 생각이나 느낌","• 경험을 시로 창작하기"],"numbered":false,"title":"단원 마무리 활동지 — 경험을 시로 창작하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#24','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C28',4,'essay','teacher','「이야기의 일부분을 바꾸어 쓰기」 활동지처럼 재미있게 읽은 이야기의 원래 제목과 바꾸어 쓰고 싶은 부분을 쓰고, 그 부분을 어떻게 바꾸어 쓸지 사건 세 가지로 쓰세요. 그렇게 바꾼 까닭도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C28","difficulty":4,"kind":"essay","stem":"「이야기의 일부분을 바꾸어 쓰기」 활동지처럼 재미있게 읽은 이야기의 원래 제목과 바꾸어 쓰고 싶은 부분을 쓰고, 그 부분을 어떻게 바꾸어 쓸지 사건 세 가지로 쓰세요. 그렇게 바꾼 까닭도 쓰세요.","answer_guide":{"answer":"예: 원래 제목 — 「알라딘과 요술 램프」. 바꾸고 싶은 부분 — 알라딘이 지니에게 소원을 비는 부분. 사건 — 알라딘은 부자가 되는 소원 대신 병든 이웃을 낫게 해 달라고 빈다. 소문을 들은 마법사가 램프를 빼앗으러 온다. 이웃들이 힘을 모아 알라딘을 지켜 준다. 까닭 — 아플 때 이웃이 도와준 경험이 있어 서로 돕는 이야기로 바꾸고 싶었다.","scoring_points":["원래 제목과 바꿀 부분을 구체적으로 썼는가","사건 세 가지가 앞 이야기와 원인과 결과로 자연스럽게 이어지는가","바꾼 까닭에 자신의 경험이나 생각을 썼는가"]},"explanation":["바꿀 부분을 구체적으로 정해요.","바뀐 부분에 따라 사건을 원인과 결과로 이어요.","어느 부분에 경험을 녹였는지 설명할 수 있어야 해요."],"asset":{"type":"passage","lines":["[활동지] 재미있게 읽은 이야기의 일부분을 바꾸어 쓰기","• 이야기의 원래 제목","• 바꾸어 쓰고 싶은 부분","• 제목 · 바꾸어 쓴 이야기","• 독자의 소감(독자 이름 · 재미있었거나 기억에 남는 부분 · 그 밖의 의견)"],"numbered":false,"title":"단원 마무리 활동지 — 이야기의 일부분을 바꾸어 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_a#25','kor',6,2,'u6','','tb_g6_2_kor_u6_review_a','unit_review','K6-2-u6-C42',4,'essay','teacher','「양말 한 짝」을 읽고 어떤 경험을 시로 표현했는지 쓰고, 이 시에서 볼 수 있는 시의 특성을 두 가지 찾아 시의 어느 부분에서 그 특성이 드러나는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C42","difficulty":4,"kind":"essay","stem":"「양말 한 짝」을 읽고 어떤 경험을 시로 표현했는지 쓰고, 이 시에서 볼 수 있는 시의 특성을 두 가지 찾아 시의 어느 부분에서 그 특성이 드러나는지 쓰세요.","answer_guide":{"answer":"예: 「양말 한 짝」은 양말 한 짝이 사라진 경험을 표현했다. 첫째, 감각적 표현을 썼다. 세탁기에서 「꼬물꼬물」 나온다고 해 양말의 모습이 눈에 보이는 듯하다. 둘째, 행을 짧게 나누고 같은 말을 되풀이해 읽을 때 리듬감이 있다.","scoring_points":["시에 담긴 경험을 썼는가","시의 특성을 두 가지 썼는가","특성마다 시에서 드러난 부분을 찾았는가"]},"explanation":["시에 담긴 경험은 시 안의 말에서 찾아요.","감각적 표현, 비유, 되풀이, 연과 행을 살펴요.","특성이 드러난 부분을 짚어 써요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#1','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C35',1,'sa','auto','「눈꺼풀」에서 말하는 이에게 졸음이 쏟아진 것은 무슨 수업 시간이었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u6-C35","difficulty":1,"kind":"sa","stem":"「눈꺼풀」에서 말하는 이에게 졸음이 쏟아진 것은 무슨 수업 시간이었나요? 두 글자로 쓰세요.","answer":["도덕"],"explanation":["시에 「5교시 도덕 시간」이 나와요.","점심 먹고 축구를 한 뒤였어요.","도덕 시간에 눈꺼풀이 자꾸 내려왔어요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"},"mis":"K6-2-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#2','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C36',1,'sa','auto','「그때부터였나 봐」에서 말하는 이의 커져 가는 마음을 무엇이 수북이 쌓였다고 표현했나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C36","difficulty":1,"kind":"sa","stem":"「그때부터였나 봐」에서 말하는 이의 커져 가는 마음을 무엇이 수북이 쌓였다고 표현했나요? 세 글자로 쓰세요.","answer":["축구공"],"explanation":["「축구공이 수북이 쌓였어」라는 행이 있어요.","축구공은 수빈이를 떠올리게 해요.","공이 쌓이듯 마음이 점점 커져 가요."],"asset":{"type":"passage","lines":["(간추림) 음악실에 가야 하는데 과학실에 가고, 종이 쳐도 운동장만 내다본다.","(간추림) 수학책을 꺼내라는데 수빈이가 찬 공이 굴러온다.","(간추림) 과학실에도 급식실에도, 건반과 곱셈 위에도 공이 쌓여 간다.","축구공이 수북이 쌓였어","(간추림) 눈을 감고 있어도 수빈이가 공을 몰고 다가온다."],"numbered":false,"title":"「그때부터였나 봐」(임수현) 뒷부분 — 『국어』 258~259쪽"},"mis":"K6-2-u6-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#3','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C37',1,'mc','auto','「오늘 날씨는」에서 수다스러운 친구에 빗댄 날씨는 무엇인가요?',ARRAY['K6-2-u6-X10']::text[],false,'{"seq":3,"concept":"K6-2-u6-C37","difficulty":1,"kind":"mc","stem":"「오늘 날씨는」에서 수다스러운 친구에 빗댄 날씨는 무엇인가요?","options":[{"t":"소나기","correct":true},{"t":"첫눈","mis":"K6-2-u6-X10"},{"t":"번개","mis":"K6-2-u6-X10"},{"t":"천둥","mis":"K6-2-u6-X10"}],"explanation":["수다스러운 소나기는 우산을 두드리며 말을 걸어요.","쉴 새 없이 말을 거는 모습이 수다스러운 친구와 닮았어요.","두 대상의 비슷한 점으로 빗대었어요."],"asset":{"type":"passage","lines":["수다스러운 소나기는","수줍음 많은 첫눈은","장난기 많은 번개는","목소리가 큰 천둥은","소나기처럼 첫눈처럼 번개처럼 천둥처럼","(간추림) 말하는 이는 오늘 전학을 왔고, 새 반 아이들이","자신을 어떤 날씨라고 생각할지 궁금해한다."],"numbered":false,"title":"「오늘 날씨는」(양슬기) 가운데 — 『국어』 262쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#4','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C9',1,'mc','auto','본 것, 들은 것, 맛본 것처럼 감각을 살려 경험을 생생하게 나타낸 표현을 무엇이라고 하나요?',ARRAY['K6-2-u6-X12','K6-2-u6-X11']::text[],false,'{"seq":4,"concept":"K6-2-u6-C9","difficulty":1,"kind":"mc","stem":"본 것, 들은 것, 맛본 것처럼 감각을 살려 경험을 생생하게 나타낸 표현을 무엇이라고 하나요?","options":[{"t":"감각적 표현","correct":true},{"t":"비유적 표현","mis":"K6-2-u6-X12"},{"t":"직유법","mis":"K6-2-u6-X11"},{"t":"은유법","mis":"K6-2-u6-X11"}],"explanation":["『국어』 266쪽에서 친구가 말한 특성이에요.","감각을 살린 표현은 경험을 생생하게 나타내요.","다른 것에 빗대는 비유적 표현과 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#5','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C18',1,'mc','auto','시 낭송을 감상하는 태도로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":5,"concept":"K6-2-u6-C18","difficulty":1,"kind":"mc","stem":"시 낭송을 감상하는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"낭송하는 사람을 바라보며 집중해서 듣는다","correct":true},{"t":"옆 친구와 장난을 치며 듣는다","mis":"K6-2-u6-X24"},{"t":"틀린 글자만 찾으며 듣는다","mis":"K6-2-u6-X24"}],"explanation":["『국어』 268쪽 감상할 때 주의할 점이에요.","낭송하는 사람을 바라보며 들어요.","시와 관련 있는 경험을 떠올리며 감상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#6','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C39',1,'mc','auto','「알라딘과 신기한 램프」에서 알라딘이 지니에게 빈 소원은 무엇인가요?',ARRAY['K6-2-u6-X50','K6-2-u6-X07']::text[],false,'{"seq":6,"concept":"K6-2-u6-C39","difficulty":1,"kind":"mc","stem":"「알라딘과 신기한 램프」에서 알라딘이 지니에게 빈 소원은 무엇인가요?","options":[{"t":"전쟁을 없애고 무기를 사라지게 해 달라는 소원","correct":true},{"t":"부자가 되게 해 달라는 소원","mis":"K6-2-u6-X50"},{"t":"왕자 비가 되게 해 달라는 소원","mis":"K6-2-u6-X07"},{"t":"하얀 대리석 궁전을 달라는 소원","mis":"K6-2-u6-X07"}],"explanation":["지니는 궁전과 왕자 비 자리를 권했어요.","알라딘은 더 쓸모 있는 것을 원했어요.","그래서 전쟁을 없애 달라는 소원을 빌었어요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#7','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C40',1,'mc','auto','「옹고집전」에서 옹고집은 동냥을 온 걸인에게 어떻게 했나요?',ARRAY['K6-2-u6-X33','K6-2-u6-X50']::text[],false,'{"seq":7,"concept":"K6-2-u6-C40","difficulty":1,"kind":"mc","stem":"「옹고집전」에서 옹고집은 동냥을 온 걸인에게 어떻게 했나요?","options":[{"t":"몽둥이질을 해 내쫓았다","correct":true},{"t":"먹을 것을 넉넉히 주었다","mis":"K6-2-u6-X33"},{"t":"집에 머물게 해 주었다","mis":"K6-2-u6-X33"},{"t":"사또에게 데려갔다","mis":"K6-2-u6-X50"}],"explanation":["하인은 걸인에게 어서 돌아가라고 했어요.","옹고집은 화를 내며 걸인을 몽둥이질해 내쫓았어요.","이 행동에서 옹고집의 심술궂은 성격이 드러나요."],"asset":{"type":"passage","lines":["(간추림) 옹진골의 옹고집은 고집이 아주 세고 심술궂은 큰 부자였다.","(간추림) 병든 어머니를 돌보지 않았고, 가족과 일꾼에게도 심술궂게 굴었다.","“흥! 내가 그리해 달라고 부탁한 것도 아니잖소?”","(간추림) 동냥을 온 늙은 걸인을 몽둥이질해 내쫓았다.","(간추림) 걸인은 도를 닦은 도사였고, 짚 인형으로 가짜 옹고집을 만들었다."],"numbered":false,"title":"「옹고집전」 앞부분 간추림 — 『국어』 282~283쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#8','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C34',1,'mc','auto','소리는 같지만 뜻이 다른 낱말끼리 짝 지은 것은 무엇인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"mc","stem":"소리는 같지만 뜻이 다른 낱말끼리 짝 지은 것은 무엇인가요?","options":[{"t":"시켰다 — 식혔다","correct":true},{"t":"먹었다 — 마셨다","mis":"K6-2-u6-X43"},{"t":"크다 — 작다","mis":"K6-2-u6-X43"}],"explanation":["『국어』 297쪽 3번에 나온 두 낱말이에요.","‘시켰다’와 ‘식혔다’는 소리가 같아요.","하지만 뜻이 달라 상황에 맞게 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#9','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C10',2,'blank','auto','「시는 자신의 생각이나 느낌을 짧은 글로 (    )해서 쓴 글이야.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X13','K6-2-u6-X01']::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"blank","stem":"「시는 자신의 생각이나 느낌을 짧은 글로 (    )해서 쓴 글이야.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"압축","correct":true},{"t":"나열","mis":"K6-2-u6-X09"},{"t":"반복","mis":"K6-2-u6-X13"},{"t":"확대","mis":"K6-2-u6-X01"}],"explanation":["『국어』 263쪽 7번에서 친구가 한 말이에요.","시는 생각이나 느낌을 짧은 글로 압축해요.","그래서 시는 간결하고 리듬감이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#10','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C11',2,'mc','auto','시로 표현할 경험을 짝과 묻고 답할 때 『국어』 264쪽 예시 답안으로 나온 질문은 무엇인가요?',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":10,"concept":"K6-2-u6-C11","difficulty":2,"kind":"mc","stem":"시로 표현할 경험을 짝과 묻고 답할 때 『국어』 264쪽 예시 답안으로 나온 질문은 무엇인가요?","options":[{"t":"그 경험을 무엇에 빗대어 표현할 수 있을까요?","correct":true},{"t":"그 경험을 몇 줄로 쓸 건가요?","mis":"K6-2-u6-X15"},{"t":"그 경험은 몇 시 몇 분에 있었나요?","mis":"K6-2-u6-X15"}],"explanation":["『국어』 264쪽 (2)에 질문이 나와요.","가장 재미있었던 순간과 빗댈 대상을 묻는 질문이 예시 답안이에요.","경험을 자세히 떠올리게 하는 질문이 좋아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"체육 시간에 배드민턴을 쳤던 경험을 시로 표현하고 싶어."},{"who":"친구 2","text":"배드민턴을 칠 때 어떤 경험이 가장 기억에 남았어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#11','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C17',2,'mc','auto','시 낭송에 배경 음악을 쓸 때 주의할 점은 무엇인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":11,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"시 낭송에 배경 음악을 쓸 때 주의할 점은 무엇인가요?","options":[{"t":"낭송하는 목소리보다 크지 않게 한다","correct":true},{"t":"목소리가 묻힐 만큼 크게 튼다","mis":"K6-2-u6-X22"},{"t":"시와 상관없이 신나는 음악을 고른다","mis":"K6-2-u6-X22"},{"t":"음악만 틀고 낭송은 하지 않는다","mis":"K6-2-u6-X20"}],"explanation":["배경 음악은 낭송을 돕는 것이에요.","목소리보다 크면 시가 들리지 않아요.","시의 분위기에 어울리는 음악을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#12','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C22',2,'mc','auto','이야기의 배경을 바꾸면 어떤 것들이 달라질 수 있나요?',ARRAY['K6-2-u6-X28','K6-2-u6-X06']::text[],false,'{"seq":12,"concept":"K6-2-u6-C22","difficulty":2,"kind":"mc","stem":"이야기의 배경을 바꾸면 어떤 것들이 달라질 수 있나요?","options":[{"t":"인물의 행동이나 사건","correct":true},{"t":"인물의 생김새만","mis":"K6-2-u6-X28"},{"t":"아무것도 달라지지 않는다","mis":"K6-2-u6-X06"},{"t":"제목만","mis":"K6-2-u6-X28"}],"explanation":["배경은 일이 일어난 때와 곳이에요.","배경이 바뀌면 인물이 할 수 있는 일이 달라져요.","그래서 인물의 행동이나 사건이 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#13','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C23',2,'blank','auto','『국어』 281쪽 주의할 점의 ㉢에 들어갈 말은 무엇인가요? 「사건 사이의 (  ㉢  )을/를 생각하며 이야기를 바꾸어 쓴다.」',ARRAY['K6-2-u6-X46','K6-2-u6-X05']::text[],false,'{"seq":13,"concept":"K6-2-u6-C23","difficulty":2,"kind":"blank","stem":"『국어』 281쪽 주의할 점의 ㉢에 들어갈 말은 무엇인가요? 「사건 사이의 (  ㉢  )을/를 생각하며 이야기를 바꾸어 쓴다.」","options":[{"t":"원인과 결과","correct":true},{"t":"주장과 근거","mis":"K6-2-u6-X46"},{"t":"자신의 경험","mis":"K6-2-u6-X05"},{"t":"인물이나 배경","mis":"K6-2-u6-X05"}],"explanation":["사건은 원인과 결과로 이어져요.","앞의 일이 원인이 되어 뒤의 일이 일어나요.","그래야 이야기가 자연스러워요."],"asset":{"type":"passage","lines":["보기: 주장과 근거 · 자신의 경험 · 원인과 결과 · 인물이나 배경","● 이야기를 자신이 잘 알거나 익숙한 내용으로 바꾸고 싶을 때에는","(  ㉠  )을/를 떠올려 본다.","● 이야기의 세 가지 요소 가운데에서 (  ㉡  )을/를 바꾸면","사건이 어떻게 달라질지 생각하며 쓴다.","● 사건 사이의 (  ㉢  )을/를 생각하며 이야기를 바꾸어 쓴다."],"numbered":false,"title":"이야기를 바꾸어 쓸 때 주의할 점 — 『국어』 281쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#14','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C27',2,'mc','auto','「옹고집전」의 사건을 일어난 차례대로 바르게 놓은 것은 무엇인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":14,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「옹고집전」의 사건을 일어난 차례대로 바르게 놓은 것은 무엇인가요?","options":[{"t":"걸인을 내쫓음 → 가짜 옹고집이 나타남 → 재판에서 쫓겨남 → 뉘우치고 돌아옴","correct":true},{"t":"가짜 옹고집이 나타남 → 걸인을 내쫓음 → 뉘우치고 돌아옴 → 재판에서 쫓겨남","mis":"K6-2-u6-X34"},{"t":"재판에서 쫓겨남 → 걸인을 내쫓음 → 가짜 옹고집이 나타남 → 뉘우치고 돌아옴","mis":"K6-2-u6-X34"},{"t":"걸인을 내쫓음 → 뉘우치고 돌아옴 → 가짜 옹고집이 나타남 → 재판에서 쫓겨남","mis":"K6-2-u6-X34"}],"explanation":["『국어』 289쪽 (3)에서 먼저 일어난 일부터 정리했어요.","앞의 일이 원인이 되어 뒤의 일이 일어나요.","걸인을 내쫓은 일이 모든 사건의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#15','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C42',2,'ox','auto','「양말 한 짝」은 한 짝만 사라져도 두 짝 다 사라진 것과 같다고 재미있게 표현했어요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":15,"concept":"K6-2-u6-C42","difficulty":2,"kind":"ox","stem":"「양말 한 짝」은 한 짝만 사라져도 두 짝 다 사라진 것과 같다고 재미있게 표현했어요.","answer":"O","reason_options":[{"t":"한 짝만 남으면 신을 수 없는 경험을 재치 있게 나타냈기 때문에","correct":true},{"t":"실제로 두 짝이 모두 사라졌기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["사라진 것은 한 짝이에요.","하지만 한 짝만 남으면 신을 수 없어요.","그 마음을 두 짝 다 사라진 거라고 재치 있게 나타냈어요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#16','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C32',2,'mc','auto','『국어』 292쪽에서 이야기를 쓰기 전에 정하는 세부 사항으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X40','K6-2-u6-X46']::text[],false,'{"seq":16,"concept":"K6-2-u6-C32","difficulty":2,"kind":"mc","stem":"『국어』 292쪽에서 이야기를 쓰기 전에 정하는 세부 사항으로 알맞은 것은 무엇인가요?","options":[{"t":"등장인물의 이름과 성격, 일이 일어난 시간과 공간, 중심 사건","correct":true},{"t":"표지 색깔과 책 안에 들어갈 글자의 크기","mis":"K6-2-u6-X40"},{"t":"책을 몇 권 찍고 누구에게 나누어 줄지","mis":"K6-2-u6-X40"},{"t":"이야기로 내세울 주장과 그 근거","mis":"K6-2-u6-X46"}],"explanation":["이야기의 세 요소를 먼저 정해요.","인물, 배경, 사건이 정해지면 전개 과정을 쓸 수 있어요.","겉모습은 나중에 정해도 돼요."],"asset":{"type":"passage","lines":["① 학급에서 만들고 싶은 이야기책 형태 정하기","(소리를 녹음한 오디오 북 · 프레젠테이션 프로그램으로 만든 책)","② 쓰고 싶은 이야기의 중심 사건, 등장인물, 배경 정하기","③ 사건의 전개 과정을 간단히 써 보기","④ 매체를 활용해 이야기를 만들고 학급 온라인 게시판에 올리기","⑤ 반 친구들의 이야기를 모아 이야기책으로 만들기"],"numbered":false,"title":"매체를 활용한 학급 이야기책 만들기 — 『국어』 292쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#17','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C11',3,'mc','auto','경험을 시로 창작한 것을 평가할 때 완성된 시만 보지 않고 함께 살펴보는 것은 무엇인가요?',ARRAY['K6-2-u6-X19','K6-2-u6-X17','K6-2-u6-X09']::text[],false,'{"seq":17,"concept":"K6-2-u6-C11","difficulty":3,"kind":"mc","stem":"경험을 시로 창작한 것을 평가할 때 완성된 시만 보지 않고 함께 살펴보는 것은 무엇인가요?","options":[{"t":"시를 쓰는 과정 전체","correct":true},{"t":"시를 쓴 종이의 색깔","mis":"K6-2-u6-X19"},{"t":"시를 쓴 시간이 얼마나 짧은지","mis":"K6-2-u6-X17"},{"t":"시의 글자 수","mis":"K6-2-u6-X09"}],"explanation":["경험을 고르고 묻고 답하고 생각그물로 정리하는 과정도 중요해요.","완성된 시만 평가하지 않아요.","시를 쓰는 과정 전체를 함께 살펴요."],"asset":{"type":"passage","lines":["[활동지] 경험을 시로 창작하기","• 시로 표현하고 싶은 경험","• 생각이나 느낌","• 경험을 시로 창작하기"],"numbered":false,"title":"단원 마무리 활동지 — 경험을 시로 창작하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#18','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C28',3,'mc','auto','이야기를 바꾸어 쓴 것을 평가할 때 중점으로 살펴보는 것은 무엇인가요?',ARRAY['K6-2-u6-X36','K6-2-u6-X26','K6-2-u6-X35']::text[],false,'{"seq":18,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"이야기를 바꾸어 쓴 것을 평가할 때 중점으로 살펴보는 것은 무엇인가요?","options":[{"t":"인물·배경·사건 가운데 일부를 계획적으로 바꾸어 썼는지","correct":true},{"t":"인물, 배경, 사건을 모두 한꺼번에 바꾸었는지","mis":"K6-2-u6-X36"},{"t":"원래 이야기를 그대로 옮겨 썼는지","mis":"K6-2-u6-X26"},{"t":"글자 수가 원래 이야기보다 많은지","mis":"K6-2-u6-X35"}],"explanation":["이야기의 기본 요소를 알고 있는지 살펴요.","그 가운데에서 일부를 계획적으로 바꾸었는지 봐요.","어떤 부분에 자신의 경험을 녹였는지 설명하게 해요."],"asset":{"type":"passage","lines":["[활동지] 재미있게 읽은 이야기의 일부분을 바꾸어 쓰기","• 이야기의 원래 제목","• 바꾸어 쓰고 싶은 부분","• 제목 · 바꾸어 쓴 이야기","• 독자의 소감(독자 이름 · 재미있었거나 기억에 남는 부분 · 그 밖의 의견)"],"numbered":false,"title":"단원 마무리 활동지 — 이야기의 일부분을 바꾸어 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#19','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C26',3,'mc','auto','「알라딘과 신기한 램프」의 작가가 이야기를 이렇게 바꾼 까닭으로 짐작할 수 있는 것은 무엇인가요?',ARRAY['K6-2-u6-X32','K6-2-u6-X45','K6-2-u6-X26']::text[],false,'{"seq":19,"concept":"K6-2-u6-C26","difficulty":3,"kind":"mc","stem":"「알라딘과 신기한 램프」의 작가가 이야기를 이렇게 바꾼 까닭으로 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"보물과 권력보다 평화가 더 쓸모 있다는 새로운 생각을 전하려고","correct":true},{"t":"원래 이야기보다 글을 더 길게 만들려고","mis":"K6-2-u6-X32"},{"t":"알라딘을 아가씨로 바꾸어 성격을 정하려고","mis":"K6-2-u6-X45"},{"t":"원래 이야기를 그대로 다시 전하려고","mis":"K6-2-u6-X26"}],"explanation":["「작가는 어떤 의도로 이렇게 바꾸었을까요?」 하고 물어보아요.","알라딘은 보물 대신 전쟁을 없애는 소원을 골랐어요.","바꾼 부분에 작가가 전하고 싶은 생각이 담겨 있어요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#20','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C30',3,'error','auto','바꾸어 쓴 이야기를 돌려 읽고 친구들이 칭찬 쪽지를 썼어요. 칭찬 쪽지를 알맞게 쓰지 않은 친구는 누구인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X42']::text[],false,'{"seq":20,"concept":"K6-2-u6-C30","difficulty":3,"kind":"error","stem":"바꾸어 쓴 이야기를 돌려 읽고 친구들이 칭찬 쪽지를 썼어요. 칭찬 쪽지를 알맞게 쓰지 않은 친구는 누구인가요?","options":[{"t":"친구 3 — 「잘 썼다.」","correct":true,"mis_target":"K6-2-u6-X25"},{"t":"박○○ — 「인물의 성격을 반대로 바꾸니까 재미있었어.」","mis":"K6-2-u6-X42"},{"t":"신○○ — 「인물의 말과 행동이 실감 나게 표현되었어.」","mis":"K6-2-u6-X25"}],"explanation":["박○○과 신○○은 어느 부분이 좋았는지 밝혔어요.","친구 3은 막연하게 말했어요.","어느 부분이 왜 좋은지 구체적으로 써요."],"asset":{"type":"passage","lines":["[칭찬 쪽지] 박○○ — 인물의 성격을 반대로 바꾸니까 재미있었어.","[칭찬 쪽지] 이○○ — 예상하지 못한 결말이라서 놀랐어.","[칭찬 쪽지] 신○○ — 인물의 말과 행동이 실감 나게 표현되었어."],"numbered":false,"title":"칭찬 쪽지 예시 — 『국어』 291쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#21','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C25',3,'mc','auto','「옹고집전」을 바꾸어 쓸 아이디어가 자신의 경험과 어떻게 관련 있는지 설명한 말로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X46','K6-2-u6-X29','K6-2-u6-X26']::text[],false,'{"seq":21,"concept":"K6-2-u6-C25","difficulty":3,"kind":"mc","stem":"「옹고집전」을 바꾸어 쓸 아이디어가 자신의 경험과 어떻게 관련 있는지 설명한 말로 알맞은 것은 무엇인가요?","options":[{"t":"이야기의 장소를 우리가 다니고 있는 학교로 바꾸었다","correct":true},{"t":"주인공의 주장과 근거를 분명히 했다","mis":"K6-2-u6-X46"},{"t":"경험과 상관없이 하늘에서 우주선이 내려오게 했다","mis":"K6-2-u6-X29"},{"t":"원래 이야기를 한 글자도 바꾸지 않았다","mis":"K6-2-u6-X26"}],"explanation":["익숙한 장소로 바꾸면 경험이 이야기에 녹아들어요.","좋아하는 게임을 참고해 주인공을 바꿀 수도 있어요.","경험과 이어진 아이디어는 이야기를 생생하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#22','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C28',3,'mc','auto','『국어』 296쪽 스스로 확인하기에서 이야기를 쓰기 전에 계획하는 세부 사항으로 든 것은 무엇인가요?',ARRAY['K6-2-u6-X40','K6-2-u6-X46','K6-2-u6-X35']::text[],false,'{"seq":22,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"『국어』 296쪽 스스로 확인하기에서 이야기를 쓰기 전에 계획하는 세부 사항으로 든 것은 무엇인가요?","options":[{"t":"인물, 배경","correct":true},{"t":"표지 색깔, 글자 크기","mis":"K6-2-u6-X40"},{"t":"주장, 근거","mis":"K6-2-u6-X46"},{"t":"쪽수, 글자 수","mis":"K6-2-u6-X35"}],"explanation":["이야기를 쓰기 전에 인물, 배경 같은 세부 사항을 계획해요.","계획이 있어야 사건을 자연스럽게 이을 수 있어요.","겉모습은 이야기의 세부 사항이 아니에요."],"asset":{"type":"passage","lines":["• 자신의 경험을 떠올리며 형식을 갖추어 시를 쓸 수 있나요?","• 이야기를 쓰기 전에 인물, 배경과 같은 세부 사항을 계획할 수 있나요?","• 처음, 가운데, 끝의 내용을 생각하며 이야기를 쓸 수 있나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"스스로 확인하기 — 『국어』 296쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#23','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C12',4,'essay','teacher','시로 표현하고 싶은 경험을 정해 『국어』 265쪽처럼 본 것, 들은 것, 만진 것 가운데 두 가지와 그때의 생각이나 느낌을 쓰고, 그것을 바탕으로 시의 한 연을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u6-C12","difficulty":4,"kind":"essay","stem":"시로 표현하고 싶은 경험을 정해 『국어』 265쪽처럼 본 것, 들은 것, 만진 것 가운데 두 가지와 그때의 생각이나 느낌을 쓰고, 그것을 바탕으로 시의 한 연을 써 보세요.","answer_guide":{"answer":"예: 경험 — 운동회 줄다리기. 본 것 — 팽팽하게 당겨진 밧줄(손에 힘이 잔뜩 들어간다). 들은 것 — 친구들의 함성(힘이 난다). 시의 한 연 — 함성이 등을 민다 / 팽팽한 밧줄이 / 우리 반을 하나로 묶는다","scoring_points":["경험을 정하고 감각 갈래 두 가지를 썼는가","감각마다 생각이나 느낌을 이었는가","그 내용을 골라 시의 한 연으로 간결하게 썼는가"]},"explanation":["생각그물은 감각 갈래로 모아요.","감각에 생각이나 느낌을 이어 적어요.","그 가운데 인상 깊은 것을 골라 시로 써요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#24','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C29',4,'essay','teacher','「옹고집전」에서 인물의 성격이나 배경을 하나 바꾸어 이야기의 첫 문장과 제목을 지어 보세요. 그리고 그 첫 문장과 제목이 무엇이 바뀌었는지를 어떻게 드러내는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C29","difficulty":4,"kind":"essay","stem":"「옹고집전」에서 인물의 성격이나 배경을 하나 바꾸어 이야기의 첫 문장과 제목을 지어 보세요. 그리고 그 첫 문장과 제목이 무엇이 바뀌었는지를 어떻게 드러내는지 쓰세요.","answer_guide":{"answer":"예: 첫 문장 — 바닷가 마을 작은 식당의 주인 옹고집은 손님이 남긴 음식만 보아도 버럭 화를 내는 사람이었다. 제목 — 「식당 주인 옹고집」. 첫 문장에서 공간적 배경이 바닷가 마을 식당으로 바뀌었고, 옹고집의 고집 센 성격은 그대로 이어진다는 것을 알 수 있다. 제목도 바뀐 배경을 바로 보여 준다.","scoring_points":["바꿀 성격이나 배경을 정했는가","첫 문장에 바뀐 점이 드러나는가","제목이 바뀐 인물·배경·사건과 어울리는가"]},"explanation":["첫 문장은 무엇이 바뀌었는지 먼저 알려 줘요.","제목은 처음에 붙여도, 나중에 붙여도 돼요.","바꾼 인물·배경·사건을 생각해 제목을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_b#25','kor',6,2,'u6','','tb_g6_2_kor_u6_review_b','unit_review','K6-2-u6-C25',4,'essay','teacher','『국어』 295쪽 두 친구의 대화를 보기(시간·성격·사실·흥미·공간)의 말로 완성하고, 자신이 바꾸어 쓰고 싶은 이야기를 하나 정해 무엇을 어떻게 바꿀지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C25","difficulty":4,"kind":"essay","stem":"『국어』 295쪽 두 친구의 대화를 보기(시간·성격·사실·흥미·공간)의 말로 완성하고, 자신이 바꾸어 쓰고 싶은 이야기를 하나 정해 무엇을 어떻게 바꿀지 쓰세요.","answer_guide":{"answer":"예: ㉠ 성격, ㉡ 시간, ㉢ 공간이다. 나는 「옹고집전」의 공간적 배경을 우리 동네 아파트로 바꾸고 싶다. 옹고집은 이웃에게 심술궂게 구는 주민이 되고, 가짜 옹고집이 나타나 관리 사무소에서 진짜를 가리는 사건이 벌어질 것이다.","scoring_points":["㉠ 성격, ㉡·㉢ 시간·공간을 바르게 썼는가","바꿀 이야기와 요소를 정했는가","바뀐 요소에 따라 사건이 어떻게 달라질지 썼는가"]},"explanation":["인물을 바꿀 때에는 성격을 바꿀 수 있어요.","배경을 바꿀 때에는 시간이나 공간을 바꿔요.","바뀐 것에 따라 사건이 자연스럽게 달라져야 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 떠올리며 이야기를 바꾸어 쓰고 싶은데 어떤 것을 바꾸어 써야 할지 고민이야."},{"who":"친구 2","text":"네가 만나 본 사람들을 떠올리며 이야기에 등장하는 인물의 (  ㉠  )을/를 바꾸어 보는 건 어때?"},{"who":"친구 1","text":"아하! 욕심 많은 인물을 남들에게 베푸는 걸 좋아하는 인물로 바꾸는 것처럼 말이지?"},{"who":"친구 2","text":"응, (  ㉡  )(이)나 (  ㉢  )과/와 같은 이야기의 배경을 바꾸는 방법도 있어."},{"who":"친구 1","text":"그럼 나는 다른 나라 이야기의 배경을 우리나라로 바꾸어 써 봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#1','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C35',1,'ox','auto','「눈꺼풀」은 수업 시간에 졸렸던 경험을 시로 표현했어요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":1,"concept":"K6-2-u6-C35","difficulty":1,"kind":"ox","stem":"「눈꺼풀」은 수업 시간에 졸렸던 경험을 시로 표현했어요.","answer":"O","reason_options":[{"t":"축구를 한 뒤 도덕 시간에 눈꺼풀이 자꾸 내려온 일을 썼기 때문에","correct":true},{"t":"실제로 풀밭에서 무거운 풀을 들어 올린 일을 썼기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["『국어』 257쪽 2번의 친구 말과 같아요.","말하는 이는 수업 시간에 졸렸어요.","「무거운 풀」은 눈꺼풀을 빗댄 말이에요."],"asset":{"type":"passage","lines":["(간추림) 점심시간에 축구를 하고 들어온 뒤의 일이다.","5교시 도덕 시간","꾸벅 꾸우벅","소리 없이 내려오는","세상에서 가장 무거운 풀"],"numbered":false,"title":"「눈꺼풀」(오지연) 가운데 — 『국어』 256쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#2','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C36',1,'ox','auto','「그때부터였나 봐」의 말하는 이는 수업 종이 쳤는데 운동장만 내다보았어요.',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":2,"concept":"K6-2-u6-C36","difficulty":1,"kind":"ox","stem":"「그때부터였나 봐」의 말하는 이는 수업 종이 쳤는데 운동장만 내다보았어요.","answer":"O","reason_options":[{"t":"수빈이 생각이 자꾸 나서 수업에 마음을 두지 못했기 때문에","correct":true},{"t":"운동장에서 큰 사고가 나서 걱정했기 때문에","mis":"K6-2-u6-X07"}],"mis":"K6-2-u6-X07","explanation":["말하는 이는 가야 할 교실도 헷갈렸어요.","종이 쳐도 운동장만 내다보았어요.","모두 수빈이 생각이 자꾸 났기 때문이에요."],"asset":{"type":"passage","lines":["(간추림) 음악실에 가야 하는데 과학실에 가고, 종이 쳐도 운동장만 내다본다.","(간추림) 수학책을 꺼내라는데 수빈이가 찬 공이 굴러온다.","(간추림) 과학실에도 급식실에도, 건반과 곱셈 위에도 공이 쌓여 간다.","축구공이 수북이 쌓였어","(간추림) 눈을 감고 있어도 수빈이가 공을 몰고 다가온다."],"numbered":false,"title":"「그때부터였나 봐」(임수현) 뒷부분 — 『국어』 258~259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#3','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C7',1,'sa','auto','비슷한 현상이나 사물을 다른 것에 빗대어 표현하는 것을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C7","difficulty":1,"kind":"sa","stem":"비슷한 현상이나 사물을 다른 것에 빗대어 표현하는 것을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["비유적 표현","비유적표현"],"explanation":["『국어』 262쪽에서 배운 말이에요.","다른 것에 빗대어 표현하는 것이 비유적 표현이에요.","직유법과 은유법은 비유적 표현의 갈래예요."],"mis":"K6-2-u6-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#4','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C12',1,'sa','auto','『국어』 265쪽 생각그물에서 높이 날아가는 배드민턴공을 무엇에 빗대었나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u6-C12","difficulty":1,"kind":"sa","stem":"『국어』 265쪽 생각그물에서 높이 날아가는 배드민턴공을 무엇에 빗대었나요? 한 글자로 쓰세요.","answer":["새"],"explanation":["높이 날아가는 배드민턴공은 본 것이에요.","그 모습을 날아가는 새에 빗대었어요.","두 대상이 높이 나는 모습이 닮았어요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"},"mis":"K6-2-u6-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#5','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C18',1,'sa','auto','『국어』 268쪽 그림에서 시 낭송을 감상할 때 주의할 점을 지키지 않은 친구의 번호를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C18","difficulty":1,"kind":"sa","stem":"『국어』 268쪽 그림에서 시 낭송을 감상할 때 주의할 점을 지키지 않은 친구의 번호를 쓰세요.","answer":["⑤","5"],"explanation":["⑤는 감상하는 동안 옆 친구와 장난을 치고 있어요.","④와 ⑥은 바르게 감상하겠다고 다짐했어요.","감상할 때에는 집중해서 들어요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"},"mis":"K6-2-u6-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#6','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C38',1,'sa','auto','「알라딘과 요술 램프」에서 알라딘이 동굴에서 집으로 돌아가도록 도와준 것은 무엇의 요정인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C38","difficulty":1,"kind":"sa","stem":"「알라딘과 요술 램프」에서 알라딘이 동굴에서 집으로 돌아가도록 도와준 것은 무엇의 요정인가요? 두 글자로 쓰세요.","answer":["반지"],"explanation":["삼촌은 알라딘에게 반지를 건네주었어요.","동굴에 갇힌 알라딘이 반지를 문질렀어요.","반지 요정의 도움으로 무사히 집에 돌아갔어요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"},"mis":"K6-2-u6-X50"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#7','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C41',1,'sa','auto','『국어』 288쪽 보기에서 「별나고 괴상한 느낌이 있다.」라는 뜻을 가진 낱말을 찾아 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u6-C41","difficulty":1,"kind":"sa","stem":"『국어』 288쪽 보기에서 「별나고 괴상한 느낌이 있다.」라는 뜻을 가진 낱말을 찾아 쓰세요.","answer":["괴이쩍다"],"explanation":["사또는 똑같은 옹고집 두 명을 보고 괴이쩍게 여겼어요.","별나고 괴상한 느낌이 괴이쩍다예요.","보기의 낱말과 뜻을 하나씩 이어 보아요."],"asset":{"type":"passage","lines":["보기: 탄식하다 · 아뢰다 · 괴이쩍다 · 극진하다","● 어떤 대상에게 정성을 다하는 태도가 있다.","● 별나고 괴상한 느낌이 있다.","● 다른 사람에게 말씀드려서 알리다.","● 한탄하여 한숨을 쉬다."],"numbered":false,"title":"낱말 알기 — 『국어』 288쪽"},"mis":"K6-2-u6-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#8','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C34',1,'ox','auto','「놀이터를 거쳐 학교로 갔다.」는 알맞은 낱말을 골라 쓴 문장이에요.',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"ox","stem":"「놀이터를 거쳐 학교로 갔다.」는 알맞은 낱말을 골라 쓴 문장이에요.","answer":"O","reason_options":[{"t":"소리가 같은 ‘걷혀’가 아니라 문장의 뜻에 맞는 ‘거쳐’를 골랐기 때문에","correct":true},{"t":"소리가 같으면 ‘걷혀’라고 써도 뜻이 같기 때문에","mis":"K6-2-u6-X43"}],"mis":"K6-2-u6-X43","explanation":["『국어』 297쪽 2번의 문장이에요.","‘거쳐’와 ‘걷혀’는 소리가 같아요.","이 문장에는 ‘거쳐’가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#9','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C10',2,'ox','auto','시는 비유적 표현과 감각적 표현을 활용해 대상을 생생하게 나타내기도 해요.',ARRAY['K6-2-u6-X03']::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"ox","stem":"시는 비유적 표현과 감각적 표현을 활용해 대상을 생생하게 나타내기도 해요.","answer":"O","reason_options":[{"t":"빗대거나 감각을 살리면 표현하고 싶은 느낌이 더 생생해지기 때문에","correct":true},{"t":"두 표현을 되도록 많이 넣어야 시가 되기 때문에","mis":"K6-2-u6-X03"}],"mis":"K6-2-u6-X03","explanation":["비유적 표현은 느낌을 더 생생하게 나타내요.","감각적 표현도 경험을 생생하게 나타내요.","개수보다 알맞게 쓰는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#10','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C14',2,'mc','auto','『국어』 266쪽 글쓰기에서 제목에 대해 알려 준 말은 무엇인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":10,"concept":"K6-2-u6-C14","difficulty":2,"kind":"mc","stem":"『국어』 266쪽 글쓰기에서 제목에 대해 알려 준 말은 무엇인가요?","options":[{"t":"시에 담긴 마음을 잘 드러내는 제목을 정해 봐요.","correct":true},{"t":"시와 상관없이 멋진 말을 제목으로 정해 봐요.","mis":"K6-2-u6-X18"},{"t":"시에서 가장 긴 줄을 그대로 제목으로 옮겨 봐요.","mis":"K6-2-u6-X18"}],"explanation":["제목은 시에 담긴 마음을 드러내요.","읽는 사람은 제목을 보고 시를 만나요.","마음과 이어지는 제목을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#11','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',2,'ox','auto','시는 경험을 알려 주는 글이므로 낭송할 때 마음을 담지 않아도 돼요.',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":11,"concept":"K6-2-u6-C16","difficulty":2,"kind":"ox","stem":"시는 경험을 알려 주는 글이므로 낭송할 때 마음을 담지 않아도 돼요.","answer":"X","reason_options":[{"t":"시는 말하는 이의 마음을 담고 있어 그 마음이 전해지도록 낭송해야 하기 때문에","correct":true},{"t":"경험의 내용만 정확히 전하면 되기 때문에","mis":"K6-2-u6-X20"}],"mis":"K6-2-u6-X20","explanation":["시는 단순히 경험을 전달하는 글이 아니에요.","시에는 말하는 이의 마음이 담겨 있어요.","그 마음이 전해지도록 목소리와 속도를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#12','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C22',2,'ox','auto','「옹고집전」의 시간적 배경을 현대로 바꾸면 옹고집을 큰 회사 사장으로 바꿀 수 있어요.',ARRAY['K6-2-u6-X28']::text[],false,'{"seq":12,"concept":"K6-2-u6-C22","difficulty":2,"kind":"ox","stem":"「옹고집전」의 시간적 배경을 현대로 바꾸면 옹고집을 큰 회사 사장으로 바꿀 수 있어요.","answer":"O","reason_options":[{"t":"배경이 바뀌면 인물이 할 수 있는 일도 그 시대에 맞게 달라지기 때문에","correct":true},{"t":"배경과 인물이 하는 일은 서로 아무 상관이 없기 때문에","mis":"K6-2-u6-X28"}],"mis":"K6-2-u6-X28","explanation":["『국어』 290쪽 보기의 예예요.","시간적 배경이 현대가 되면 옹고집도 현대의 인물이 돼요.","배경과 인물, 사건은 함께 움직여요."],"asset":{"type":"passage","lines":["(1) 나는 주인공을 착한 성격으로 바꾸고 싶어.","(2) [보기] 옛날 어느 마을에 마음 착한 옹고집이 살았다.","옹고집은 큰 회사 사장이었다.","옹고집과 똑같이 생긴 사람이 나타나 자신이 진짜라고 주장했다.","(2) [예시] 다른 사람을 항상 배려하고 돕는 옹고집이 살았다.","옹고집은 남을 돕느라 몸이 열 개라도 부족할 정도로 바빴다.","도사가 나타나 옹고집에게 분신술을 알려 주었다.","옹고집은 몸을 둘로 나누어 다른 사람을 더 많이 돕고 살았다."],"numbered":false,"title":"「옹고집전」을 바꿀 계획 — 『국어』 290쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#13','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C25',2,'mc','auto','『국어』 295쪽 대화의 ㉡과 ㉢에 들어갈 말을 보기(시간·성격·사실·흥미·공간)에서 바르게 고른 것은 무엇인가요?',ARRAY['K6-2-u6-X31','K6-2-u6-X05']::text[],false,'{"seq":13,"concept":"K6-2-u6-C25","difficulty":2,"kind":"mc","stem":"『국어』 295쪽 대화의 ㉡과 ㉢에 들어갈 말을 보기(시간·성격·사실·흥미·공간)에서 바르게 고른 것은 무엇인가요?","options":[{"t":"시간 — 공간","correct":true},{"t":"사실 — 흥미","mis":"K6-2-u6-X31"},{"t":"성격 — 흥미","mis":"K6-2-u6-X05"},{"t":"사실 — 성격","mis":"K6-2-u6-X05"}],"explanation":["이야기의 배경에는 시간과 공간이 있어요.","친구는 다른 나라 이야기의 배경을 우리나라로 바꾸겠다고 했어요.","성격은 ㉠에 들어가는 말이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 떠올리며 이야기를 바꾸어 쓰고 싶은데 어떤 것을 바꾸어 써야 할지 고민이야."},{"who":"친구 2","text":"네가 만나 본 사람들을 떠올리며 이야기에 등장하는 인물의 (  ㉠  )을/를 바꾸어 보는 건 어때?"},{"who":"친구 1","text":"아하! 욕심 많은 인물을 남들에게 베푸는 걸 좋아하는 인물로 바꾸는 것처럼 말이지?"},{"who":"친구 2","text":"응, (  ㉡  )(이)나 (  ㉢  )과/와 같은 이야기의 배경을 바꾸는 방법도 있어."},{"who":"친구 1","text":"그럼 나는 다른 나라 이야기의 배경을 우리나라로 바꾸어 써 봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#14','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C27',2,'sa','auto','「옹고집전」의 흐름 가운데 진짜와 가짜가 싸우고 사또가 판결하는 부분을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K6-2-u6-C27","difficulty":2,"kind":"sa","stem":"「옹고집전」의 흐름 가운데 진짜와 가짜가 싸우고 사또가 판결하는 부분을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["절정"],"explanation":["발단, 전개, 절정의 차례로 이야기가 흘러가요.","갈등이 가장 커지는 곳이 절정이에요.","진짜 옹고집이 쫓겨나는 재판 장면이 절정이에요."],"asset":{"type":"passage","lines":["발단 — 옛날에 고집 세고 심술궂은 옹고집이 살았다.","전개 — 걸인을 몽둥이질해 쫓아냈고, 도사는 짚으로 가짜 옹고집을 만들었다.","절정 — 진짜와 가짜가 싸웠고, 사또가 진짜를 가짜라고 판결해 쫓겨났다.","결말 — 떠돌며 고생한 진짜 옹고집은 뉘우치고 돌아와 착하게 살았다."],"numbered":false,"title":"「옹고집전」 사건의 흐름 — 『국어』 289쪽"},"mis":"K6-2-u6-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#15','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C42',2,'mc','auto','「양말 한 짝」의 「기회를 틈타 양말은 사라진다」라는 표현이 재미있는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X04','K6-2-u6-X03']::text[],false,'{"seq":15,"concept":"K6-2-u6-C42","difficulty":2,"kind":"mc","stem":"「양말 한 짝」의 「기회를 틈타 양말은 사라진다」라는 표현이 재미있는 까닭은 무엇인가요?","options":[{"t":"양말을 몰래 빠져나가는 사람처럼 표현했기 때문","correct":true},{"t":"양말이 사라진 날짜를 정확히 적었기 때문","mis":"K6-2-u6-X09"},{"t":"어려운 말로 빨래 과정을 설명했기 때문","mis":"K6-2-u6-X04"},{"t":"빗댄 표현을 되도록 많이 넣었기 때문","mis":"K6-2-u6-X03"}],"explanation":["양말은 스스로 움직일 수 없어요.","그런데 기회를 틈타 사라진다고 했어요.","양말을 사람처럼 나타내 경험이 재미있게 느껴져요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#16','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C32',2,'ox','auto','경험을 바탕으로 쓴 이야기는 일기처럼 겪은 일을 그대로만 써야 해요.',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":16,"concept":"K6-2-u6-C32","difficulty":2,"kind":"ox","stem":"경험을 바탕으로 쓴 이야기는 일기처럼 겪은 일을 그대로만 써야 해요.","answer":"X","reason_options":[{"t":"경험을 바탕으로 인물·배경·사건을 상상해 바꾸어 쓰는 글이기 때문에","correct":true},{"t":"지어낸 내용이 들어가면 경험을 쓴 글이 아니기 때문에","mis":"K6-2-u6-X31"}],"mis":"K6-2-u6-X31","explanation":["경험한 일을 쓴 글은 사실이에요.","경험을 바탕으로 쓴 이야기는 허구예요.","그래서 일기나 생활문과는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#17','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C6',3,'error','auto','「경험을 시로 창작하기」 활동지로 시를 쓰기 전에 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X15','K6-2-u6-X02']::text[],false,'{"seq":17,"concept":"K6-2-u6-C6","difficulty":3,"kind":"error","stem":"「경험을 시로 창작하기」 활동지로 시를 쓰기 전에 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「경험한 일을 아침부터 저녁까지 빠짐없이 다 적어야 생생한 시가 돼.」","correct":true,"mis_target":"K6-2-u6-X09"},{"t":"친구 1 — 「시로 표현하고 싶은 경험과 그때의 생각이나 느낌을 먼저 적어 볼래.」","mis":"K6-2-u6-X15"},{"t":"친구 2 — 「특별한 일이 아니어도 일상 속 경험을 시로 쓸 수 있어.」","mis":"K6-2-u6-X02"}],"explanation":["이 활동지는 경험과 생각이나 느낌을 먼저 적게 해요.","일상 속 경험도 시가 돼요.","경험을 모두 쓰지 않고 인상 깊은 것을 골라 간결하게 써요."],"asset":{"type":"passage","lines":["[활동지] 경험을 시로 창작하기","• 시로 표현하고 싶은 경험","• 생각이나 느낌","• 경험을 시로 창작하기"],"numbered":false,"title":"단원 마무리 활동지 — 경험을 시로 창작하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#18','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C25',3,'error','auto','「이야기의 일부분을 바꾸어 쓰기」 활동지로 이야기를 바꾸어 쓰며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X48','K6-2-u6-X32','K6-2-u6-X31']::text[],false,'{"seq":18,"concept":"K6-2-u6-C25","difficulty":3,"kind":"error","stem":"「이야기의 일부분을 바꾸어 쓰기」 활동지로 이야기를 바꾸어 쓰며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「책에서 읽은 일은 내 경험이 아니니까 이야기에 넣을 수 없어.」","correct":true,"mis_target":"K6-2-u6-X48"},{"t":"친구 1 — 「원래 이야기의 어느 부분을 왜 바꾸었는지 발표할 거야.」","mis":"K6-2-u6-X32"},{"t":"친구 2 — 「경험에 너무 얽매이지 않고 자유롭게 상상해도 돼.」","mis":"K6-2-u6-X31"}],"explanation":["직접 경험과 간접 경험이 모두 글에 반영될 수 있어요.","경험에 너무 얽매이지 않고 자유롭게 상상해도 돼요.","어느 부분을 왜 바꾸었는지 발표할 수 있어야 해요."],"asset":{"type":"passage","lines":["[활동지] 재미있게 읽은 이야기의 일부분을 바꾸어 쓰기","• 이야기의 원래 제목","• 바꾸어 쓰고 싶은 부분","• 제목 · 바꾸어 쓴 이야기","• 독자의 소감(독자 이름 · 재미있었거나 기억에 남는 부분 · 그 밖의 의견)"],"numbered":false,"title":"단원 마무리 활동지 — 이야기의 일부분을 바꾸어 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#19','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C26',3,'ox','auto','옛이야기를 바꾸어 쓰면 원래 이야기에 없던 새로운 뜻이 생길 수 있어요.',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":19,"concept":"K6-2-u6-C26","difficulty":3,"kind":"ox","stem":"옛이야기를 바꾸어 쓰면 원래 이야기에 없던 새로운 뜻이 생길 수 있어요.","answer":"O","reason_options":[{"t":"바뀐 인물의 말과 선택이 새로운 생각을 보여 주기 때문에","correct":true},{"t":"바꾸어 쓰는 까닭은 글을 길게 늘이는 데 있기 때문에","mis":"K6-2-u6-X32"}],"mis":"K6-2-u6-X32","explanation":["「착한 옹고집의 분신술」은 분신술을 돕는 일로 바꾸었어요.","흑설 공주 이야기의 왕비는 질투하지 않았어요.","바뀐 곳에서 새로운 뜻이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#20','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C18',3,'mc','auto','친구의 시 낭송을 감상하고 쓴 잘한 점 가운데 가장 구체적인 것은 무엇인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X21','K6-2-u6-X24']::text[],false,'{"seq":20,"concept":"K6-2-u6-C18","difficulty":3,"kind":"mc","stem":"친구의 시 낭송을 감상하고 쓴 잘한 점 가운데 가장 구체적인 것은 무엇인가요?","options":[{"t":"감각적 표현을 사용해 경험을 시로 재미있게 표현했어.","correct":true},{"t":"좋았어. 다음에도 잘하면 좋겠어.","mis":"K6-2-u6-X25"},{"t":"목소리가 무척 커서 그것만 기억나.","mis":"K6-2-u6-X21"},{"t":"틀린 데가 하나도 없이 끝까지 읽었어.","mis":"K6-2-u6-X24"}],"explanation":["『국어』 269쪽 점검하기 (1)의 예시 답안이에요.","무엇이 어떻게 좋았는지 밝혀 써요.","크기나 틀린 데보다 표현과 마음을 보아요."],"asset":{"type":"passage","lines":["[친구의 시 낭송을 감상하고 잘한 점]","서연 — 배경 음악과 시가 어울려서 시의 장면이 생생하게 떠올랐어.","동욱 — 감각적 표현을 사용해 경험을 시로 재미있게 표현했어."],"numbered":false,"title":"친구의 시 낭송 감상하기 — 『국어』 269쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#21','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C32',3,'ox','auto','경험한 일을 쓴 글은 사실이고, 경험을 바탕으로 쓴 이야기는 허구예요.',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":21,"concept":"K6-2-u6-C32","difficulty":3,"kind":"ox","stem":"경험한 일을 쓴 글은 사실이고, 경험을 바탕으로 쓴 이야기는 허구예요.","answer":"O","reason_options":[{"t":"이야기는 경험을 바탕으로 상상한 내용을 더해 만든 글이기 때문에","correct":true},{"t":"경험을 바탕으로 썼다면 이야기도 모두 사실이어야 하기 때문에","mis":"K6-2-u6-X31"}],"mis":"K6-2-u6-X31","explanation":["경험한 일을 쓴 글은 사실 그대로예요.","경험을 바탕으로 쓴 이야기는 상상이 더해진 허구예요.","이 차이를 알면 이야기를 더 자유롭게 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#22','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C28',3,'ox','auto','이야기를 쓸 때에는 처음, 가운데, 끝의 내용을 생각하며 써요.',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":22,"concept":"K6-2-u6-C28","difficulty":3,"kind":"ox","stem":"이야기를 쓸 때에는 처음, 가운데, 끝의 내용을 생각하며 써요.","answer":"O","reason_options":[{"t":"처음, 가운데, 끝이 자연스럽게 이어져야 하기 때문에","correct":true},{"t":"가장 재미있는 장면만 쓰면 되기 때문에","mis":"K6-2-u6-X29"}],"mis":"K6-2-u6-X29","explanation":["『국어』 296쪽 스스로 확인하기 물음이에요.","이야기는 처음, 가운데, 끝으로 이어져요.","앞뒤가 자연스럽게 이어지게 써요."],"asset":{"type":"passage","lines":["• 자신의 경험을 떠올리며 형식을 갖추어 시를 쓸 수 있나요?","• 이야기를 쓰기 전에 인물, 배경과 같은 세부 사항을 계획할 수 있나요?","• 처음, 가운데, 끝의 내용을 생각하며 이야기를 쓸 수 있나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"스스로 확인하기 — 『국어』 296쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#23','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C13',4,'essay','teacher','자신이 쓴 시를 고쳐 쓴다고 생각하고, 『국어』 266쪽 수정하기처럼 시의 특성에 비추어 확인할 점을 세 가지 쓰세요. 그리고 그 가운데 하나를 어떻게 고칠지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u6-C13","difficulty":4,"kind":"essay","stem":"자신이 쓴 시를 고쳐 쓴다고 생각하고, 『국어』 266쪽 수정하기처럼 시의 특성에 비추어 확인할 점을 세 가지 쓰세요. 그리고 그 가운데 하나를 어떻게 고칠지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 확인할 점은 첫째, 장면이 바뀌는 곳에서 연과 행을 나누었는가, 둘째, 경험을 모두 쓰지 않고 인상 깊었던 것만 골라 간결하게 썼는가, 셋째, 비유적 표현이나 감각적 표현으로 마음을 생생하게 나타냈는가이다. 예를 들어 「땀이 많이 났다」를 「비처럼 쏟아지는 땀」으로 고치겠다.","scoring_points":["시의 특성에 맞는 확인할 점을 세 가지 썼는가","겉모습(글씨·길이)이 아닌 표현을 살폈는가","고칠 예를 구체적으로 들었는가"]},"explanation":["고쳐 쓰기는 시의 특성이 잘 드러나는지 확인하는 일이에요.","연과 행, 간결함, 비유적·감각적 표현을 살펴요.","고칠 곳은 구체적인 예로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#24','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',4,'essay','teacher','「알라딘과 요술 램프」에서 알라딘의 성격을 바꾸어 이어질 사건을 상상해 보세요. 바꾼 성격을 쓰고, 그 성격 때문에 달라지는 사건 두 가지를 원인과 결과가 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C23","difficulty":4,"kind":"essay","stem":"「알라딘과 요술 램프」에서 알라딘의 성격을 바꾸어 이어질 사건을 상상해 보세요. 바꾼 성격을 쓰고, 그 성격 때문에 달라지는 사건 두 가지를 원인과 결과가 드러나게 쓰세요.","answer_guide":{"answer":"예: 알라딘을 겁이 많지만 정직한 성격으로 바꾸겠다. 알라딘은 삼촌이라는 남자가 이상하다고 느껴 어머니께 솔직하게 말씀드린다. 그래서 어머니와 함께 남자를 따라가지 않고, 남자는 혼자 동굴로 들어갔다가 램프를 찾지 못하고 돌아간다.","scoring_points":["바꾼 성격을 분명히 썼는가","그 성격이 인물의 말과 행동을 바꾸었는가","두 사건이 원인과 결과로 이어지는가"]},"explanation":["성격이 바뀌면 인물의 말과 행동이 바뀌어요.","바뀐 행동이 다음 사건의 원인이 돼요.","앞의 일과 이어지지 않는 갑작스러운 사건은 피해요."],"asset":{"type":"passage","lines":["(간추림) 낯선 남자가 자신이 알라딘의 삼촌이라며 다가왔다.","(간추림) 귀한 선물을 가져오고 말을 잘하며 친절해 삼촌이라고 믿게 되었다.","(간추림) 동굴에서 램프를 먼저 내놓으라는 말을 거절하자 남자는 돌문을 닫았다.","(간추림) 그는 못된 마법사였고, 알라딘은 반지 요정 덕분에 집에 왔다.","(간추림) 옷자락으로 램프의 먼지를 닦자 램프의 요정 지니가 나타났다.","(간추림) 알라딘은 먹을 것을 얻고, 부자가 되고 싶다고 해 보물을 얻었다."],"numbered":false,"title":"「알라딘과 요술 램프」(글 ㉮) 간추림 — 『국어』 270~274쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_c#25','kor',6,2,'u6','','tb_g6_2_kor_u6_review_c','unit_review','K6-2-u6-C10',4,'essay','teacher','이 단원에서 공부한 내용을 정리하세요. 경험을 시로 쓸 때 생각할 점 두 가지와, 경험을 떠올리며 이야기를 바꾸어 쓸 때 생각할 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C10","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 내용을 정리하세요. 경험을 시로 쓸 때 생각할 점 두 가지와, 경험을 떠올리며 이야기를 바꾸어 쓸 때 생각할 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 시로 쓸 때에는 경험을 모두 쓰지 않고 인상 깊었던 것을 골라 연과 행으로 나누어 간결하게 쓴다. 또 비유적 표현이나 감각적 표현을 활용해 생각이나 느낌을 생생하게 나타낸다. 이야기를 바꾸어 쓸 때에는 자신의 경험을 바탕으로 인물이나 배경을 바꾸어 본다. 또 원인과 결과를 생각하며 처음, 가운데, 끝이 자연스럽게 이어지도록 쓴다.","scoring_points":["시를 쓸 때 생각할 점 두 가지를 썼는가","이야기를 바꾸어 쓸 때 생각할 점 두 가지를 썼는가","단원에서 배운 말(연과 행·비유·감각·인물·배경·원인과 결과)로 정리했는가"]},"explanation":["시는 간결하게, 연과 행으로, 생생한 표현으로 써요.","이야기는 경험을 바탕으로 인물이나 배경을 바꾸어요.","사건은 원인과 결과로 자연스럽게 이어요."],"asset":{"type":"passage","lines":["● 이야기를 바꾸어 쓸 때에는 자신의 경험을 바탕으로 인물이나 배경을 바꾸어 본다.","● 이야기를 바꾸어 쓸 때에는 처음, 가운데, 끝으로 자연스럽게 이어지도록 한다.","● 시를 쓸 때 비유적 표현이나 감각적 표현을 활용할 수 있다."],"numbered":false,"title":"이 단원에서 공부한 내용 정리 — 『국어』 296쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#1','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C1',1,'mc','auto','『국어』 255쪽 생각 열기에서 남학생은 무엇을 하고 있나요?',ARRAY['K6-2-u6-X26','K6-2-u6-X01','K6-2-u6-X04']::text[],false,'{"seq":1,"concept":"K6-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 255쪽 생각 열기에서 남학생은 무엇을 하고 있나요?","options":[{"t":"경험을 떠올리며 글을 쓰고 있다","correct":true},{"t":"책을 그대로 베껴 쓰고 있다","mis":"K6-2-u6-X26"},{"t":"글씨 연습만 하고 있다","mis":"K6-2-u6-X01"},{"t":"어려운 낱말을 외우고 있다","mis":"K6-2-u6-X04"}],"explanation":["생각 열기는 단원의 문을 여는 장면이에요.","남학생은 경험을 떠올리며 글을 쓰고 있어요.","경험을 떠올리면 시나 이야기를 생생하게 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#2','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C36',1,'mc','auto','「그때부터였나 봐」에서 말하는 이가 가야 했던 곳과 실제로 간 곳을 바르게 말한 것은 무엇인가요?',ARRAY['K6-2-u6-X50','K6-2-u6-X07']::text[],false,'{"seq":2,"concept":"K6-2-u6-C36","difficulty":1,"kind":"mc","stem":"「그때부터였나 봐」에서 말하는 이가 가야 했던 곳과 실제로 간 곳을 바르게 말한 것은 무엇인가요?","options":[{"t":"음악실에 가야 하는데 과학실에 갔다","correct":true},{"t":"과학실에 가야 하는데 음악실에 갔다","mis":"K6-2-u6-X50"},{"t":"급식실에 가야 하는데 운동장에 갔다","mis":"K6-2-u6-X07"}],"explanation":["시의 둘째 연에 나오는 장면이에요.","말하는 이는 음악실에 가야 했어요.","수빈이 생각에 과학실로 가 버렸어요."],"asset":{"type":"passage","lines":["(간추림) 음악실에 가야 하는데 과학실에 가고, 종이 쳐도 운동장만 내다본다.","(간추림) 수학책을 꺼내라는데 수빈이가 찬 공이 굴러온다.","(간추림) 과학실에도 급식실에도, 건반과 곱셈 위에도 공이 쌓여 간다.","축구공이 수북이 쌓였어","(간추림) 눈을 감고 있어도 수빈이가 공을 몰고 다가온다."],"numbered":false,"title":"「그때부터였나 봐」(임수현) 뒷부분 — 『국어』 258~259쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#3','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C8',1,'ox','auto','‘듯이’를 써서 두 대상을 직접 비교하는 것은 은유법이에요.',ARRAY['K6-2-u6-X11']::text[],false,'{"seq":3,"concept":"K6-2-u6-C8","difficulty":1,"kind":"ox","stem":"‘듯이’를 써서 두 대상을 직접 비교하는 것은 은유법이에요.","answer":"X","reason_options":[{"t":"‘같이’, ‘처럼’, ‘듯이’로 직접 비교하면 직유법이기 때문에","correct":true},{"t":"‘듯이’는 ‘……은 ……이다’와 같은 말이기 때문에","mis":"K6-2-u6-X11"}],"mis":"K6-2-u6-X11","explanation":["‘듯이’는 직접 비교하는 말이에요.","직접 비교하면 직유법이에요.","은유법은 ‘……은/는 ……(이)다’처럼 빗대요."],"asset":{"type":"passage","lines":["비슷한 현상이나 사물을 다른 것에 빗대어 표현하는 것을 비유적 표현이라고 해요.","‘같이’, ‘처럼’, ‘듯이’를 써서 두 대상을 직접 비교하면 직유법,","‘……은/는 ……(이)다’처럼 빗대어 표현하면 은유법이에요."],"title":"비유적 표현 — 『국어』 262~263쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#4','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C12',1,'ox','auto','『국어』 265쪽 생각그물에서 「이마의 땀」은 만진 것에 들어가요.',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C12","difficulty":1,"kind":"ox","stem":"『국어』 265쪽 생각그물에서 「이마의 땀」은 만진 것에 들어가요.","answer":"O","reason_options":[{"t":"손이나 몸에 닿아 느낀 것이기 때문에","correct":true},{"t":"눈으로 본 것은 모두 만진 것이기 때문에","mis":"K6-2-u6-X12"}],"mis":"K6-2-u6-X12","explanation":["이마의 땀은 몸에 닿아 느낀 것이에요.","그래서 만진 것 칸에 적었어요.","본 것, 들은 것, 만진 것을 구별해요."],"asset":{"type":"passage","lines":["[가운데] 배드민턴을 친 경험","본 것 — 서브 넣을 때 파르르 떨리는 배드민턴공","→ 생각이나 느낌: 서브가 넘어갈 수 있을지 긴장됩니다.","들은 것 — 파이팅! / 친구들의 응원 소리 → 힘이 납니다.","본 것 — 높이 날아가는 배드민턴공 → 비유적 표현: 날아가는 새","만진 것 — 이마의 땀 → 비유적 표현: 비처럼 쏟아지는 땀","들은 것 — 톡 / 탁 공을 치는 소리 → 경쾌한 느낌이 납니다."],"numbered":false,"title":"경험을 생각그물로 정리하기 — 『국어』 265쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#5','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C19',1,'ox','auto','③처럼 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽으면 시의 리듬이 잘 살아요.',ARRAY['K6-2-u6-X47']::text[],false,'{"seq":5,"concept":"K6-2-u6-C19","difficulty":1,"kind":"ox","stem":"③처럼 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽으면 시의 리듬이 잘 살아요.","answer":"X","reason_options":[{"t":"시의 분위기에 어울리는 목소리와 속도로 리듬을 살려 읽어야 하기 때문에","correct":true},{"t":"한 글자씩 읽어야 듣는 사람이 정확히 알아듣기 때문에","mis":"K6-2-u6-X47"}],"mis":"K6-2-u6-X47","explanation":["끊어 읽으면 시의 리듬이 끊겨요.","연과 행의 리듬을 살려 이어 읽어요.","분위기에 맞는 목소리와 속도를 찾아요."],"asset":{"type":"passage","lines":["[그림] 시 낭송회 — 앞에 선 세 친구와 앉아서 듣는 세 친구","① 「축구공을 차는…….」 하고 아주 작은 소리로 읽는다.","② 종이를 들고 서 있다.","③ 「그, 랬, 어, 요.」 하고 한 글자씩 끊어 읽는다.","④ 「집중해서 들어야지.」","⑤ 옆 친구와 장난을 치고 있다.","⑥ 「시와 관련 있는 경험을 떠올리며 감상해야지.」"],"numbered":false,"title":"시 낭송회 장면 — 『국어』 268쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#6','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C39',1,'ox','auto','「알라딘과 신기한 램프」의 지니는 알라딘의 소원을 듣고 익숙하지 않은 일이라며 놀랐어요.',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":6,"concept":"K6-2-u6-C39","difficulty":1,"kind":"ox","stem":"「알라딘과 신기한 램프」의 지니는 알라딘의 소원을 듣고 익숙하지 않은 일이라며 놀랐어요.","answer":"O","reason_options":[{"t":"이전의 주인들은 적을 물리치거나 부와 권력을 원했기 때문에","correct":true},{"t":"지니는 평화를 가장 잘 만드는 요정이었기 때문에","mis":"K6-2-u6-X07"}],"mis":"K6-2-u6-X07","explanation":["지니는 평화는 자기 전공이 아니라고 했어요.","이전 주인들과 전혀 다른 소원이었기 때문이에요.","그래도 지니는 힘을 주어 소원을 이루었어요."],"asset":{"type":"passage","lines":["(간추림) 알라딘은 보물 대신 집으로 데려다 달라고 했다.","(간추림) 그 보물은 많은 사람이 피 흘린 대가로 얻은 것이었다.","(간추림) 지니는 궁전과 노예, 다이아몬드 드레스, 왕자 비 자리를 권했다.","(간추림) 알라딘은 귀족은 가난한 사람들을 억압한다며 거절했다.","“난 더 쓸모 있는 것을 원해요.”","(간추림) 알라딘은 전쟁을 없애고 무기를 사라지게 해 달라고 했다.","(간추림) 지니는 놀랐지만 온 힘을 주어 소원을 이루어 주었다."],"numbered":false,"title":"「알라딘과 신기한 램프」(바버라 G. 워커 글, 박혜란 옮김, 글 ㉯) 간추림 — 『국어』 274~278쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#7','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C40',1,'ox','auto','「옹고집전」에서 사또는 가족에 대해 막힘없이 대답한 쪽을 진짜 옹고집이라고 판결했어요.',ARRAY['K6-2-u6-X50']::text[],false,'{"seq":7,"concept":"K6-2-u6-C40","difficulty":1,"kind":"ox","stem":"「옹고집전」에서 사또는 가족에 대해 막힘없이 대답한 쪽을 진짜 옹고집이라고 판결했어요.","answer":"O","reason_options":[{"t":"진짜는 아들 나이도 답하지 못했고, 가짜는 가족을 막힘없이 말했기 때문에","correct":true},{"t":"진짜 옹고집이 가족을 가장 잘 알고 대답했기 때문에","mis":"K6-2-u6-X50"}],"mis":"K6-2-u6-X50","explanation":["사또는 가족에 대해 아는 대로 말해 보라고 했어요.","가짜 옹고집이 막힘없이 대답했어요.","그래서 사또는 가짜를 진짜라고 판결했어요."],"asset":{"type":"passage","lines":["(간추림) 가짜 옹고집이 집에 들어와 주인 행세를 하자 진짜와 다투었다.","(간추림) 부인도 하인도 둘을 가려내지 못해 사또 앞에 서게 되었다.","(간추림) 가족을 묻자 진짜는 제대로 답하지 못하고 가짜는 막힘없이 답했다.","(간추림) 진짜 옹고집은 곤장을 맞고 쫓겨나 떠돌아다니는 신세가 되었다."],"numbered":false,"title":"「옹고집전」 가운데 부분 간추림 — 『국어』 284~285쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#8','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C34',1,'sa','auto','「뜨거운 죽을 (    ).」의 빈칸에 ‘시켰다’와 ‘식혔다’ 가운데 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"sa","stem":"「뜨거운 죽을 (    ).」의 빈칸에 ‘시켰다’와 ‘식혔다’ 가운데 알맞은 말을 쓰세요.","answer":["식혔다"],"explanation":["『국어』 297쪽 3번 예시 답안의 문장이에요.","뜨거운 죽은 식혀요.","심부름은 ‘시키다’를 써요."],"mis":"K6-2-u6-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#9','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C10',2,'match','auto','시의 특성과 그 특성이 주는 효과를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"match","stem":"시의 특성과 그 특성이 주는 효과를 알맞게 이으세요.","pairs":[{"l":"연과 행으로 나누어 읽기","r":"리듬감을 느낄 수 있다"},{"l":"비유적 표현","r":"표현하고 싶은 느낌을 더 생생하게 나타낸다"},{"l":"짧은 글로 압축하기","r":"생각이나 느낌을 간결하게 담는다"}],"mis":"K6-2-u6-X13","explanation":["『국어』 263쪽 7번에서 시의 특성을 이야기했어요.","연과 행은 리듬, 비유는 생생함, 압축은 간결함과 이어져요.","특성은 규칙이 아니라 마음을 잘 전하는 방법이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"시는 자신의 생각이나 느낌을 짧은 글로 압축해서 쓴 글이야. 연과 행으로 나누어 읽을 때 리듬감을 느낄 수 있어."},{"who":"친구 2","text":"비유적 표현을 활용해서 시를 쓴 사람이 표현하고 싶은 느낌을 더 생생하게 나타내기도 해."},{"who":"친구 3","text":"감각적 표현을 활용하여 생생하게 표현할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#10','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C11',2,'ox','auto','시로 표현할 경험은 특별한 경험이 아니어도 돼요.',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":10,"concept":"K6-2-u6-C11","difficulty":2,"kind":"ox","stem":"시로 표현할 경험은 특별한 경험이 아니어도 돼요.","answer":"O","reason_options":[{"t":"일상생활 속 경험도 시로 표현할 수 있기 때문에","correct":true},{"t":"특별한 경험이어야 읽는 사람이 감동하기 때문에","mis":"K6-2-u6-X02"}],"mis":"K6-2-u6-X02","explanation":["배드민턴을 친 경험도 좋은 시가 돼요.","일상생활 속 경험도 시로 표현할 수 있어요.","경험에 대한 생각이나 느낌을 솔직하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#11','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C17',2,'match','auto','『국어』 267쪽 예시 답안에서 마음을 잘 전달하는 방법과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K6-2-u6-C17","difficulty":2,"kind":"match","stem":"『국어』 267쪽 예시 답안에서 마음을 잘 전달하는 방법과 그 예를 알맞게 이으세요.","pairs":[{"l":"효과음","r":"심장 박동 소리"},{"l":"배경 음악","r":"긴장감이 고조되는 음악"},{"l":"영상","r":"시와 어울리는 영상"}],"mis":"K6-2-u6-X22","explanation":["효과음, 배경 음악, 영상으로 마음을 전할 수 있어요.","모두 시의 분위기에 어울려야 해요.","목소리보다 크거나 화려하지 않게 써요."],"asset":{"type":"passage","lines":["(1) 전하고 싶은 마음 — 배드민턴 서브를 넣기 전 긴장되는 마음","(2) 목소리 — 공이 그물을 넘어가기를 바라는 간절한 목소리,","공이 튀어 오를 때에는 경쾌한 목소리","(2) 속도 — 서브를 넣기 전까지는 숨을 내쉬면서 느린 속도,","공이 그물 위를 오고 갈 때에는 빠른 속도","(3) 다른 방법 — 심장 박동 소리 같은 효과음 · 긴장감이 고조되는 음악","· 시와 어울리는 영상"],"numbered":false,"title":"시 낭송 계획 예시 — 『국어』 267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#12','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C21',2,'mc','auto','『국어』 295쪽 대화에서 욕심 많은 인물을 남들에게 베푸는 걸 좋아하는 인물로 바꾸는 것은 무엇을 바꾼 것인가요?',ARRAY['K6-2-u6-X05','K6-2-u6-X31']::text[],false,'{"seq":12,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"『국어』 295쪽 대화에서 욕심 많은 인물을 남들에게 베푸는 걸 좋아하는 인물로 바꾸는 것은 무엇을 바꾼 것인가요?","options":[{"t":"인물의 성격","correct":true},{"t":"이야기의 시간","mis":"K6-2-u6-X05"},{"t":"이야기의 공간","mis":"K6-2-u6-X05"},{"t":"겪은 일의 사실","mis":"K6-2-u6-X31"}],"explanation":["친구는 만나 본 사람들을 떠올리며 바꾸자고 했어요.","욕심 많음에서 베풀기 좋아함으로 바뀐 것은 성격이에요.","시간과 공간은 이야기의 배경이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"경험을 떠올리며 이야기를 바꾸어 쓰고 싶은데 어떤 것을 바꾸어 써야 할지 고민이야."},{"who":"친구 2","text":"네가 만나 본 사람들을 떠올리며 이야기에 등장하는 인물의 (  ㉠  )을/를 바꾸어 보는 건 어때?"},{"who":"친구 1","text":"아하! 욕심 많은 인물을 남들에게 베푸는 걸 좋아하는 인물로 바꾸는 것처럼 말이지?"},{"who":"친구 2","text":"응, (  ㉡  )(이)나 (  ㉢  )과/와 같은 이야기의 배경을 바꾸는 방법도 있어."},{"who":"친구 1","text":"그럼 나는 다른 나라 이야기의 배경을 우리나라로 바꾸어 써 봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#13','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C24',2,'ox','auto','이야기를 바꾸어 쓸 때에는 엉뚱하고 갑작스러운 사건이 계속 일어나야 재미있어요.',ARRAY['K6-2-u6-X30']::text[],false,'{"seq":13,"concept":"K6-2-u6-C24","difficulty":2,"kind":"ox","stem":"이야기를 바꾸어 쓸 때에는 엉뚱하고 갑작스러운 사건이 계속 일어나야 재미있어요.","answer":"X","reason_options":[{"t":"하나의 사건이 일어나면 그에 알맞은 마무리가 있어야 이야기가 자연스럽기 때문에","correct":true},{"t":"놀라운 일이 많을수록 잘 바꾼 이야기이기 때문에","mis":"K6-2-u6-X30"}],"mis":"K6-2-u6-X30","explanation":["사건은 원인과 결과로 촘촘하게 짜여요.","엉뚱한 사건이 계속되면 이야기가 끊겨요.","기발하게 바꾸는 것만이 재미있게 바꾸는 방법은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#14','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C40',2,'mc','auto','「옹고집전」에서 옹고집이 다시 집에 돌아왔을 때 가짜가 있던 방에 남아 있던 것은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X50']::text[],false,'{"seq":14,"concept":"K6-2-u6-C40","difficulty":2,"kind":"mc","stem":"「옹고집전」에서 옹고집이 다시 집에 돌아왔을 때 가짜가 있던 방에 남아 있던 것은 무엇인가요?","options":[{"t":"지푸라기 인형 하나","correct":true},{"t":"도사의 지팡이","mis":"K6-2-u6-X07"},{"t":"사또의 판결문","mis":"K6-2-u6-X07"},{"t":"가짜 옹고집","mis":"K6-2-u6-X50"}],"explanation":["가짜 옹고집은 도사가 짚으로 만든 인형이었어요.","진짜 옹고집이 뉘우치고 돌아오자 가짜는 사라졌어요.","방에는 지푸라기 인형 하나만 누워 있었어요."],"asset":{"type":"passage","lines":["(간추림) 몇 해 뒤 깊은 산속에서 두견새 울음을 듣고 잃어버린 것을 깨달았다.","“부끄럽구나. 나는 불효막심한 자식에, 못난 남편, 못난 아비였다.”","(간추림) 도사 앞에 엎드려 뉘우치자 도사는 돌아가 개과천선하라고 했다.","(간추림) 집에 돌아오니 가짜가 있던 방에는 지푸라기 인형 하나뿐이었다.","(간추림) 그 뒤 옹고집은 효도하고 가족에게 극진히 대하며 착한 일을 했다."],"numbered":false,"title":"「옹고집전」 뒷부분 간추림 — 『국어』 286~287쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#15','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C42',2,'sa','auto','「양말 한 짝」은 어떤 경험을 시로 표현했나요? 「양말 한 짝이 (    ) 경험」의 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u6-C42","difficulty":2,"kind":"sa","stem":"「양말 한 짝」은 어떤 경험을 시로 표현했나요? 「양말 한 짝이 (    ) 경험」의 빈칸에 알맞은 말을 쓰세요.","answer":["사라진"],"explanation":["『국어』 294쪽 1번 (1)의 예시 답안이에요.","양말 한 짝이 자꾸 사라져요.","양말 한 짝이 사라진 경험을 시로 표현했어요."],"asset":{"type":"passage","lines":["세탁기에서 나올 때","기회를 틈타 양말은 사라진다","한 짝만 사라져도","두 짝 다 사라진 거다"],"title":"「양말 한 짝」(김세희) 가운데 — 『국어』 294쪽"},"mis":"K6-2-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#16','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C31',2,'mc','auto','『국어』 292쪽에서 학급 이야기책을 완성하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X39','K6-2-u6-X41']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"『국어』 292쪽에서 학급 이야기책을 완성하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"학급 온라인 게시판에 올린 이야기들을 모아 책으로 만든다","correct":true},{"t":"혼자만 보고 친구들에게는 보여 주지 않는다","mis":"K6-2-u6-X39"},{"t":"표지만 화려하게 꾸미고 글은 나중에 쓴다","mis":"K6-2-u6-X41"}],"explanation":["넷째 단계에서 이야기를 게시판에 올려요.","다섯째 단계에서 친구들의 이야기를 모아 책으로 만들어요.","표지를 만들어 책을 완성하고 함께 나눠요."],"asset":{"type":"passage","lines":["① 학급에서 만들고 싶은 이야기책 형태 정하기","(소리를 녹음한 오디오 북 · 프레젠테이션 프로그램으로 만든 책)","② 쓰고 싶은 이야기의 중심 사건, 등장인물, 배경 정하기","③ 사건의 전개 과정을 간단히 써 보기","④ 매체를 활용해 이야기를 만들고 학급 온라인 게시판에 올리기","⑤ 반 친구들의 이야기를 모아 이야기책으로 만들기"],"numbered":false,"title":"매체를 활용한 학급 이야기책 만들기 — 『국어』 292쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#17','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C11',3,'mc','auto','시로 쓸 경험을 정하는 단계에서부터 어려워하는 친구에게 해 줄 도움으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X09','K6-2-u6-X03']::text[],false,'{"seq":17,"concept":"K6-2-u6-C11","difficulty":3,"kind":"mc","stem":"시로 쓸 경험을 정하는 단계에서부터 어려워하는 친구에게 해 줄 도움으로 알맞은 것은 무엇인가요?","options":[{"t":"일상생활 속 경험도 시로 표현할 수 있음을 알려 준다","correct":true},{"t":"특별한 경험이 생길 때까지 기다리게 한다","mis":"K6-2-u6-X02"},{"t":"경험을 길게 설명하는 글을 대신 쓰게 한다","mis":"K6-2-u6-X09"},{"t":"빗댄 표현을 먼저 많이 외우게 한다","mis":"K6-2-u6-X03"}],"explanation":["시로 쓸 경험을 고르기 어려워하는 친구가 있을 수 있어요.","일상생활 속 경험도 좋은 시의 재료예요.","먼저 말로 자유롭게 표현해 보게 해도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#18','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C28',3,'mc','auto','「이야기의 일부분을 바꾸어 쓰기」 활동지에서 바꾸어 쓸 이야기와 부분을 정하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X35','K6-2-u6-X36']::text[],false,'{"seq":18,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"「이야기의 일부분을 바꾸어 쓰기」 활동지에서 바꾸어 쓸 이야기와 부분을 정하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"재미있게 읽은 이야기의 제목과 줄거리를 떠올리고, 바꾸어 쓰고 싶은 부분을 구체적으로 정한다","correct":true},{"t":"줄거리를 모르는 낯선 이야기를 골라 새롭게 쓴다","mis":"K6-2-u6-X30"},{"t":"바꾸고 싶은 부분을 정하지 않고 바로 길게 쓴다","mis":"K6-2-u6-X35"},{"t":"인물, 배경, 사건을 모두 바꿀 수 있는 이야기만 고른다","mis":"K6-2-u6-X36"}],"explanation":["먼저 재미있게 읽은 이야기를 떠올려요.","제목과 줄거리를 떠올리고 바꾸고 싶은 부분을 정해요.","자신의 독서 경험에 맞게 이야기를 골라도 돼요."],"asset":{"type":"passage","lines":["[활동지] 재미있게 읽은 이야기의 일부분을 바꾸어 쓰기","• 이야기의 원래 제목","• 바꾸어 쓰고 싶은 부분","• 제목 · 바꾸어 쓴 이야기","• 독자의 소감(독자 이름 · 재미있었거나 기억에 남는 부분 · 그 밖의 의견)"],"numbered":false,"title":"단원 마무리 활동지 — 이야기의 일부분을 바꾸어 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#19','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C26',3,'mc','auto','『국어』 280쪽에서 인물이 어떤 말을 하고 어떤 선택을 하는지 주의 깊게 살펴보면 무엇을 짐작할 수 있다고 했나요?',ARRAY['K6-2-u6-X35','K6-2-u6-X07']::text[],false,'{"seq":19,"concept":"K6-2-u6-C26","difficulty":3,"kind":"mc","stem":"『국어』 280쪽에서 인물이 어떤 말을 하고 어떤 선택을 하는지 주의 깊게 살펴보면 무엇을 짐작할 수 있다고 했나요?","options":[{"t":"이야기에 담겨 있는 주제","correct":true},{"t":"책의 쪽수","mis":"K6-2-u6-X35"},{"t":"이야기의 글자 수","mis":"K6-2-u6-X35"},{"t":"작가가 사는 곳","mis":"K6-2-u6-X07"}],"explanation":["인물의 말과 선택에는 이야기의 생각이 담겨 있어요.","글 ㉯의 알라딘이 고른 소원에서 주제를 짐작할 수 있어요.","인물과 배경도 함께 살펴보아요."],"asset":{"type":"passage","lines":["글 ㉮ ① 반지 요정의 도움으로 램프를 가지고 집으로 돌아옴.","② 지니가 나타나 소원을 들어주겠다고 말함.","③ 배가 고프다고 하자 지니가 음식을 차려 줌.","④ 부자가 되고 싶다는 소원을 빌고, 보석과 보물을 얻음.","글 ㉯ ① 지니의 도움으로 융단을 타고 집으로 돌아옴.","② 지니가 부와 권력을 얻게 해 주겠다고 권함.","③ 그런 소원은 빌고 싶지 않다고 말함.","④ 전쟁을 없애고 무기를 사라지게 해 달라고 빌고, 이루어짐."],"numbered":false,"title":"요술 램프를 가지게 된 뒤 사건 전개 — 『국어』 280쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#20','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C30',3,'ox','auto','친구의 이야기를 돌려 읽고 칭찬 쪽지를 쓸 때에는 어느 부분이 왜 좋았는지 써요.',ARRAY['K6-2-u6-X25']::text[],false,'{"seq":20,"concept":"K6-2-u6-C30","difficulty":3,"kind":"ox","stem":"친구의 이야기를 돌려 읽고 칭찬 쪽지를 쓸 때에는 어느 부분이 왜 좋았는지 써요.","answer":"O","reason_options":[{"t":"구체적인 칭찬이 친구에게 무엇을 잘했는지 알려 주기 때문에","correct":true},{"t":"칭찬은 짧고 막연할수록 부담이 없기 때문에","mis":"K6-2-u6-X25"}],"mis":"K6-2-u6-X25","explanation":["『국어』 291쪽 공유하기 활동이에요.","어느 부분이 왜 좋았는지 써요.","구체적인 칭찬은 다음 글쓰기에 힘이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#21','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C25',3,'error','auto','「옹고집전」을 바꾸어 쓰며 친구들이 아이디어와 경험을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X48','K6-2-u6-X31','K6-2-u6-X28']::text[],false,'{"seq":21,"concept":"K6-2-u6-C25","difficulty":3,"kind":"error","stem":"「옹고집전」을 바꾸어 쓰며 친구들이 아이디어와 경험을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 3 — 「나는 「손톱 먹은 쥐」를 읽기만 했으니 그 이야기는 경험으로 쓸 수 없어.」","correct":true,"mis_target":"K6-2-u6-X48"},{"t":"친구 1 — 「내가 좋아하는 게임을 참고해서 주인공을 바꾸었어.」","mis":"K6-2-u6-X31"},{"t":"친구 2 — 「이야기의 장소를 우리가 다니는 학교로 바꾸었어.」","mis":"K6-2-u6-X28"}],"explanation":["읽거나 들은 이야기도 간접 경험이에요.","비슷한 이야기를 떠올리면 아이디어가 생겨요.","좋아하는 것이나 익숙한 장소도 경험과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#22','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C1',3,'mc','auto','이 단원에서 한 활동의 궁극적인 목적으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X02','K6-2-u6-X04']::text[],false,'{"seq":22,"concept":"K6-2-u6-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 한 활동의 궁극적인 목적으로 알맞은 것은 무엇인가요?","options":[{"t":"생각이나 느낌을 나누고 자신의 이야기를 쓰며 글쓰기와 읽기의 즐거움을 느끼는 것","correct":true},{"t":"친구들보다 더 길고 멋진 시를 써서 칭찬받는 것","mis":"K6-2-u6-X01"},{"t":"누구도 겪지 못한 대단한 경험을 찾아내 쓰는 것","mis":"K6-2-u6-X02"},{"t":"어렵고 멋있어 보이는 표현을 많이 외워 두는 것","mis":"K6-2-u6-X04"}],"explanation":["경험을 떠올리는 것은 창작을 쉽게 시작하려는 것이에요.","이 단원의 목표는 새로운 시나 이야기를 창작하는 것이에요.","그 과정에서 글쓰기와 읽기의 즐거움을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#23','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C16',4,'essay','teacher','이 단원에서 읽은 시 가운데 한 편을 골라 낭송 계획을 세우세요. 전하고 싶은 마음, 장면에 어울리는 목소리와 속도, 마음을 전하는 다른 방법과 그때 주의할 점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u6-C16","difficulty":4,"kind":"essay","stem":"이 단원에서 읽은 시 가운데 한 편을 골라 낭송 계획을 세우세요. 전하고 싶은 마음, 장면에 어울리는 목소리와 속도, 마음을 전하는 다른 방법과 그때 주의할 점을 쓰세요.","answer_guide":{"answer":"예: 「그때부터였나 봐」를 고르겠다. 전하고 싶은 마음은 수빈이 생각이 자꾸 나서 설레는 마음이다. 「축구공만 데굴데굴 굴러와」는 통통 튀는 밝은 목소리로 조금 빠르게, 마지막 연은 꿈꾸듯 느리게 읽겠다. 공이 굴러가는 효과음을 넣되 목소리보다 작게 하겠다.","scoring_points":["전하고 싶은 마음을 정했는가","장면에 따라 목소리와 속도를 다르게 계획했는가","효과음·음악·영상을 목소리보다 크지 않게 쓰는 점을 썼는가"]},"explanation":["먼저 시에 담긴 마음을 정해요.","장면마다 어울리는 목소리와 속도를 찾아요.","효과음은 돕는 만큼만, 목소리보다 작게 써요."],"asset":{"type":"passage","lines":["(1) 전하고 싶은 마음 — 배드민턴 서브를 넣기 전 긴장되는 마음","(2) 목소리 — 공이 그물을 넘어가기를 바라는 간절한 목소리,","공이 튀어 오를 때에는 경쾌한 목소리","(2) 속도 — 서브를 넣기 전까지는 숨을 내쉬면서 느린 속도,","공이 그물 위를 오고 갈 때에는 빠른 속도","(3) 다른 방법 — 심장 박동 소리 같은 효과음 · 긴장감이 고조되는 음악","· 시와 어울리는 영상"],"numbered":false,"title":"시 낭송 계획 예시 — 『국어』 267쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#24','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C30',4,'essay','teacher','「알라딘과 신기한 램프」를 친구가 바꾸어 쓴 이야기라고 생각하고, 「이야기의 일부분을 바꾸어 쓰기」 활동지의 독자의 소감 칸을 채우세요. 재미있었거나 기억에 남는 부분과 그 까닭, 그 밖의 의견을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C30","difficulty":4,"kind":"essay","stem":"「알라딘과 신기한 램프」를 친구가 바꾸어 쓴 이야기라고 생각하고, 「이야기의 일부분을 바꾸어 쓰기」 활동지의 독자의 소감 칸을 채우세요. 재미있었거나 기억에 남는 부분과 그 까닭, 그 밖의 의견을 쓰세요.","answer_guide":{"answer":"예: 재미있었던 부분은 알라딘이 지니가 권한 궁전과 왕자 비 자리를 거절하는 장면이다. 원래 이야기와 달리 욕심 없는 알라딘이 전쟁을 없애 달라고 해서 새로웠다. 그 밖의 의견으로, 무기가 사라진 뒤 사람들이 어떻게 살았는지 이어지는 이야기도 읽어 보고 싶다.","scoring_points":["기억에 남는 부분을 구체적으로 짚었는가","그 까닭을 썼는가","그 밖의 의견을 정중하고 구체적으로 썼는가"]},"explanation":["독자의 소감은 글쓴이에게 힘이 돼요.","어느 부분이 왜 기억에 남는지 구체적으로 써요.","바라는 점도 정중하게 덧붙여요."],"asset":{"type":"passage","lines":["[활동지] 재미있게 읽은 이야기의 일부분을 바꾸어 쓰기","• 이야기의 원래 제목","• 바꾸어 쓰고 싶은 부분","• 제목 · 바꾸어 쓴 이야기","• 독자의 소감(독자 이름 · 재미있었거나 기억에 남는 부분 · 그 밖의 의견)"],"numbered":false,"title":"단원 마무리 활동지 — 이야기의 일부분을 바꾸어 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u6_review_d#25','kor',6,2,'u6','','tb_g6_2_kor_u6_review_d','unit_review','K6-2-u6-C1',4,'essay','teacher','『국어』 296쪽 스스로 확인하기 물음 세 가지 가운데 가장 자신 있는 것과 더 노력할 것을 하나씩 골라 까닭을 쓰고, 앞으로 경험을 시나 이야기로 표현하며 실천할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C1","difficulty":4,"kind":"essay","stem":"『국어』 296쪽 스스로 확인하기 물음 세 가지 가운데 가장 자신 있는 것과 더 노력할 것을 하나씩 골라 까닭을 쓰고, 앞으로 경험을 시나 이야기로 표현하며 실천할 일을 쓰세요.","answer_guide":{"answer":"예: 가장 자신 있는 것은 「자신의 경험을 떠올리며 형식을 갖추어 시를 쓸 수 있나요?」이다. 생각그물로 정리한 뒤 연과 행으로 나누어 쓸 수 있게 되었기 때문이다. 더 노력할 것은 「처음, 가운데, 끝의 내용을 생각하며 이야기를 쓸 수 있나요?」이다. 가운데 부분에서 사건이 갑자기 바뀌곤 했기 때문이다. 앞으로 일주일에 한 번 겪은 일을 짧은 시로 쓰고, 읽은 이야기의 끝을 바꾸어 써 보겠다.","scoring_points":["자신 있는 것과 노력할 것을 골랐는가","각각의 까닭을 솔직하게 썼는가","실천할 일을 구체적으로 썼는가"]},"explanation":["스스로 확인하기는 시와 이야기 쓰기를 모두 돌아봐요.","잘한 점과 부족한 점을 함께 살펴요.","생활 속에서 실천할 일을 정해요."],"asset":{"type":"passage","lines":["• 자신의 경험을 떠올리며 형식을 갖추어 시를 쓸 수 있나요?","• 이야기를 쓰기 전에 인물, 배경과 같은 세부 사항을 계획할 수 있나요?","• 처음, 가운데, 끝의 내용을 생각하며 이야기를 쓸 수 있나요?","매우 잘함: ●●● · 잘함: ●● · 보통임: ●"],"numbered":false,"title":"스스로 확인하기 — 『국어』 296쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
